window.COURT_DATA = {"gameName": "Yea or Nay: Split Decision", "epoch": "2026-08-12", "puzzles": [{"id": "texas-v-johnson", "era": "The Rehnquist Court \u00b7 October Term 1988", "caseTitle": "Texas v. Johnson", "question": "May the government punish burning the American flag as political protest?", "desc": "Gregory Lee Johnson burned the flag while protesters chanted 'America, the red, white, and blue, we spit on you.' Texas convicted him under its venerated-objects law: a year in jail and a $2,000 fine. No one was hurt; a great many were offended. Texas says the flag is a unique national symbol the state may protect. Johnson says torching it was pure political expression. Forty-eight states ban flag desecration, and the veterans' groups are watching.", "intro": "Outside the 1984 Republican National Convention in Dallas, a demonstrator douses an American flag in kerosene and sets it alight. Five years later the flag, the First Amendment, and the national temper arrive at the Court together.", "decided": "June 21, 1989", "split": "5\u20134", "answer": "no", "justices": [{"key": "rehnquist88", "name": "William Rehnquist", "meta": "Nixon appointee (R)", "blurb": "Elevated to Chief Justice in 1986 after fifteen years as the Court's lone-wolf conservative dissenter. A states'-rights man with a genial, poker-playing manner, he now assigns the opinions and works to move the Court rightward without splintering his majorities.", "photo": "photos/rehnquist88.jpg", "chief": true}, {"key": "brennan", "name": "William Brennan", "meta": "Eisenhower appointee (R)", "blurb": "The aging architect of the Warren Court's rights revolution, now 83 and often outnumbered. The Court's great coalition-builder \u2014 'five votes can do anything around here' \u2014 he still hunts for a fifth vote wherever one can be found.", "photo": "photos/brennan.jpg"}, {"key": "white", "name": "Byron White", "meta": "Kennedy appointee (D)", "blurb": "A Kennedy appointee and former NFL halfback, gruff and unsentimental. He defies every label: hard on criminal defendants, skeptical of newly minted rights, steady on civil rights. He writes short opinions and asks no one's permission.", "photo": "photos/white.jpg"}, {"key": "marshall", "name": "Thurgood Marshall", "meta": "Lyndon Johnson appointee (D)", "blurb": "The lawyer who argued Brown v. Board of Education, now the Court's most unwavering liberal. He votes against every death sentence and speaks for the poor and powerless \u2014 increasingly in dissent, side by side with his ally Brennan.", "photo": "photos/marshall.jpg"}, {"key": "blackmun", "name": "Harry Blackmun", "meta": "Nixon appointee (R)", "blurb": "The Nixon appointee who wrote Roe v. Wade and has drifted left ever since, marked by the backlash. A meticulous former counsel to the Mayo Clinic, sensitive and deliberate, now usually found alongside Brennan and Marshall.", "photo": "photos/blackmun.jpg"}, {"key": "stevens88", "name": "John Paul Stevens", "meta": "Ford appointee (R)", "blurb": "A Ford appointee and Chicago antitrust lawyer with a bow tie and a ferociously independent streak. He follows his own analysis wherever it leads, scattering solo opinions along the way \u2014 unpredictable by design and beholden to no bloc.", "photo": "photos/stevens88.jpg"}, {"key": "oconnor88", "name": "Sandra Day O'Connor", "meta": "Reagan appointee (R)", "blurb": "The first woman on the Court, a former Arizona legislative leader who judges the way she once governed: case by case, fact by fact, wary of sweeping rules. Increasingly she is the justice both sides must persuade.", "photo": "photos/oconnor88.jpg"}, {"key": "scalia88", "name": "Antonin Scalia", "meta": "Reagan appointee (R)", "blurb": "Reagan's combative textualist, three terms on the bench and already the Court's sharpest pen. He reads constitutional text at face value wherever it points \u2014 and delights in skewering colleagues who balance interests instead.", "photo": "photos/scalia88.jpg"}, {"key": "kennedy88", "name": "Anthony Kennedy", "meta": "Reagan appointee (R)", "blurb": "The newest justice, a courtly Sacramento conservative confirmed unanimously after the Bork nomination went down in flames. Expected to be a dependable Reagan vote, but given to grand talk about liberty and the dignity of the individual.", "photo": "photos/kennedy88.jpg"}], "votes": {"rehnquist88": "yes", "brennan": "no", "white": "yes", "marshall": "no", "blackmun": "no", "stevens88": "yes", "oconnor88": "yes", "scalia88": "no", "kennedy88": "no"}}, {"id": "dc-v-heller", "era": "The Roberts Court \u00b7 October Term 2007", "caseTitle": "District of Columbia v. Heller", "question": "Does the Second Amendment protect an individual's right to keep a handgun at home, apart from militia service?", "desc": "Dick Heller carries a gun all day guarding the Federal Judicial Center \u2014 and cannot legally keep one at home under Washington's 1976 handgun ban, the strictest in America. His lawsuit asks what the amendment's tangled clauses actually promise: a militia's collective prerogative, or an individual's right? Both sides come armed with founding-era history, and every gun law in the country is watching. Even some conservatives fear what an honest answer might unleash.", "intro": "A security guard in the nation's capital wants to keep his revolver at home. The Court has not squarely read the Second Amendment in nearly seventy years \u2014 and must now decide what 'a well regulated Militia' has to do with it.", "decided": "June 26, 2008", "split": "5\u20134", "answer": "yes", "justices": [{"key": "roberts", "name": "John Roberts", "meta": "George W. Bush appointee (R)", "blurb": "The chief justice who won the job promising to call balls and strikes, not pitch or bat. A polished Supreme Court advocate turned umpire, he prefers narrow rulings and unanimity where he can get them \u2014 and moves the law by patient inches when he can't.", "photo": "photos/roberts.jpg", "chief": true}, {"key": "stevens_roberts", "name": "John Paul Stevens", "meta": "Ford appointee (R)", "blurb": "The senior associate justice, pushing ninety and sharper than ever: a bow-tied Republican antitrust lawyer appointed by Gerald Ford who became the anchor of the Court's liberal wing. He insists the Court moved, not him.", "photo": "photos/stevens_roberts.jpg"}, {"key": "scalia_roberts", "name": "Antonin Scalia", "meta": "Reagan appointee (R)", "blurb": "Originalism's happy warrior, decades into his crusade to read the Constitution as its ratifiers understood it. His opinions are the Court's best copy, his scorn for 'living constitutionalism' legendary \u2014 and his method has reshaped how every case is argued.", "photo": "photos/scalia_roberts.jpg"}, {"key": "kennedy_roberts", "name": "Anthony Kennedy", "meta": "Reagan appointee (R)", "blurb": "The swing. A courtly Sacramento Republican who controls the outcome in nearly every close case \u2014 and knows it. Liberty and dignity are his lodestars, sweeping language his signature, suspense his permanent gift to Court-watchers.", "photo": "photos/kennedy_roberts.jpg"}, {"key": "souter_roberts", "name": "David Souter", "meta": "George H. W. Bush appointee (R)", "blurb": "A frugal New Hampshire Yankee named by the first President Bush as a 'home run' for conservatives \u2014 who drifted steadily toward the Court's left instead. Skeptical of grand theories, devoted to precedent and to history's complications.", "photo": "photos/souter_roberts.jpg"}, {"key": "thomas_roberts", "name": "Clarence Thomas", "meta": "George H. W. Bush appointee (R)", "blurb": "The Court's most uncompromising originalist, fearless in print: he will discard decades of precedent without apology and stake out positions entirely alone, serenely confident the law will someday catch up to him.", "photo": "photos/thomas_roberts.jpg"}, {"key": "ginsburg_roberts", "name": "Ruth Bader Ginsburg", "meta": "Clinton appointee (D)", "blurb": "The pioneering women's-rights litigator of the 1970s, now the liberal wing's most exacting technician. Small, quiet, and precise, she picks her battles carefully \u2014 and reads her fiercest dissents aloud from the bench when she loses one.", "photo": "photos/ginsburg_roberts.jpg"}, {"key": "breyer_roberts", "name": "Stephen Breyer", "meta": "Clinton appointee (D)", "blurb": "The Court's pragmatist professor: a former Senate staffer and administrative-law scholar who judges by consequences, not grand theory. Endlessly optimistic about government, allergic to absolutes, and famous for winding hypotheticals that leave lawyers blinking.", "photo": "photos/breyer_roberts.jpg"}, {"key": "alito", "name": "Samuel Alito", "meta": "George W. Bush appointee (R)", "blurb": "A former federal prosecutor from New Jersey, methodical and unflashy, with the most reliably conservative instincts on the bench \u2014 above all where crime, religion, or the culture wars are concerned. In dissent, his pen turns acid.", "photo": "photos/alito.jpg"}], "votes": {"roberts": "yes", "stevens_roberts": "no", "scalia_roberts": "yes", "kennedy_roberts": "yes", "souter_roberts": "no", "thomas_roberts": "yes", "ginsburg_roberts": "no", "breyer_roberts": "no", "alito": "yes"}}, {"id": "citizens-united", "era": "The Roberts Court \u00b7 October Term 2009", "caseTitle": "Citizens United v. FEC", "question": "May the government limit corporations' independent spending on political speech in candidate elections?", "desc": "Hillary: The Movie is a ninety-minute case against Hillary Clinton's fitness for the presidency \u2014 and because it was made with corporate money, McCain-Feingold bars it from the airwaves close to an election. Citizens United, the nonprofit behind it, sued. At the first argument the government's lawyer conceded its logic might even reach banning books \u2014 and the Court took the rare step of scheduling a September reargument on whether decades of restrictions on corporate political money should survive at all. The foundations of campaign-finance law are on the table.", "intro": "A conservative nonprofit made a ninety-minute film attacking Hillary Clinton and was told it couldn't air during primary season. The Court ordered the case reargued \u2014 a signal it may reach far beyond one movie.", "decided": "January 21, 2010", "split": "5\u20134", "answer": "no", "justices": [{"key": "roberts", "name": "John Roberts", "meta": "George W. Bush appointee (R)", "blurb": "The chief justice who won the job promising to call balls and strikes, not pitch or bat. A polished Supreme Court advocate turned umpire, he prefers narrow rulings and unanimity where he can get them \u2014 and moves the law by patient inches when he can't.", "photo": "photos/roberts.jpg", "chief": true}, {"key": "stevens_roberts", "name": "John Paul Stevens", "meta": "Ford appointee (R)", "blurb": "The senior associate justice, pushing ninety and sharper than ever: a bow-tied Republican antitrust lawyer appointed by Gerald Ford who became the anchor of the Court's liberal wing. He insists the Court moved, not him.", "photo": "photos/stevens_roberts.jpg"}, {"key": "scalia_roberts", "name": "Antonin Scalia", "meta": "Reagan appointee (R)", "blurb": "Originalism's happy warrior, decades into his crusade to read the Constitution as its ratifiers understood it. His opinions are the Court's best copy, his scorn for 'living constitutionalism' legendary \u2014 and his method has reshaped how every case is argued.", "photo": "photos/scalia_roberts.jpg"}, {"key": "kennedy_roberts", "name": "Anthony Kennedy", "meta": "Reagan appointee (R)", "blurb": "The swing. A courtly Sacramento Republican who controls the outcome in nearly every close case \u2014 and knows it. Liberty and dignity are his lodestars, sweeping language his signature, suspense his permanent gift to Court-watchers.", "photo": "photos/kennedy_roberts.jpg"}, {"key": "thomas_roberts", "name": "Clarence Thomas", "meta": "George H. W. Bush appointee (R)", "blurb": "The Court's most uncompromising originalist, fearless in print: he will discard decades of precedent without apology and stake out positions entirely alone, serenely confident the law will someday catch up to him.", "photo": "photos/thomas_roberts.jpg"}, {"key": "ginsburg_roberts", "name": "Ruth Bader Ginsburg", "meta": "Clinton appointee (D)", "blurb": "The pioneering women's-rights litigator of the 1970s, now the liberal wing's most exacting technician. Small, quiet, and precise, she picks her battles carefully \u2014 and reads her fiercest dissents aloud from the bench when she loses one.", "photo": "photos/ginsburg_roberts.jpg"}, {"key": "breyer_roberts", "name": "Stephen Breyer", "meta": "Clinton appointee (D)", "blurb": "The Court's pragmatist professor: a former Senate staffer and administrative-law scholar who judges by consequences, not grand theory. Endlessly optimistic about government, allergic to absolutes, and famous for winding hypotheticals that leave lawyers blinking.", "photo": "photos/breyer_roberts.jpg"}, {"key": "alito", "name": "Samuel Alito", "meta": "George W. Bush appointee (R)", "blurb": "A former federal prosecutor from New Jersey, methodical and unflashy, with the most reliably conservative instincts on the bench \u2014 above all where crime, religion, or the culture wars are concerned. In dissent, his pen turns acid.", "photo": "photos/alito.jpg"}, {"key": "sotomayor", "name": "Sonia Sotomayor", "meta": "Obama appointee (D)", "blurb": "From a Bronx housing project to Princeton to the federal trial bench: the first Latina justice never lets the Court forget how doctrine lands on actual people. A former prosecutor, relentless at argument, the liberal wing's most passionate voice.", "photo": "photos/sotomayor.jpg"}], "votes": {"roberts": "no", "stevens_roberts": "yes", "scalia_roberts": "no", "kennedy_roberts": "no", "thomas_roberts": "no", "ginsburg_roberts": "yes", "breyer_roberts": "yes", "alito": "no", "sotomayor": "yes"}}, {"id": "loving-v-virginia", "era": "The Warren Court \u00b7 October Term 1966", "caseTitle": "Loving v. Virginia", "question": "May a state criminalize marriage between people of different races?", "desc": "Virginia's Racial Integrity Act of 1924 makes the Lovings' marriage a felony, and fifteen other states still enforce laws like it. The trial judge wrote that God 'did not intend for the races to mix.' Exiled to Washington, the Lovings want to go home to Caroline County. Virginia argues its law punishes both spouses equally and therefore discriminates against no one \u2014 the same arithmetic that once sustained separate-but-equal. Mildred's letter to Robert Kennedy started the case; the ACLU has carried it here.", "intro": "Richard and Mildred Loving married in Washington, then were arrested in their Virginia bedroom at 2 a.m. The sentence: a year in jail, suspended if they leave the state for twenty-five.", "decided": "June 12, 1967", "split": "9\u20130", "answer": "no", "justices": [{"key": "warren", "name": "Earl Warren", "meta": "Eisenhower appointee (R)", "blurb": "The former California governor, now the most consequential Chief Justice in a century. He asks lawyers one question \u2014 'But is it fair?' \u2014 and works the conference like the politician he never stopped being.", "photo": "photos/warren.jpg", "chief": true}, {"key": "black", "name": "Hugo Black", "meta": "Franklin Roosevelt appointee (D)", "blurb": "An Alabama New Dealer who carries the Constitution in his coat pocket and reads it literally. 'No law' means no law \u2014 but rights he cannot find in the text, he will not invent.", "photo": "photos/black.jpg"}, {"key": "douglas", "name": "William O. Douglas", "meta": "Franklin Roosevelt appointee (D)", "blurb": "A restless westerner and the Court's fastest pen \u2014 impatient with doctrine, indifferent to precedent, and instinctively on the side of the lone individual against the government in nearly any form it takes.", "photo": "photos/douglas.jpg"}, {"key": "clark", "name": "Tom C. Clark", "meta": "Truman appointee (D)", "blurb": "Truman's Attorney General in a trademark bow tie \u2014 the Court's law-and-order Texan. He backs the police and the prosecutor by instinct, but he ran federal law enforcement himself and knows its temptations from the inside.", "photo": "photos/clark.jpg"}, {"key": "harlan", "name": "John Marshall Harlan", "meta": "Eisenhower appointee (R)", "blurb": "The Wall Street patrician and grandson of a great dissenter \u2014 the Court's conservative conscience. He believes in ordered liberty and lawyerly process, and objects, elegantly, when the majority moves too far, too fast.", "photo": "photos/harlan.jpg"}, {"key": "brennan", "name": "William Brennan", "meta": "Eisenhower appointee (R)", "blurb": "The Court's Irish charmer and master coalition-builder, an Eisenhower appointee who turned out to be its most effective liberal. His first rule of the shop: with five votes, you can do anything.", "photo": "photos/brennan.jpg"}, {"key": "stewart", "name": "Potter Stewart", "meta": "Eisenhower appointee (R)", "blurb": "A moderate Ohio Republican who resists both blocs' grand theories. He decides cases one at a time, asks what the Constitution actually commands, and lands \u2014 unpredictably \u2014 somewhere in the middle.", "photo": "photos/stewart.jpg"}, {"key": "white", "name": "Byron White", "meta": "Kennedy appointee (D)", "blurb": "'Whizzer' White, the All-American halfback turned Kennedy's deputy attorney general \u2014 tough-minded, unsentimental, and skeptical of newly minted rights, especially the kind that make police work harder.", "photo": "photos/white.jpg"}, {"key": "fortas", "name": "Abe Fortas", "meta": "Lyndon Johnson appointee (D)", "blurb": "LBJ's confidant and Washington's premier lawyer, still quietly advising the President from the bench. As an advocate he won poor defendants their counsel; as a justice he champions the underdog \u2014 children included.", "photo": "photos/fortas.jpg"}], "votes": {"warren": "no", "black": "no", "douglas": "no", "clark": "no", "harlan": "no", "brennan": "no", "stewart": "no", "white": "no", "fortas": "no"}}, {"id": "cruzan-v-missouri", "era": "The Rehnquist Court \u00b7 October Term 1989", "caseTitle": "Cruzan v. Director, Missouri Dept. of Health", "question": "May a state demand clear proof of a patient's own wishes before her family can end life support?", "desc": "Nancy Cruzan was 25 when her car overturned on an icy road; her brain went without oxygen for fourteen minutes, and her doctors say she will never wake. Her parents, certain she would not want to live this way, asked to withdraw the tube that feeds her. Missouri's highest court refused: without 'clear and convincing evidence' of Nancy's own wishes, the state's interest in preserving life prevails. The first right-to-die case ever to reach the Court, with medicine, religion, and the American family pressing in.", "intro": "In a Missouri state hospital, Nancy Cruzan has lain in a persistent vegetative state for seven years since a car wreck. Her parents ask to remove her feeding tube. The state answers: not without proof of what Nancy herself wanted.", "decided": "June 25, 1990", "split": "5\u20134", "answer": "yes", "justices": [{"key": "rehnquist88", "name": "William Rehnquist", "meta": "Nixon appointee (R)", "blurb": "Elevated to Chief Justice in 1986 after fifteen years as the Court's lone-wolf conservative dissenter. A states'-rights man with a genial, poker-playing manner, he now assigns the opinions and works to move the Court rightward without splintering his majorities.", "photo": "photos/rehnquist88.jpg", "chief": true}, {"key": "brennan", "name": "William Brennan", "meta": "Eisenhower appointee (R)", "blurb": "The aging architect of the Warren Court's rights revolution, now 83 and often outnumbered. The Court's great coalition-builder \u2014 'five votes can do anything around here' \u2014 he still hunts for a fifth vote wherever one can be found.", "photo": "photos/brennan.jpg"}, {"key": "white", "name": "Byron White", "meta": "Kennedy appointee (D)", "blurb": "A Kennedy appointee and former NFL halfback, gruff and unsentimental. He defies every label: hard on criminal defendants, skeptical of newly minted rights, steady on civil rights. He writes short opinions and asks no one's permission.", "photo": "photos/white.jpg"}, {"key": "marshall", "name": "Thurgood Marshall", "meta": "Lyndon Johnson appointee (D)", "blurb": "The lawyer who argued Brown v. Board of Education, now the Court's most unwavering liberal. He votes against every death sentence and speaks for the poor and powerless \u2014 increasingly in dissent, side by side with his ally Brennan.", "photo": "photos/marshall.jpg"}, {"key": "blackmun", "name": "Harry Blackmun", "meta": "Nixon appointee (R)", "blurb": "The Nixon appointee who wrote Roe v. Wade and has drifted left ever since, marked by the backlash. A meticulous former counsel to the Mayo Clinic, sensitive and deliberate, now usually found alongside Brennan and Marshall.", "photo": "photos/blackmun.jpg"}, {"key": "stevens88", "name": "John Paul Stevens", "meta": "Ford appointee (R)", "blurb": "A Ford appointee and Chicago antitrust lawyer with a bow tie and a ferociously independent streak. He follows his own analysis wherever it leads, scattering solo opinions along the way \u2014 unpredictable by design and beholden to no bloc.", "photo": "photos/stevens88.jpg"}, {"key": "oconnor88", "name": "Sandra Day O'Connor", "meta": "Reagan appointee (R)", "blurb": "The first woman on the Court, a former Arizona legislative leader who judges the way she once governed: case by case, fact by fact, wary of sweeping rules. Increasingly she is the justice both sides must persuade.", "photo": "photos/oconnor88.jpg"}, {"key": "scalia88", "name": "Antonin Scalia", "meta": "Reagan appointee (R)", "blurb": "Reagan's combative textualist, three terms on the bench and already the Court's sharpest pen. He reads constitutional text at face value wherever it points \u2014 and delights in skewering colleagues who balance interests instead.", "photo": "photos/scalia88.jpg"}, {"key": "kennedy88", "name": "Anthony Kennedy", "meta": "Reagan appointee (R)", "blurb": "The newest justice, a courtly Sacramento conservative confirmed unanimously after the Bork nomination went down in flames. Expected to be a dependable Reagan vote, but given to grand talk about liberty and the dignity of the individual.", "photo": "photos/kennedy88.jpg"}], "votes": {"rehnquist88": "yes", "brennan": "no", "white": "yes", "marshall": "no", "blackmun": "no", "stevens88": "no", "oconnor88": "yes", "scalia88": "yes", "kennedy88": "yes"}}, {"id": "obergefell-v-hodges", "era": "The Roberts Court \u00b7 October Term 2014", "caseTitle": "Obergefell v. Hodges", "question": "Does the Fourteenth Amendment require every state to license and recognize same-sex marriages?", "desc": "In two years same-sex marriage has spread from a handful of states to most of the country, largely by court order \u2014 until the Sixth Circuit upheld four states' bans and forced the issue. Dozens of plaintiffs \u2014 widowers, adoptive parents, an Army sergeant \u2014 ask whether Ohio, Michigan, Kentucky, and Tennessee may define marriage as one man and one woman. Crowds camp outside the building for argument seats. Everyone understands this is the endgame.", "intro": "Jim Obergefell married his dying partner on a medical plane on a Maryland tarmac \u2014 and Ohio refused to put his name on the death certificate. The marriage question the Court has circled for years finally arrives whole.", "decided": "June 26, 2015", "split": "5\u20134", "answer": "yes", "justices": [{"key": "roberts", "name": "John Roberts", "meta": "George W. Bush appointee (R)", "blurb": "The chief justice who won the job promising to call balls and strikes, not pitch or bat. A polished Supreme Court advocate turned umpire, he prefers narrow rulings and unanimity where he can get them \u2014 and moves the law by patient inches when he can't.", "photo": "photos/roberts.jpg", "chief": true}, {"key": "scalia_roberts", "name": "Antonin Scalia", "meta": "Reagan appointee (R)", "blurb": "Originalism's happy warrior, decades into his crusade to read the Constitution as its ratifiers understood it. His opinions are the Court's best copy, his scorn for 'living constitutionalism' legendary \u2014 and his method has reshaped how every case is argued.", "photo": "photos/scalia_roberts.jpg"}, {"key": "kennedy_roberts", "name": "Anthony Kennedy", "meta": "Reagan appointee (R)", "blurb": "The swing. A courtly Sacramento Republican who controls the outcome in nearly every close case \u2014 and knows it. Liberty and dignity are his lodestars, sweeping language his signature, suspense his permanent gift to Court-watchers.", "photo": "photos/kennedy_roberts.jpg"}, {"key": "thomas_roberts", "name": "Clarence Thomas", "meta": "George H. W. Bush appointee (R)", "blurb": "The Court's most uncompromising originalist, fearless in print: he will discard decades of precedent without apology and stake out positions entirely alone, serenely confident the law will someday catch up to him.", "photo": "photos/thomas_roberts.jpg"}, {"key": "ginsburg_roberts", "name": "Ruth Bader Ginsburg", "meta": "Clinton appointee (D)", "blurb": "The pioneering women's-rights litigator of the 1970s, now the liberal wing's most exacting technician. Small, quiet, and precise, she picks her battles carefully \u2014 and reads her fiercest dissents aloud from the bench when she loses one.", "photo": "photos/ginsburg_roberts.jpg"}, {"key": "breyer_roberts", "name": "Stephen Breyer", "meta": "Clinton appointee (D)", "blurb": "The Court's pragmatist professor: a former Senate staffer and administrative-law scholar who judges by consequences, not grand theory. Endlessly optimistic about government, allergic to absolutes, and famous for winding hypotheticals that leave lawyers blinking.", "photo": "photos/breyer_roberts.jpg"}, {"key": "alito", "name": "Samuel Alito", "meta": "George W. Bush appointee (R)", "blurb": "A former federal prosecutor from New Jersey, methodical and unflashy, with the most reliably conservative instincts on the bench \u2014 above all where crime, religion, or the culture wars are concerned. In dissent, his pen turns acid.", "photo": "photos/alito.jpg"}, {"key": "sotomayor", "name": "Sonia Sotomayor", "meta": "Obama appointee (D)", "blurb": "From a Bronx housing project to Princeton to the federal trial bench: the first Latina justice never lets the Court forget how doctrine lands on actual people. A former prosecutor, relentless at argument, the liberal wing's most passionate voice.", "photo": "photos/sotomayor.jpg"}, {"key": "kagan", "name": "Elena Kagan", "meta": "Obama appointee (D)", "blurb": "The former Harvard Law dean and solicitor general, a coalition-builder who learned her politics in the Clinton White House. The liberal wing's tactician: she writes in plain, wry English and plays a patient long game of her own.", "photo": "photos/kagan.jpg"}], "votes": {"roberts": "no", "scalia_roberts": "no", "kennedy_roberts": "yes", "thomas_roberts": "no", "ginsburg_roberts": "yes", "breyer_roberts": "yes", "alito": "no", "sotomayor": "yes", "kagan": "yes"}}, {"id": "sony-v-universal", "era": "The Burger Court \u00b7 October Term 1983", "caseTitle": "Sony Corp. v. Universal City Studios", "question": "Is the maker of home video recorders liable because viewers tape TV shows to watch later?", "desc": "Sony's Betamax lets ordinary families do something new: tape a broadcast and watch it later. Universal and Disney call that mass copyright infringement, and they sued in 1976 to make Sony answer for its customers' recording. Hollywood's chief lobbyist tells Congress the VCR is to the American film industry 'as the Boston Strangler is to the woman home alone.' Millions of machines already sit in American living rooms; a ruling for the studios could make every 'time-shifting' viewer an infringer.", "intro": "Hollywood sues the Betamax. The movie studios say every living-room video recorder is a piracy machine \u2014 and they want the manufacturer held to account for it.", "decided": "January 17, 1984", "split": "5\u20134", "answer": "no", "justices": [{"key": "burger", "name": "Warren Burger", "meta": "Nixon appointee (R)", "blurb": "Seventeen years into the center chair, as much administrator as judge \u2014 obsessed with judicial efficiency and courtroom decorum. Reliably conservative on crime and social questions, though colleagues grumble that his opinion assignments follow strategy more than principle.", "photo": "photos/burger.jpg", "chief": true}, {"key": "brennan", "name": "William Brennan", "meta": "Eisenhower appointee (R)", "blurb": "The aging captain of the Court's shrinking liberal wing, three decades in. He can still conjure a majority from thin air on a good day \u2014 but these days he is more often assigning dissents than opinions.", "photo": "photos/brennan.jpg"}, {"key": "white", "name": "Byron White", "meta": "Kennedy appointee (D)", "blurb": "JFK's last appointee has hardened into the Court's flintiest pragmatist \u2014 tough on crime, dismissive of rights he cannot find in the Constitution's text, still steady on race and equal protection.", "photo": "photos/white.jpg"}, {"key": "marshall", "name": "Thurgood Marshall", "meta": "Lyndon Johnson appointee (D)", "blurb": "The civil-rights giant in winter, increasingly isolated as the Court moves right. He and Brennan vote as a pair on the death penalty and much else, filing dissent after dissent for a future Court to find.", "photo": "photos/marshall.jpg"}, {"key": "blackmun", "name": "Harry Blackmun", "meta": "Nixon appointee (R)", "blurb": "The onetime 'Minnesota Twin' has completed a long migration: the shy Nixon appointee now votes more often with Brennan and Marshall than with the Chief he grew up beside \u2014 above all on privacy and equality.", "photo": "photos/blackmun.jpg"}, {"key": "powell", "name": "Lewis Powell", "meta": "Nixon appointee (R)", "blurb": "The Court's gentle fulcrum. The courtly Richmond lawyer decides the close ones \u2014 law clerks joke that the Constitution means whatever Lewis Powell thinks it means \u2014 balancing order against liberty with a counselor's caution.", "photo": "photos/powell.jpg"}, {"key": "rehnquist", "name": "William Rehnquist", "meta": "Nixon appointee (R)", "blurb": "The Court's anchor on the right, so fond of solo dissents that his clerks once gave him a Lone Ranger doll. Federalism, law enforcement, judicial restraint: his positions never wobble \u2014 and the Court, increasingly, comes to him.", "photo": "photos/rehnquist.jpg"}, {"key": "stevens", "name": "John Paul Stevens", "meta": "Ford appointee (R)", "blurb": "The bow-tied Chicagoan defies sorting \u2014 a Ford Republican drifting toward the Court's left flank, case by idiosyncratic case. He writes more separate opinions than anyone, trusting his own reading of the law over any bloc's.", "photo": "photos/stevens.jpg"}, {"key": "oconnor", "name": "Sandra Day O'Connor", "meta": "Reagan appointee (R)", "blurb": "The first woman on the Court, a former Arizona legislative leader who judges like a lawmaker \u2014 narrow rulings, workable compromises, close attention to the facts. Reliably conservative on crime; harder to predict everywhere else.", "photo": "photos/oconnor.jpg"}], "votes": {"burger": "no", "brennan": "no", "white": "no", "marshall": "yes", "blackmun": "yes", "powell": "yes", "rehnquist": "yes", "stevens": "no", "oconnor": "no"}}, {"id": "bowers-v-hardwick", "era": "The Burger Court \u00b7 October Term 1985", "caseTitle": "Bowers v. Hardwick", "question": "Does the Constitution protect private, consensual sex between adults of the same sex?", "desc": "Hardwick was arrested in his own bedroom with another man under a Georgia statute punishing sodomy with up to twenty years in prison. The district attorney dropped the charge, but Hardwick sued, arguing that the Court's privacy cases \u2014 contraception, abortion, the sanctity of the home \u2014 must protect consensual adult intimacy too. Half the states have repealed such laws; Georgia defends its own as ancient moral tradition. The gay-rights movement, not two decades after Stonewall, faces its first great test in the marble temple.", "intro": "An Atlanta police officer, serving an invalid warrant, walks into Michael Hardwick's bedroom \u2014 and Georgia's sodomy law lands at the Supreme Court.", "decided": "June 30, 1986", "split": "5\u20134", "answer": "no", "justices": [{"key": "burger", "name": "Warren Burger", "meta": "Nixon appointee (R)", "blurb": "Seventeen years into the center chair, as much administrator as judge \u2014 obsessed with judicial efficiency and courtroom decorum. Reliably conservative on crime and social questions, though colleagues grumble that his opinion assignments follow strategy more than principle.", "photo": "photos/burger.jpg", "chief": true}, {"key": "brennan", "name": "William Brennan", "meta": "Eisenhower appointee (R)", "blurb": "The aging captain of the Court's shrinking liberal wing, three decades in. He can still conjure a majority from thin air on a good day \u2014 but these days he is more often assigning dissents than opinions.", "photo": "photos/brennan.jpg"}, {"key": "white", "name": "Byron White", "meta": "Kennedy appointee (D)", "blurb": "JFK's last appointee has hardened into the Court's flintiest pragmatist \u2014 tough on crime, dismissive of rights he cannot find in the Constitution's text, still steady on race and equal protection.", "photo": "photos/white.jpg"}, {"key": "marshall", "name": "Thurgood Marshall", "meta": "Lyndon Johnson appointee (D)", "blurb": "The civil-rights giant in winter, increasingly isolated as the Court moves right. He and Brennan vote as a pair on the death penalty and much else, filing dissent after dissent for a future Court to find.", "photo": "photos/marshall.jpg"}, {"key": "blackmun", "name": "Harry Blackmun", "meta": "Nixon appointee (R)", "blurb": "The onetime 'Minnesota Twin' has completed a long migration: the shy Nixon appointee now votes more often with Brennan and Marshall than with the Chief he grew up beside \u2014 above all on privacy and equality.", "photo": "photos/blackmun.jpg"}, {"key": "powell", "name": "Lewis Powell", "meta": "Nixon appointee (R)", "blurb": "The Court's gentle fulcrum. The courtly Richmond lawyer decides the close ones \u2014 law clerks joke that the Constitution means whatever Lewis Powell thinks it means \u2014 balancing order against liberty with a counselor's caution.", "photo": "photos/powell.jpg"}, {"key": "rehnquist", "name": "William Rehnquist", "meta": "Nixon appointee (R)", "blurb": "The Court's anchor on the right, so fond of solo dissents that his clerks once gave him a Lone Ranger doll. Federalism, law enforcement, judicial restraint: his positions never wobble \u2014 and the Court, increasingly, comes to him.", "photo": "photos/rehnquist.jpg"}, {"key": "stevens", "name": "John Paul Stevens", "meta": "Ford appointee (R)", "blurb": "The bow-tied Chicagoan defies sorting \u2014 a Ford Republican drifting toward the Court's left flank, case by idiosyncratic case. He writes more separate opinions than anyone, trusting his own reading of the law over any bloc's.", "photo": "photos/stevens.jpg"}, {"key": "oconnor", "name": "Sandra Day O'Connor", "meta": "Reagan appointee (R)", "blurb": "The first woman on the Court, a former Arizona legislative leader who judges like a lawmaker \u2014 narrow rulings, workable compromises, close attention to the facts. Reliably conservative on crime; harder to predict everywhere else.", "photo": "photos/oconnor.jpg"}], "votes": {"burger": "no", "brennan": "yes", "white": "no", "marshall": "yes", "blackmun": "yes", "powell": "no", "rehnquist": "no", "stevens": "yes", "oconnor": "no"}}, {"id": "furman-v-georgia", "era": "The Burger Court \u00b7 October Term 1971", "caseTitle": "Furman v. Georgia", "question": "Does the death penalty, as states now administer it, violate the Constitution?", "desc": "William Henry Furman, a Black handyman from Savannah, shot a homeowner during a botched midnight burglary \u2014 he says the gun went off as he fled. Georgia juries choose between life and death with no standards at all, and the studies say the penalty falls overwhelmingly on the poor and the Black. Executions nationwide have quietly stopped while the country awaits the answer. The Court has never faced the question this squarely \u2014 and no one is sure the nine can agree on a single reason for whatever they decide.", "intro": "1972. Six hundred men wait on death row while the Court weighs whether capital punishment \u2014 as America actually practices it \u2014 can survive the Eighth Amendment's ban on cruel and unusual punishments.", "decided": "June 29, 1972", "split": "5\u20134", "answer": "yes", "justices": [{"key": "burger", "name": "Warren Burger", "meta": "Nixon appointee (R)", "blurb": "Nixon's chief justice, installed to steady a Court he believes ran wild under Earl Warren. A stickler for order and the dignity of institutions, he is more cautious conservative than crusader \u2014 and ever mindful of the Court's public standing.", "photo": "photos/burger.jpg", "chief": true}, {"key": "douglas", "name": "William O. Douglas", "meta": "Franklin Roosevelt appointee (D)", "blurb": "A New Deal wunderkind grown into the Court's absolutist loner \u2014 three decades on the bench, four wives, a shelf of his own books. He votes for the individual against the government almost reflexively, and writes opinions at breakneck speed.", "photo": "photos/douglas.jpg"}, {"key": "brennan", "name": "William Brennan", "meta": "Eisenhower appointee (R)", "blurb": "The Warren Court's master coalition-builder, an Eisenhower appointee turned architect of its liberal revolution. His first rule \u2014 with five votes you can do anything \u2014 still guides him as the bench tilts rightward around him.", "photo": "photos/brennan.jpg"}, {"key": "stewart", "name": "Potter Stewart", "meta": "Eisenhower appointee (R)", "blurb": "A pragmatic Ohio Republican wary of grand theory, he decides cases narrowly and one at a time. Neither wing can count on him: he distrusts government overreach and judicial adventure in roughly equal measure.", "photo": "photos/stewart.jpg"}, {"key": "white", "name": "Byron White", "meta": "Kennedy appointee (D)", "blurb": "The Kennedys' deputy attorney general, an All-America halfback turned no-nonsense pragmatist. Tough on crime and skeptical of newly minted rights, yet often found with the liberals on race and civil rights.", "photo": "photos/white.jpg"}, {"key": "marshall", "name": "Thurgood Marshall", "meta": "Lyndon Johnson appointee (D)", "blurb": "The architect of Brown v. Board and the Court's first Black justice. He judges from lived experience \u2014 Jim Crow courtrooms, clients facing the electric chair \u2014 and defends the poor and powerless with unembarrassed consistency.", "photo": "photos/marshall.jpg"}, {"key": "blackmun", "name": "Harry Blackmun", "meta": "Nixon appointee (R)", "blurb": "The junior justice, a shy Minnesota Republican and longtime counsel to the Mayo Clinic. Washington calls him and his boyhood friend the Chief the 'Minnesota Twins' \u2014 so far he votes Burger's way more often than not.", "photo": "photos/blackmun.jpg"}, {"key": "powell", "name": "Lewis Powell", "meta": "Nixon appointee (R)", "blurb": "A courtly Richmond corporate lawyer and former ABA president, newly arrived on the bench. The establishment's ideal judge: moderate, balancing, allergic to extremes \u2014 he weighs each case like a client matter and lands, usually, near the center.", "photo": "photos/powell.jpg"}, {"key": "rehnquist", "name": "William Rehnquist", "meta": "Nixon appointee (R)", "blurb": "The junior justice and its boldest conservative \u2014 a 47-year-old Nixon Justice Department lawyer with a brilliant pen and no fear of standing alone. He doubts much of what the Warren Court built.", "photo": "photos/rehnquist.jpg"}], "votes": {"burger": "no", "douglas": "yes", "brennan": "yes", "stewart": "yes", "white": "yes", "marshall": "yes", "blackmun": "no", "powell": "no", "rehnquist": "no"}}, {"id": "atkins-v-virginia", "era": "The Rehnquist Court \u00b7 October Term 2001", "caseTitle": "Atkins v. Virginia", "question": "May a state execute a murderer who is intellectually disabled?", "desc": "Atkins and an accomplice abducted airman Eric Nesbitt outside a convenience store, forced him to withdraw cash from an ATM, and shot him eight times. His guilt is not before the Court; his mind is. In 1989 only two death-penalty states spared mentally retarded offenders, and the Court found no national consensus against the practice. Now eighteen do. The Eighth Amendment turns on 'evolving standards of decency' \u2014 and the justices must decide whether the standards have evolved, and who gets to say so.", "intro": "Daryl Atkins sits on Virginia's death row for the abduction and murder of a young airman. A psychologist puts his IQ at 59. Thirteen years ago the Court let such executions proceed \u2014 since then, state after state has banned them.", "decided": "June 20, 2002", "split": "6\u20133", "answer": "no", "justices": [{"key": "rehnquist", "name": "William Rehnquist", "meta": "Nixon appointee (R)", "blurb": "Chief Justice for nearly two decades, a genial and ruthlessly efficient administrator with a lifelong project: reviving states' rights and reining in Washington. He has spent his whole career waiting for the votes he now has.", "photo": "photos/rehnquist.jpg", "chief": true}, {"key": "stevens", "name": "John Paul Stevens", "meta": "Ford appointee (R)", "blurb": "The senior associate justice, a bow-tied Ford appointee from Chicago who now marshals the Court's liberal wing. Fiercely independent in method, he assigns the dissents whenever the Chief is on the other side.", "photo": "photos/stevens.jpg"}, {"key": "oconnor", "name": "Sandra Day O'Connor", "meta": "Reagan appointee (R)", "blurb": "A former Arizona legislator and the Court's pivotal vote \u2014 by common consent the most powerful woman in America. She distrusts absolutes and decides case by case; where she lands is usually where the law lands.", "photo": "photos/oconnor.jpg"}, {"key": "scalia", "name": "Antonin Scalia", "meta": "Reagan appointee (R)", "blurb": "The Court's combative originalist, its funniest questioner and its fiercest dissenter. He wants clear rules drawn from text and history, and treats his colleagues' balancing tests as legislation in robes.", "photo": "photos/scalia.jpg"}, {"key": "kennedy", "name": "Anthony Kennedy", "meta": "Reagan appointee (R)", "blurb": "A courtly Sacramento Republican with a taste for sweeping language about liberty and dignity. Conservative by default but persuadable at the margins \u2014 one of the two votes every advocate in the courtroom is chasing.", "photo": "photos/kennedy.jpg"}, {"key": "souter", "name": "David Souter", "meta": "George H. W. Bush appointee (R)", "blurb": "The first President Bush's 'stealth nominee,' a frugal New Hampshire bachelor who confounded his sponsors by settling into the moderate-liberal wing. A common-law traditionalist, devoted to precedent and wary of bold constitutional lurches.", "photo": "photos/souter.jpg"}, {"key": "thomas", "name": "Clarence Thomas", "meta": "George H. W. Bush appointee (R)", "blurb": "The Court's most uncompromising originalist, silent at argument and fearless in print. He would rather overrule a wrong precedent than trim it, and he stakes out positions no other justice will yet join.", "photo": "photos/thomas.jpg"}, {"key": "ginsburg", "name": "Ruth Bader Ginsburg", "meta": "Clinton appointee (D)", "blurb": "The ACLU litigator who dismantled sex-discrimination law brick by brick, now a precise, soft-spoken justice. A minimalist by temperament and a reliable liberal vote on questions of equal citizenship.", "photo": "photos/ginsburg.jpg"}, {"key": "breyer", "name": "Stephen Breyer", "meta": "Clinton appointee (D)", "blurb": "The junior justice, a Harvard administrative-law professor who thinks in workable purposes rather than absolutes. Pragmatic, optimistic about government, and forever spinning elaborate hypotheticals from the bench.", "photo": "photos/breyer.jpg"}], "votes": {"rehnquist": "yes", "stevens": "no", "oconnor": "no", "scalia": "yes", "kennedy": "no", "souter": "no", "thomas": "yes", "ginsburg": "no", "breyer": "no"}}, {"id": "lawrence-v-texas", "era": "The Rehnquist Court \u00b7 October Term 2002", "caseTitle": "Lawrence v. Texas", "question": "May a state make it a crime for two adults of the same sex to have sex in private?", "desc": "Lawrence and Garner spent a night in jail for conduct that was legal for any opposite-sex couple in Texas. In 1986 the Court upheld Georgia's sodomy law, scoffing at the claimed right as 'facetious'; since then the number of states with such laws has fallen from twenty-five to thirteen, and only four enforce them against homosexuals alone. Texas says the law expresses its citizens' moral judgment, which has always been reason enough. The challengers say the Constitution leaves adults' private lives to adults \u2014 and asks the Court to say Bowers was wrong.", "intro": "Houston police, answering a false report of an armed intruder, enter John Lawrence's apartment and arrest him and Tyron Garner under the Texas Homosexual Conduct law. The fine is $200. The question reaches back seventeen years, to Bowers v. Hardwick.", "decided": "June 26, 2003", "split": "6\u20133", "answer": "no", "justices": [{"key": "rehnquist", "name": "William Rehnquist", "meta": "Nixon appointee (R)", "blurb": "Chief Justice for nearly two decades, a genial and ruthlessly efficient administrator with a lifelong project: reviving states' rights and reining in Washington. He has spent his whole career waiting for the votes he now has.", "photo": "photos/rehnquist.jpg", "chief": true}, {"key": "stevens", "name": "John Paul Stevens", "meta": "Ford appointee (R)", "blurb": "The senior associate justice, a bow-tied Ford appointee from Chicago who now marshals the Court's liberal wing. Fiercely independent in method, he assigns the dissents whenever the Chief is on the other side.", "photo": "photos/stevens.jpg"}, {"key": "oconnor", "name": "Sandra Day O'Connor", "meta": "Reagan appointee (R)", "blurb": "A former Arizona legislator and the Court's pivotal vote \u2014 by common consent the most powerful woman in America. She distrusts absolutes and decides case by case; where she lands is usually where the law lands.", "photo": "photos/oconnor.jpg"}, {"key": "scalia", "name": "Antonin Scalia", "meta": "Reagan appointee (R)", "blurb": "The Court's combative originalist, its funniest questioner and its fiercest dissenter. He wants clear rules drawn from text and history, and treats his colleagues' balancing tests as legislation in robes.", "photo": "photos/scalia.jpg"}, {"key": "kennedy", "name": "Anthony Kennedy", "meta": "Reagan appointee (R)", "blurb": "A courtly Sacramento Republican with a taste for sweeping language about liberty and dignity. Conservative by default but persuadable at the margins \u2014 one of the two votes every advocate in the courtroom is chasing.", "photo": "photos/kennedy.jpg"}, {"key": "souter", "name": "David Souter", "meta": "George H. W. Bush appointee (R)", "blurb": "The first President Bush's 'stealth nominee,' a frugal New Hampshire bachelor who confounded his sponsors by settling into the moderate-liberal wing. A common-law traditionalist, devoted to precedent and wary of bold constitutional lurches.", "photo": "photos/souter.jpg"}, {"key": "thomas", "name": "Clarence Thomas", "meta": "George H. W. Bush appointee (R)", "blurb": "The Court's most uncompromising originalist, silent at argument and fearless in print. He would rather overrule a wrong precedent than trim it, and he stakes out positions no other justice will yet join.", "photo": "photos/thomas.jpg"}, {"key": "ginsburg", "name": "Ruth Bader Ginsburg", "meta": "Clinton appointee (D)", "blurb": "The ACLU litigator who dismantled sex-discrimination law brick by brick, now a precise, soft-spoken justice. A minimalist by temperament and a reliable liberal vote on questions of equal citizenship.", "photo": "photos/ginsburg.jpg"}, {"key": "breyer", "name": "Stephen Breyer", "meta": "Clinton appointee (D)", "blurb": "The junior justice, a Harvard administrative-law professor who thinks in workable purposes rather than absolutes. Pragmatic, optimistic about government, and forever spinning elaborate hypotheticals from the bench.", "photo": "photos/breyer.jpg"}], "votes": {"rehnquist": "yes", "stevens": "no", "oconnor": "no", "scalia": "yes", "kennedy": "no", "souter": "no", "thomas": "yes", "ginsburg": "no", "breyer": "no"}}, {"id": "trump-v-united-states", "era": "The Roberts Court \u00b7 October Term 2023", "caseTitle": "Trump v. United States", "question": "Does a former president enjoy at least presumptive immunity from criminal prosecution for his official acts in office?", "desc": "Special counsel Jack Smith's January 6 indictment charges Donald Trump with conspiring to overturn the 2020 election. Trump claims sweeping immunity for anything within a president's official duties \u2014 otherwise, his lawyers warn, every president will leave office fearing his successor's prosecutors. The special counsel answers that no man is above the law and the trial should start now. The election is four months off, and the calendar itself may be the real prize.", "intro": "For the first time, a former president stands indicted for trying to overturn an election he lost \u2014 and he answers that presidents cannot be prosecuted at all. The Court is asked to define the office itself.", "decided": "July 1, 2024", "split": "6\u20133", "answer": "yes", "justices": [{"key": "roberts", "name": "John Roberts", "meta": "George W. Bush appointee (R)", "blurb": "No longer the Court's median vote \u2014 a six-justice conservative majority can now rule without him. He still preaches minimalism and frets over the institution's standing, hunting for narrower paths that his colleagues increasingly decline to take.", "photo": "photos/roberts.jpg", "chief": true}, {"key": "thomas_roberts", "name": "Clarence Thomas", "meta": "George H. W. Bush appointee (R)", "blurb": "The Court's most uncompromising originalist, fearless in print: he will discard decades of precedent without apology and stake out positions entirely alone, serenely confident the law will someday catch up to him.", "photo": "photos/thomas_roberts.jpg"}, {"key": "alito", "name": "Samuel Alito", "meta": "George W. Bush appointee (R)", "blurb": "A former federal prosecutor from New Jersey, methodical and unflashy, with the most reliably conservative instincts on the bench \u2014 above all where crime, religion, or the culture wars are concerned. In dissent, his pen turns acid.", "photo": "photos/alito.jpg"}, {"key": "sotomayor", "name": "Sonia Sotomayor", "meta": "Obama appointee (D)", "blurb": "From a Bronx housing project to Princeton to the federal trial bench: the first Latina justice never lets the Court forget how doctrine lands on actual people. A former prosecutor, relentless at argument, the liberal wing's most passionate voice.", "photo": "photos/sotomayor.jpg"}, {"key": "kagan", "name": "Elena Kagan", "meta": "Obama appointee (D)", "blurb": "The former Harvard Law dean and solicitor general, a coalition-builder who learned her politics in the Clinton White House. The liberal wing's tactician: she writes in plain, wry English and plays a patient long game of her own.", "photo": "photos/kagan.jpg"}, {"key": "gorsuch", "name": "Neil Gorsuch", "meta": "Trump appointee (R)", "blurb": "Scalia's successor and a true-believing textualist from Colorado: read the words, then follow them off a cliff if necessary. A westerner with a libertarian streak, he votes his method wherever it leads \u2014 to either camp's occasional dismay.", "photo": "photos/gorsuch.jpg"}, {"key": "kavanaugh", "name": "Brett Kavanaugh", "meta": "Trump appointee (R)", "blurb": "Confirmed after the most explosive hearings in memory, the former Bush White House aide works at looking reassuringly conventional: a conservative who prizes stability, writes separately to narrow things, and courts the middle whenever there is one.", "photo": "photos/kavanaugh.jpg"}, {"key": "barrett", "name": "Amy Coney Barrett", "meta": "Trump appointee (R)", "blurb": "Scalia's former clerk and a Notre Dame law professor, elevated to the bench days before a presidential election. An academic originalist \u2014 careful, methodical, unshowy \u2014 still drawing her own map of where method and caution part ways.", "photo": "photos/barrett.jpg"}, {"key": "jackson", "name": "Ketanji Brown Jackson", "meta": "Biden appointee (D)", "blurb": "The first Black woman on the Court and its first former public defender. She brings a trial judge's practicality, a performer's timing at oral argument, and no apparent interest in waiting her turn to be heard.", "photo": "photos/jackson.jpg"}], "votes": {"roberts": "yes", "thomas_roberts": "yes", "alito": "yes", "sotomayor": "no", "kagan": "no", "gorsuch": "yes", "kavanaugh": "yes", "barrett": "yes", "jackson": "no"}}, {"id": "tinker-v-des-moines", "era": "The Warren Court \u00b7 October Term 1968", "caseTitle": "Tinker v. Des Moines", "question": "Does the First Amendment protect public-school students who wear armbands in political protest?", "desc": "Mary Beth, her brother John, and Christopher Eckhardt planned a silent protest: black armbands through the holidays, nothing more. School officials, hearing of the plan, banned armbands specifically \u2014 political buttons and even Iron Crosses remained permitted \u2014 and suspended the three who wore them anyway. No class was disrupted. With campuses in open revolt by the time the case is argued in 1968, the schools say discipline demands deference; the students' lawyers say children do not shed the Constitution at the schoolhouse gate.", "intro": "December 1965. Thirteen-year-old Mary Beth Tinker wears a black armband to junior high to mourn the dead of Vietnam. Des Moines banned armbands two days earlier \u2014 and suspends her by afternoon.", "decided": "February 24, 1969", "split": "7\u20132", "answer": "yes", "justices": [{"key": "warren", "name": "Earl Warren", "meta": "Eisenhower appointee (R)", "blurb": "The former California governor, now the most consequential Chief Justice in a century. He asks lawyers one question \u2014 'But is it fair?' \u2014 and works the conference like the politician he never stopped being.", "photo": "photos/warren.jpg", "chief": true}, {"key": "black", "name": "Hugo Black", "meta": "Franklin Roosevelt appointee (D)", "blurb": "An Alabama New Dealer who carries the Constitution in his coat pocket and reads it literally. 'No law' means no law \u2014 but rights he cannot find in the text, he will not invent.", "photo": "photos/black.jpg"}, {"key": "douglas", "name": "William O. Douglas", "meta": "Franklin Roosevelt appointee (D)", "blurb": "A restless westerner and the Court's fastest pen \u2014 impatient with doctrine, indifferent to precedent, and instinctively on the side of the lone individual against the government in nearly any form it takes.", "photo": "photos/douglas.jpg"}, {"key": "harlan", "name": "John Marshall Harlan", "meta": "Eisenhower appointee (R)", "blurb": "The Wall Street patrician and grandson of a great dissenter \u2014 the Court's conservative conscience. He believes in ordered liberty and lawyerly process, and objects, elegantly, when the majority moves too far, too fast.", "photo": "photos/harlan.jpg"}, {"key": "brennan", "name": "William Brennan", "meta": "Eisenhower appointee (R)", "blurb": "The Court's Irish charmer and master coalition-builder, an Eisenhower appointee who turned out to be its most effective liberal. His first rule of the shop: with five votes, you can do anything.", "photo": "photos/brennan.jpg"}, {"key": "stewart", "name": "Potter Stewart", "meta": "Eisenhower appointee (R)", "blurb": "A moderate Ohio Republican who resists both blocs' grand theories. He decides cases one at a time, asks what the Constitution actually commands, and lands \u2014 unpredictably \u2014 somewhere in the middle.", "photo": "photos/stewart.jpg"}, {"key": "white", "name": "Byron White", "meta": "Kennedy appointee (D)", "blurb": "'Whizzer' White, the All-American halfback turned Kennedy's deputy attorney general \u2014 tough-minded, unsentimental, and skeptical of newly minted rights, especially the kind that make police work harder.", "photo": "photos/white.jpg"}, {"key": "fortas", "name": "Abe Fortas", "meta": "Lyndon Johnson appointee (D)", "blurb": "LBJ's confidant and Washington's premier lawyer, still quietly advising the President from the bench. As an advocate he won poor defendants their counsel; as a justice he champions the underdog \u2014 children included.", "photo": "photos/fortas.jpg"}, {"key": "marshall", "name": "Thurgood Marshall", "meta": "Lyndon Johnson appointee (D)", "blurb": "The architect of the NAACP's litigation war on Jim Crow and the first Black justice \u2014 a storyteller who has seen the criminal law from the defendant's side of the table and never forgets it.", "photo": "photos/marshall.jpg"}], "votes": {"warren": "yes", "black": "no", "douglas": "yes", "harlan": "no", "brennan": "yes", "stewart": "yes", "white": "yes", "fortas": "yes", "marshall": "yes"}}, {"id": "nfib-v-sebelius", "era": "The Roberts Court \u00b7 October Term 2011", "caseTitle": "NFIB v. Sebelius", "question": "May the Affordable Care Act's individual mandate \u2014 buy health insurance or pay a penalty \u2014 stand as a valid exercise of Congress's taxing power?", "desc": "The Affordable Care Act's machinery depends on the individual mandate: carry health insurance or pay a penalty with your taxes. Twenty-six states and a small-business federation call that an unprecedented command to enter commerce; the government calls it regulation of a market everyone is already in \u2014 and, in the alternative, a tax. After the mandate takes a beating at argument, Washington spends three months bracing for the law to fall, and intrigue about the outcome consumes the capital.", "intro": "Obamacare's fate reaches the Court in an election year: three days of argument, protesters ringing the plaza, and one question underneath it all \u2014 can Congress make Americans buy insurance?", "decided": "June 28, 2012", "split": "5\u20134", "answer": "yes", "justices": [{"key": "roberts", "name": "John Roberts", "meta": "George W. Bush appointee (R)", "blurb": "The chief justice who won the job promising to call balls and strikes, not pitch or bat. A polished Supreme Court advocate turned umpire, he prefers narrow rulings and unanimity where he can get them \u2014 and moves the law by patient inches when he can't.", "photo": "photos/roberts.jpg", "chief": true}, {"key": "scalia_roberts", "name": "Antonin Scalia", "meta": "Reagan appointee (R)", "blurb": "Originalism's happy warrior, decades into his crusade to read the Constitution as its ratifiers understood it. His opinions are the Court's best copy, his scorn for 'living constitutionalism' legendary \u2014 and his method has reshaped how every case is argued.", "photo": "photos/scalia_roberts.jpg"}, {"key": "kennedy_roberts", "name": "Anthony Kennedy", "meta": "Reagan appointee (R)", "blurb": "The swing. A courtly Sacramento Republican who controls the outcome in nearly every close case \u2014 and knows it. Liberty and dignity are his lodestars, sweeping language his signature, suspense his permanent gift to Court-watchers.", "photo": "photos/kennedy_roberts.jpg"}, {"key": "thomas_roberts", "name": "Clarence Thomas", "meta": "George H. W. Bush appointee (R)", "blurb": "The Court's most uncompromising originalist, fearless in print: he will discard decades of precedent without apology and stake out positions entirely alone, serenely confident the law will someday catch up to him.", "photo": "photos/thomas_roberts.jpg"}, {"key": "ginsburg_roberts", "name": "Ruth Bader Ginsburg", "meta": "Clinton appointee (D)", "blurb": "The pioneering women's-rights litigator of the 1970s, now the liberal wing's most exacting technician. Small, quiet, and precise, she picks her battles carefully \u2014 and reads her fiercest dissents aloud from the bench when she loses one.", "photo": "photos/ginsburg_roberts.jpg"}, {"key": "breyer_roberts", "name": "Stephen Breyer", "meta": "Clinton appointee (D)", "blurb": "The Court's pragmatist professor: a former Senate staffer and administrative-law scholar who judges by consequences, not grand theory. Endlessly optimistic about government, allergic to absolutes, and famous for winding hypotheticals that leave lawyers blinking.", "photo": "photos/breyer_roberts.jpg"}, {"key": "alito", "name": "Samuel Alito", "meta": "George W. Bush appointee (R)", "blurb": "A former federal prosecutor from New Jersey, methodical and unflashy, with the most reliably conservative instincts on the bench \u2014 above all where crime, religion, or the culture wars are concerned. In dissent, his pen turns acid.", "photo": "photos/alito.jpg"}, {"key": "sotomayor", "name": "Sonia Sotomayor", "meta": "Obama appointee (D)", "blurb": "From a Bronx housing project to Princeton to the federal trial bench: the first Latina justice never lets the Court forget how doctrine lands on actual people. A former prosecutor, relentless at argument, the liberal wing's most passionate voice.", "photo": "photos/sotomayor.jpg"}, {"key": "kagan", "name": "Elena Kagan", "meta": "Obama appointee (D)", "blurb": "The former Harvard Law dean and solicitor general, a coalition-builder who learned her politics in the Clinton White House. The liberal wing's tactician: she writes in plain, wry English and plays a patient long game of her own.", "photo": "photos/kagan.jpg"}], "votes": {"roberts": "yes", "scalia_roberts": "no", "kennedy_roberts": "no", "thomas_roberts": "no", "ginsburg_roberts": "yes", "breyer_roberts": "yes", "alito": "no", "sotomayor": "yes", "kagan": "yes"}}, {"id": "new-jersey-v-tlo", "era": "The Burger Court \u00b7 October Term 1984", "caseTitle": "New Jersey v. T.L.O.", "question": "May school officials search a student's purse without a warrant or probable cause?", "desc": "Inside fourteen-year-old T.L.O.'s purse the vice principal found cigarettes, then rolling papers, then marijuana, a wad of dollar bills, and an index card listing students who owed her money. New Jersey used all of it to prosecute her as a delinquent. The Warrant Clause was written for constables, not vice principals: schools say they need swift discipline in an era of drugs in the hallways; her lawyers answer that children do not shed the Constitution at the schoolhouse door.", "intro": "A Piscataway freshman caught smoking in the girls' room denies everything \u2014 so the vice principal opens her purse, and the Fourth Amendment goes to high school.", "decided": "January 15, 1985", "split": "6\u20133", "answer": "yes", "justices": [{"key": "burger", "name": "Warren Burger", "meta": "Nixon appointee (R)", "blurb": "Seventeen years into the center chair, as much administrator as judge \u2014 obsessed with judicial efficiency and courtroom decorum. Reliably conservative on crime and social questions, though colleagues grumble that his opinion assignments follow strategy more than principle.", "photo": "photos/burger.jpg", "chief": true}, {"key": "brennan", "name": "William Brennan", "meta": "Eisenhower appointee (R)", "blurb": "The aging captain of the Court's shrinking liberal wing, three decades in. He can still conjure a majority from thin air on a good day \u2014 but these days he is more often assigning dissents than opinions.", "photo": "photos/brennan.jpg"}, {"key": "white", "name": "Byron White", "meta": "Kennedy appointee (D)", "blurb": "JFK's last appointee has hardened into the Court's flintiest pragmatist \u2014 tough on crime, dismissive of rights he cannot find in the Constitution's text, still steady on race and equal protection.", "photo": "photos/white.jpg"}, {"key": "marshall", "name": "Thurgood Marshall", "meta": "Lyndon Johnson appointee (D)", "blurb": "The civil-rights giant in winter, increasingly isolated as the Court moves right. He and Brennan vote as a pair on the death penalty and much else, filing dissent after dissent for a future Court to find.", "photo": "photos/marshall.jpg"}, {"key": "blackmun", "name": "Harry Blackmun", "meta": "Nixon appointee (R)", "blurb": "The onetime 'Minnesota Twin' has completed a long migration: the shy Nixon appointee now votes more often with Brennan and Marshall than with the Chief he grew up beside \u2014 above all on privacy and equality.", "photo": "photos/blackmun.jpg"}, {"key": "powell", "name": "Lewis Powell", "meta": "Nixon appointee (R)", "blurb": "The Court's gentle fulcrum. The courtly Richmond lawyer decides the close ones \u2014 law clerks joke that the Constitution means whatever Lewis Powell thinks it means \u2014 balancing order against liberty with a counselor's caution.", "photo": "photos/powell.jpg"}, {"key": "rehnquist", "name": "William Rehnquist", "meta": "Nixon appointee (R)", "blurb": "The Court's anchor on the right, so fond of solo dissents that his clerks once gave him a Lone Ranger doll. Federalism, law enforcement, judicial restraint: his positions never wobble \u2014 and the Court, increasingly, comes to him.", "photo": "photos/rehnquist.jpg"}, {"key": "stevens", "name": "John Paul Stevens", "meta": "Ford appointee (R)", "blurb": "The bow-tied Chicagoan defies sorting \u2014 a Ford Republican drifting toward the Court's left flank, case by idiosyncratic case. He writes more separate opinions than anyone, trusting his own reading of the law over any bloc's.", "photo": "photos/stevens.jpg"}, {"key": "oconnor", "name": "Sandra Day O'Connor", "meta": "Reagan appointee (R)", "blurb": "The first woman on the Court, a former Arizona legislative leader who judges like a lawmaker \u2014 narrow rulings, workable compromises, close attention to the facts. Reliably conservative on crime; harder to predict everywhere else.", "photo": "photos/oconnor.jpg"}], "votes": {"burger": "yes", "brennan": "no", "white": "yes", "marshall": "no", "blackmun": "yes", "powell": "yes", "rehnquist": "yes", "stevens": "no", "oconnor": "yes"}}, {"id": "gregg-v-georgia", "era": "The Burger Court \u00b7 October Term 1975", "caseTitle": "Gregg v. Georgia", "question": "May a state impose the death penalty for murder under a statute that guides the jury's discretion?", "desc": "Troy Gregg was condemned for robbing and murdering two men who gave him a ride. Georgia's new statute is the model reform: a separate sentencing trial, jury findings of specific aggravating circumstances, automatic review in the state's highest court. The national moratorium has held since 1972 while hundreds of new death sentences pile up, waiting. The question the Court sidestepped in Furman is now unavoidable: is capital punishment itself cruel and unusual \u2014 or was the problem only how juries imposed it?", "intro": "Four years after Furman emptied every death row in America, thirty-five states have rewritten their capital statutes \u2014 and the Court must decide whether the death penalty can come back.", "decided": "July 2, 1976", "split": "7\u20132", "answer": "yes", "justices": [{"key": "burger", "name": "Warren Burger", "meta": "Nixon appointee (R)", "blurb": "Nixon's chief justice, installed to steady a Court he believes ran wild under Earl Warren. A stickler for order and the dignity of institutions, he is more cautious conservative than crusader \u2014 and ever mindful of the Court's public standing.", "photo": "photos/burger.jpg", "chief": true}, {"key": "brennan", "name": "William Brennan", "meta": "Eisenhower appointee (R)", "blurb": "Twenty years on, the great liberal playmaker works a Court that has drifted away from him. He still counts to five better than anyone alive, hunting the center for partners case by case.", "photo": "photos/brennan.jpg"}, {"key": "stewart", "name": "Potter Stewart", "meta": "Eisenhower appointee (R)", "blurb": "The Court's studied centrist, a judge of narrow rulings and practical lines. Eighteen years in, he remains the man both blocs court \u2014 skeptical of absolutes, attentive to how the law actually operates.", "photo": "photos/stewart.jpg"}, {"key": "white", "name": "Byron White", "meta": "Kennedy appointee (D)", "blurb": "The Kennedys' deputy attorney general, an All-America halfback turned no-nonsense pragmatist. Tough on crime and skeptical of newly minted rights, yet often found with the liberals on race and civil rights.", "photo": "photos/white.jpg"}, {"key": "marshall", "name": "Thurgood Marshall", "meta": "Lyndon Johnson appointee (D)", "blurb": "The architect of Brown v. Board and the Court's first Black justice. He judges from lived experience \u2014 Jim Crow courtrooms, clients facing the electric chair \u2014 and defends the poor and powerless with unembarrassed consistency.", "photo": "photos/marshall.jpg"}, {"key": "blackmun", "name": "Harry Blackmun", "meta": "Nixon appointee (R)", "blurb": "The Mayo Clinic's meticulous former counsel, an anxious drafter who agonizes over every case. Once dismissed as Burger's 'Minnesota Twin,' he is drifting from the Chief, case by case, toward a path of his own.", "photo": "photos/blackmun.jpg"}, {"key": "powell", "name": "Lewis Powell", "meta": "Nixon appointee (R)", "blurb": "A courtly Richmond corporate lawyer and former ABA president, newly arrived on the bench. The establishment's ideal judge: moderate, balancing, allergic to extremes \u2014 he weighs each case like a client matter and lands, usually, near the center.", "photo": "photos/powell.jpg"}, {"key": "rehnquist", "name": "William Rehnquist", "meta": "Nixon appointee (R)", "blurb": "The junior justice and its boldest conservative \u2014 a 47-year-old Nixon Justice Department lawyer with a brilliant pen and no fear of standing alone. He doubts much of what the Warren Court built.", "photo": "photos/rehnquist.jpg"}, {"key": "stevens", "name": "John Paul Stevens", "meta": "Ford appointee (R)", "blurb": "The newest justice, a bow-tied Chicago antitrust lawyer chosen by Gerald Ford for sheer legal craftsmanship. He belongs to no bloc, writes separate opinions constantly, and steers by his own idiosyncratic compass.", "photo": "photos/stevens.jpg"}], "votes": {"burger": "yes", "brennan": "no", "stewart": "yes", "white": "yes", "marshall": "no", "blackmun": "yes", "powell": "yes", "rehnquist": "yes", "stevens": "yes"}}, {"id": "boy-scouts-v-dale", "era": "The Rehnquist Court \u00b7 October Term 1999", "caseTitle": "Boy Scouts of America v. Dale", "question": "Does the First Amendment let the Boy Scouts expel a gay assistant scoutmaster?", "desc": "Dale, an assistant scoutmaster in Monmouth Council, was expelled in 1990 after the Scouts learned he was co-president of the Rutgers gay and lesbian student alliance. He sued under New Jersey's public-accommodations law, and the state's highest court ordered him reinstated. The Scouts \u2014 six million strong, chartered by Congress \u2014 say homosexuality contradicts the oath's promise to be 'morally straight,' and that forcing them to keep Dale rewrites their message. Dale says a scout troop is not a debating society, and discrimination is not speech.", "intro": "James Dale is an Eagle Scout with a decade of merit badges \u2014 until a newspaper photo identifies him as a leader of a gay campus group, and the Boy Scouts revoke his membership by letter. New Jersey law says they can't.", "decided": "June 28, 2000", "split": "5\u20134", "answer": "yes", "justices": [{"key": "rehnquist", "name": "William Rehnquist", "meta": "Nixon appointee (R)", "blurb": "Chief Justice for nearly two decades, a genial and ruthlessly efficient administrator with a lifelong project: reviving states' rights and reining in Washington. He has spent his whole career waiting for the votes he now has.", "photo": "photos/rehnquist.jpg", "chief": true}, {"key": "stevens", "name": "John Paul Stevens", "meta": "Ford appointee (R)", "blurb": "The senior associate justice, a bow-tied Ford appointee from Chicago who now marshals the Court's liberal wing. Fiercely independent in method, he assigns the dissents whenever the Chief is on the other side.", "photo": "photos/stevens.jpg"}, {"key": "oconnor", "name": "Sandra Day O'Connor", "meta": "Reagan appointee (R)", "blurb": "A former Arizona legislator and the Court's pivotal vote \u2014 by common consent the most powerful woman in America. She distrusts absolutes and decides case by case; where she lands is usually where the law lands.", "photo": "photos/oconnor.jpg"}, {"key": "scalia", "name": "Antonin Scalia", "meta": "Reagan appointee (R)", "blurb": "The Court's combative originalist, its funniest questioner and its fiercest dissenter. He wants clear rules drawn from text and history, and treats his colleagues' balancing tests as legislation in robes.", "photo": "photos/scalia.jpg"}, {"key": "kennedy", "name": "Anthony Kennedy", "meta": "Reagan appointee (R)", "blurb": "A courtly Sacramento Republican with a taste for sweeping language about liberty and dignity. Conservative by default but persuadable at the margins \u2014 one of the two votes every advocate in the courtroom is chasing.", "photo": "photos/kennedy.jpg"}, {"key": "souter", "name": "David Souter", "meta": "George H. W. Bush appointee (R)", "blurb": "The first President Bush's 'stealth nominee,' a frugal New Hampshire bachelor who confounded his sponsors by settling into the moderate-liberal wing. A common-law traditionalist, devoted to precedent and wary of bold constitutional lurches.", "photo": "photos/souter.jpg"}, {"key": "thomas", "name": "Clarence Thomas", "meta": "George H. W. Bush appointee (R)", "blurb": "The Court's most uncompromising originalist, silent at argument and fearless in print. He would rather overrule a wrong precedent than trim it, and he stakes out positions no other justice will yet join.", "photo": "photos/thomas.jpg"}, {"key": "ginsburg", "name": "Ruth Bader Ginsburg", "meta": "Clinton appointee (D)", "blurb": "The ACLU litigator who dismantled sex-discrimination law brick by brick, now a precise, soft-spoken justice. A minimalist by temperament and a reliable liberal vote on questions of equal citizenship.", "photo": "photos/ginsburg.jpg"}, {"key": "breyer", "name": "Stephen Breyer", "meta": "Clinton appointee (D)", "blurb": "The junior justice, a Harvard administrative-law professor who thinks in workable purposes rather than absolutes. Pragmatic, optimistic about government, and forever spinning elaborate hypotheticals from the bench.", "photo": "photos/breyer.jpg"}], "votes": {"rehnquist": "yes", "stevens": "no", "oconnor": "yes", "scalia": "yes", "kennedy": "yes", "souter": "no", "thomas": "yes", "ginsburg": "no", "breyer": "no"}}, {"id": "gideon-v-wainwright", "era": "The Warren Court \u00b7 October Term 1962", "caseTitle": "Gideon v. Wainwright", "question": "Must a state provide a lawyer to a criminal defendant too poor to hire one?", "desc": "Clarence Earl Gideon asked the trial judge for counsel; Florida appoints lawyers only in capital cases, so he cross-examined witnesses himself and drew five years. Twenty years ago, in Betts v. Brady, the Court held that states need not furnish counsel to poor defendants absent 'special circumstances.' Gideon, reading law in the prison library, insists the Constitution says otherwise. The Court has appointed Washington superlawyer Abe Fortas to argue his side \u2014 a hint, perhaps, of what it thinks of Betts.", "intro": "A Florida drifter, convicted of burglarizing a pool hall after defending himself at trial, mails the Supreme Court a five-page petition written in pencil on prison stationery. The Court takes his case.", "decided": "March 18, 1963", "split": "9\u20130", "answer": "yes", "justices": [{"key": "warren", "name": "Earl Warren", "meta": "Eisenhower appointee (R)", "blurb": "The former California governor, now the most consequential Chief Justice in a century. He asks lawyers one question \u2014 'But is it fair?' \u2014 and works the conference like the politician he never stopped being.", "photo": "photos/warren.jpg", "chief": true}, {"key": "black", "name": "Hugo Black", "meta": "Franklin Roosevelt appointee (D)", "blurb": "An Alabama New Dealer who carries the Constitution in his coat pocket and reads it literally. 'No law' means no law \u2014 but rights he cannot find in the text, he will not invent.", "photo": "photos/black.jpg"}, {"key": "douglas", "name": "William O. Douglas", "meta": "Franklin Roosevelt appointee (D)", "blurb": "A restless westerner and the Court's fastest pen \u2014 impatient with doctrine, indifferent to precedent, and instinctively on the side of the lone individual against the government in nearly any form it takes.", "photo": "photos/douglas.jpg"}, {"key": "clark", "name": "Tom C. Clark", "meta": "Truman appointee (D)", "blurb": "Truman's Attorney General in a trademark bow tie \u2014 the Court's law-and-order Texan. He backs the police and the prosecutor by instinct, but he ran federal law enforcement himself and knows its temptations from the inside.", "photo": "photos/clark.jpg"}, {"key": "harlan", "name": "John Marshall Harlan", "meta": "Eisenhower appointee (R)", "blurb": "The Wall Street patrician and grandson of a great dissenter \u2014 the Court's conservative conscience. He believes in ordered liberty and lawyerly process, and objects, elegantly, when the majority moves too far, too fast.", "photo": "photos/harlan.jpg"}, {"key": "brennan", "name": "William Brennan", "meta": "Eisenhower appointee (R)", "blurb": "The Court's Irish charmer and master coalition-builder, an Eisenhower appointee who turned out to be its most effective liberal. His first rule of the shop: with five votes, you can do anything.", "photo": "photos/brennan.jpg"}, {"key": "stewart", "name": "Potter Stewart", "meta": "Eisenhower appointee (R)", "blurb": "A moderate Ohio Republican who resists both blocs' grand theories. He decides cases one at a time, asks what the Constitution actually commands, and lands \u2014 unpredictably \u2014 somewhere in the middle.", "photo": "photos/stewart.jpg"}, {"key": "white", "name": "Byron White", "meta": "Kennedy appointee (D)", "blurb": "'Whizzer' White, the All-American halfback turned Kennedy's deputy attorney general \u2014 tough-minded, unsentimental, and skeptical of newly minted rights, especially the kind that make police work harder.", "photo": "photos/white.jpg"}, {"key": "goldberg", "name": "Arthur Goldberg", "meta": "Kennedy appointee (D)", "blurb": "Kennedy's labor secretary, new to the bench in Frankfurter's old seat and his opposite in every way: an exuberant liberal who believes the Constitution grows, and that the Court should help it along.", "photo": "photos/goldberg.jpg"}], "votes": {"warren": "yes", "black": "yes", "douglas": "yes", "clark": "yes", "harlan": "yes", "brennan": "yes", "stewart": "yes", "white": "yes", "goldberg": "yes"}}, {"id": "reed-v-reed", "era": "The Burger Court \u00b7 October Term 1971", "caseTitle": "Reed v. Reed", "question": "May a state automatically prefer men over women for the job of administering an estate?", "desc": "Sally Reed's teenage son died by his own hand, leaving an estate worth less than a thousand dollars; the probate court appointed her estranged ex-husband to administer it, as Idaho law commanded whenever a man and a woman were equally entitled. A Rutgers law professor named Ruth Bader Ginsburg co-writes the ACLU's brief attacking the statute. In more than a century under the Fourteenth Amendment, the Court has never once struck down a law for discriminating against women. A seven-member bench \u2014 two seats vacant \u2014 hears the case.", "intro": "Boise, Idaho. A separated couple both ask to administer their dead son's tiny estate, and Idaho law settles the tie automatically: 'males must be preferred to females.'", "decided": "November 22, 1971", "split": "7\u20130", "answer": "no", "justices": [{"key": "burger", "name": "Warren Burger", "meta": "Nixon appointee (R)", "blurb": "Nixon's chief justice, installed to steady a Court he believes ran wild under Earl Warren. A stickler for order and the dignity of institutions, he is more cautious conservative than crusader \u2014 and ever mindful of the Court's public standing.", "photo": "photos/burger.jpg", "chief": true}, {"key": "douglas", "name": "William O. Douglas", "meta": "Franklin Roosevelt appointee (D)", "blurb": "A New Deal wunderkind grown into the Court's absolutist loner \u2014 three decades on the bench, four wives, a shelf of his own books. He votes for the individual against the government almost reflexively, and writes opinions at breakneck speed.", "photo": "photos/douglas.jpg"}, {"key": "brennan", "name": "William Brennan", "meta": "Eisenhower appointee (R)", "blurb": "The Warren Court's master coalition-builder, an Eisenhower appointee turned architect of its liberal revolution. His first rule \u2014 with five votes you can do anything \u2014 still guides him as the bench tilts rightward around him.", "photo": "photos/brennan.jpg"}, {"key": "stewart", "name": "Potter Stewart", "meta": "Eisenhower appointee (R)", "blurb": "A pragmatic Ohio Republican wary of grand theory, he decides cases narrowly and one at a time. Neither wing can count on him: he distrusts government overreach and judicial adventure in roughly equal measure.", "photo": "photos/stewart.jpg"}, {"key": "white", "name": "Byron White", "meta": "Kennedy appointee (D)", "blurb": "The Kennedys' deputy attorney general, an All-America halfback turned no-nonsense pragmatist. Tough on crime and skeptical of newly minted rights, yet often found with the liberals on race and civil rights.", "photo": "photos/white.jpg"}, {"key": "marshall", "name": "Thurgood Marshall", "meta": "Lyndon Johnson appointee (D)", "blurb": "The architect of Brown v. Board and the Court's first Black justice. He judges from lived experience \u2014 Jim Crow courtrooms, clients facing the electric chair \u2014 and defends the poor and powerless with unembarrassed consistency.", "photo": "photos/marshall.jpg"}, {"key": "blackmun", "name": "Harry Blackmun", "meta": "Nixon appointee (R)", "blurb": "The junior justice, a shy Minnesota Republican and longtime counsel to the Mayo Clinic. Washington calls him and his boyhood friend the Chief the 'Minnesota Twins' \u2014 so far he votes Burger's way more often than not.", "photo": "photos/blackmun.jpg"}], "votes": {"burger": "no", "douglas": "no", "brennan": "no", "stewart": "no", "white": "no", "marshall": "no", "blackmun": "no"}}, {"id": "roe-v-wade", "era": "The Burger Court \u00b7 October Term 1972", "caseTitle": "Roe v. Wade", "question": "Does the constitutional right of privacy protect a woman's decision to end her pregnancy?", "desc": "Norma McCorvey, twenty-two, poor and pregnant for the third time, could not lawfully end her pregnancy anywhere in Texas except to save her own life. Two young Texas lawyers built her case into an attack on the abortion laws of most of the nation. Argued twice \u2014 once before a short-handed bench, again before the full nine \u2014 the case asks whether the 'right of privacy' the Court found in the marital bedroom in 1965 reaches a woman's decision not to bear a child.", "intro": "A Dallas waitress suing under the name 'Jane Roe' challenges the Texas law \u2014 nearly a century old \u2014 that makes almost every abortion a crime.", "decided": "January 22, 1973", "split": "7\u20132", "answer": "yes", "justices": [{"key": "burger", "name": "Warren Burger", "meta": "Nixon appointee (R)", "blurb": "Nixon's chief justice, installed to steady a Court he believes ran wild under Earl Warren. A stickler for order and the dignity of institutions, he is more cautious conservative than crusader \u2014 and ever mindful of the Court's public standing.", "photo": "photos/burger.jpg", "chief": true}, {"key": "douglas", "name": "William O. Douglas", "meta": "Franklin Roosevelt appointee (D)", "blurb": "A New Deal wunderkind grown into the Court's absolutist loner \u2014 three decades on the bench, four wives, a shelf of his own books. He votes for the individual against the government almost reflexively, and writes opinions at breakneck speed.", "photo": "photos/douglas.jpg"}, {"key": "brennan", "name": "William Brennan", "meta": "Eisenhower appointee (R)", "blurb": "The Warren Court's master coalition-builder, an Eisenhower appointee turned architect of its liberal revolution. His first rule \u2014 with five votes you can do anything \u2014 still guides him as the bench tilts rightward around him.", "photo": "photos/brennan.jpg"}, {"key": "stewart", "name": "Potter Stewart", "meta": "Eisenhower appointee (R)", "blurb": "A pragmatic Ohio Republican wary of grand theory, he decides cases narrowly and one at a time. Neither wing can count on him: he distrusts government overreach and judicial adventure in roughly equal measure.", "photo": "photos/stewart.jpg"}, {"key": "white", "name": "Byron White", "meta": "Kennedy appointee (D)", "blurb": "The Kennedys' deputy attorney general, an All-America halfback turned no-nonsense pragmatist. Tough on crime and skeptical of newly minted rights, yet often found with the liberals on race and civil rights.", "photo": "photos/white.jpg"}, {"key": "marshall", "name": "Thurgood Marshall", "meta": "Lyndon Johnson appointee (D)", "blurb": "The architect of Brown v. Board and the Court's first Black justice. He judges from lived experience \u2014 Jim Crow courtrooms, clients facing the electric chair \u2014 and defends the poor and powerless with unembarrassed consistency.", "photo": "photos/marshall.jpg"}, {"key": "blackmun", "name": "Harry Blackmun", "meta": "Nixon appointee (R)", "blurb": "The junior justice, a shy Minnesota Republican and longtime counsel to the Mayo Clinic. Washington calls him and his boyhood friend the Chief the 'Minnesota Twins' \u2014 so far he votes Burger's way more often than not.", "photo": "photos/blackmun.jpg"}, {"key": "powell", "name": "Lewis Powell", "meta": "Nixon appointee (R)", "blurb": "A courtly Richmond corporate lawyer and former ABA president, newly arrived on the bench. The establishment's ideal judge: moderate, balancing, allergic to extremes \u2014 he weighs each case like a client matter and lands, usually, near the center.", "photo": "photos/powell.jpg"}, {"key": "rehnquist", "name": "William Rehnquist", "meta": "Nixon appointee (R)", "blurb": "The junior justice and its boldest conservative \u2014 a 47-year-old Nixon Justice Department lawyer with a brilliant pen and no fear of standing alone. He doubts much of what the Warren Court built.", "photo": "photos/rehnquist.jpg"}], "votes": {"burger": "yes", "douglas": "yes", "brennan": "yes", "stewart": "yes", "white": "no", "marshall": "yes", "blackmun": "yes", "powell": "yes", "rehnquist": "no"}}, {"id": "times-v-sullivan", "era": "The Warren Court \u00b7 October Term 1963", "caseTitle": "New York Times v. Sullivan", "question": "Does the First Amendment shield the press from libel judgments won by public officials over honest errors?", "desc": "'Heed Their Rising Voices,' a 1960 fund-raising ad for Martin Luther King's legal defense, got small details wrong \u2014 which song the protesters sang, how many times King had been arrested. Montgomery commissioner L.B. Sullivan, never named in the ad, sued the Times and won half a million dollars. Under Alabama law, false statements get no protection and damage is simply presumed. Southern officials have discovered that libel law can do what censorship cannot: drive the national press out of the segregation story.", "intro": "An Alabama jury has ordered the New York Times to pay $500,000 over a civil-rights advertisement containing minor mistakes. Dozens of similar suits are queued behind it \u2014 enough to bankrupt every paper covering the South.", "decided": "March 9, 1964", "split": "9\u20130", "answer": "yes", "justices": [{"key": "warren", "name": "Earl Warren", "meta": "Eisenhower appointee (R)", "blurb": "The former California governor, now the most consequential Chief Justice in a century. He asks lawyers one question \u2014 'But is it fair?' \u2014 and works the conference like the politician he never stopped being.", "photo": "photos/warren.jpg", "chief": true}, {"key": "black", "name": "Hugo Black", "meta": "Franklin Roosevelt appointee (D)", "blurb": "An Alabama New Dealer who carries the Constitution in his coat pocket and reads it literally. 'No law' means no law \u2014 but rights he cannot find in the text, he will not invent.", "photo": "photos/black.jpg"}, {"key": "douglas", "name": "William O. Douglas", "meta": "Franklin Roosevelt appointee (D)", "blurb": "A restless westerner and the Court's fastest pen \u2014 impatient with doctrine, indifferent to precedent, and instinctively on the side of the lone individual against the government in nearly any form it takes.", "photo": "photos/douglas.jpg"}, {"key": "clark", "name": "Tom C. Clark", "meta": "Truman appointee (D)", "blurb": "Truman's Attorney General in a trademark bow tie \u2014 the Court's law-and-order Texan. He backs the police and the prosecutor by instinct, but he ran federal law enforcement himself and knows its temptations from the inside.", "photo": "photos/clark.jpg"}, {"key": "harlan", "name": "John Marshall Harlan", "meta": "Eisenhower appointee (R)", "blurb": "The Wall Street patrician and grandson of a great dissenter \u2014 the Court's conservative conscience. He believes in ordered liberty and lawyerly process, and objects, elegantly, when the majority moves too far, too fast.", "photo": "photos/harlan.jpg"}, {"key": "brennan", "name": "William Brennan", "meta": "Eisenhower appointee (R)", "blurb": "The Court's Irish charmer and master coalition-builder, an Eisenhower appointee who turned out to be its most effective liberal. His first rule of the shop: with five votes, you can do anything.", "photo": "photos/brennan.jpg"}, {"key": "stewart", "name": "Potter Stewart", "meta": "Eisenhower appointee (R)", "blurb": "A moderate Ohio Republican who resists both blocs' grand theories. He decides cases one at a time, asks what the Constitution actually commands, and lands \u2014 unpredictably \u2014 somewhere in the middle.", "photo": "photos/stewart.jpg"}, {"key": "white", "name": "Byron White", "meta": "Kennedy appointee (D)", "blurb": "'Whizzer' White, the All-American halfback turned Kennedy's deputy attorney general \u2014 tough-minded, unsentimental, and skeptical of newly minted rights, especially the kind that make police work harder.", "photo": "photos/white.jpg"}, {"key": "goldberg", "name": "Arthur Goldberg", "meta": "Kennedy appointee (D)", "blurb": "Kennedy's labor secretary, new to the bench in Frankfurter's old seat and his opposite in every way: an exuberant liberal who believes the Constitution grows, and that the Court should help it along.", "photo": "photos/goldberg.jpg"}], "votes": {"warren": "yes", "black": "yes", "douglas": "yes", "clark": "yes", "harlan": "yes", "brennan": "yes", "stewart": "yes", "white": "yes", "goldberg": "yes"}}, {"id": "303-creative-v-elenis", "era": "The Roberts Court \u00b7 October Term 2022", "caseTitle": "303 Creative v. Elenis", "question": "May a state require a designer of custom wedding websites to create them for same-sex weddings over her religious objections?", "desc": "Lorie Smith says Colorado's public-accommodations law would force her to design websites celebrating marriages her Christianity opposes, on pain of investigation and fines \u2014 so she went to court preemptively, before taking a single wedding client. The state answers that a business selling a service must sell it to everyone; her lawyers answer that custom websites are speech, and Colorado is scripting it. Five years after the baker's case, the compelled-speech question arrives clean.", "intro": "A Colorado web designer wants to build wedding sites \u2014 but not for same-sex weddings, which her faith rejects. She sued before designing a single one. The question Masterpiece Cakeshop sidestepped is back, framed as pure speech.", "decided": "June 30, 2023", "split": "6\u20133", "answer": "no", "justices": [{"key": "roberts", "name": "John Roberts", "meta": "George W. Bush appointee (R)", "blurb": "No longer the Court's median vote \u2014 a six-justice conservative majority can now rule without him. He still preaches minimalism and frets over the institution's standing, hunting for narrower paths that his colleagues increasingly decline to take.", "photo": "photos/roberts.jpg", "chief": true}, {"key": "thomas_roberts", "name": "Clarence Thomas", "meta": "George H. W. Bush appointee (R)", "blurb": "The Court's most uncompromising originalist, fearless in print: he will discard decades of precedent without apology and stake out positions entirely alone, serenely confident the law will someday catch up to him.", "photo": "photos/thomas_roberts.jpg"}, {"key": "alito", "name": "Samuel Alito", "meta": "George W. Bush appointee (R)", "blurb": "A former federal prosecutor from New Jersey, methodical and unflashy, with the most reliably conservative instincts on the bench \u2014 above all where crime, religion, or the culture wars are concerned. In dissent, his pen turns acid.", "photo": "photos/alito.jpg"}, {"key": "sotomayor", "name": "Sonia Sotomayor", "meta": "Obama appointee (D)", "blurb": "From a Bronx housing project to Princeton to the federal trial bench: the first Latina justice never lets the Court forget how doctrine lands on actual people. A former prosecutor, relentless at argument, the liberal wing's most passionate voice.", "photo": "photos/sotomayor.jpg"}, {"key": "kagan", "name": "Elena Kagan", "meta": "Obama appointee (D)", "blurb": "The former Harvard Law dean and solicitor general, a coalition-builder who learned her politics in the Clinton White House. The liberal wing's tactician: she writes in plain, wry English and plays a patient long game of her own.", "photo": "photos/kagan.jpg"}, {"key": "gorsuch", "name": "Neil Gorsuch", "meta": "Trump appointee (R)", "blurb": "Scalia's successor and a true-believing textualist from Colorado: read the words, then follow them off a cliff if necessary. A westerner with a libertarian streak, he votes his method wherever it leads \u2014 to either camp's occasional dismay.", "photo": "photos/gorsuch.jpg"}, {"key": "kavanaugh", "name": "Brett Kavanaugh", "meta": "Trump appointee (R)", "blurb": "Confirmed after the most explosive hearings in memory, the former Bush White House aide works at looking reassuringly conventional: a conservative who prizes stability, writes separately to narrow things, and courts the middle whenever there is one.", "photo": "photos/kavanaugh.jpg"}, {"key": "barrett", "name": "Amy Coney Barrett", "meta": "Trump appointee (R)", "blurb": "Scalia's former clerk and a Notre Dame law professor, elevated to the bench days before a presidential election. An academic originalist \u2014 careful, methodical, unshowy \u2014 still drawing her own map of where method and caution part ways.", "photo": "photos/barrett.jpg"}, {"key": "jackson", "name": "Ketanji Brown Jackson", "meta": "Biden appointee (D)", "blurb": "The first Black woman on the Court and its first former public defender. She brings a trial judge's practicality, a performer's timing at oral argument, and no apparent interest in waiting her turn to be heard.", "photo": "photos/jackson.jpg"}], "votes": {"roberts": "no", "thomas_roberts": "no", "alito": "no", "sotomayor": "yes", "kagan": "yes", "gorsuch": "no", "kavanaugh": "no", "barrett": "no", "jackson": "yes"}}, {"id": "us-v-nixon", "era": "The Burger Court \u00b7 October Term 1973", "caseTitle": "United States v. Nixon", "question": "Must the President surrender his White House tapes to a criminal subpoena?", "desc": "The subpoena names the President of the United States and the tapes everyone knows exist \u2014 the ones with eighteen and a half minutes already missing. Nixon's lawyers argue no court can compel the executive; the special prosecutor answers that no man, president or not, may withhold evidence from a criminal trial. William Rehnquist, a Nixon Justice Department alumnus, has recused himself. The country waits to learn whether the Court's writ runs to the Oval Office.", "intro": "July 1974. The Watergate special prosecutor wants sixty-four White House tapes. The President claims an absolute executive privilege over his own conversations. Eight justices \u2014 three of them Nixon appointees \u2014 must decide, with impeachment hearings already underway.", "decided": "July 24, 1974", "split": "8\u20130", "answer": "yes", "justices": [{"key": "burger", "name": "Warren Burger", "meta": "Nixon appointee (R)", "blurb": "Nixon's chief justice, installed to steady a Court he believes ran wild under Earl Warren. A stickler for order and the dignity of institutions, he is more cautious conservative than crusader \u2014 and ever mindful of the Court's public standing.", "photo": "photos/burger.jpg", "chief": true}, {"key": "douglas", "name": "William O. Douglas", "meta": "Franklin Roosevelt appointee (D)", "blurb": "A New Deal wunderkind grown into the Court's absolutist loner \u2014 three decades on the bench, four wives, a shelf of his own books. He votes for the individual against the government almost reflexively, and writes opinions at breakneck speed.", "photo": "photos/douglas.jpg"}, {"key": "brennan", "name": "William Brennan", "meta": "Eisenhower appointee (R)", "blurb": "The Warren Court's master coalition-builder, an Eisenhower appointee turned architect of its liberal revolution. His first rule \u2014 with five votes you can do anything \u2014 still guides him as the bench tilts rightward around him.", "photo": "photos/brennan.jpg"}, {"key": "stewart", "name": "Potter Stewart", "meta": "Eisenhower appointee (R)", "blurb": "A pragmatic Ohio Republican wary of grand theory, he decides cases narrowly and one at a time. Neither wing can count on him: he distrusts government overreach and judicial adventure in roughly equal measure.", "photo": "photos/stewart.jpg"}, {"key": "white", "name": "Byron White", "meta": "Kennedy appointee (D)", "blurb": "The Kennedys' deputy attorney general, an All-America halfback turned no-nonsense pragmatist. Tough on crime and skeptical of newly minted rights, yet often found with the liberals on race and civil rights.", "photo": "photos/white.jpg"}, {"key": "marshall", "name": "Thurgood Marshall", "meta": "Lyndon Johnson appointee (D)", "blurb": "The architect of Brown v. Board and the Court's first Black justice. He judges from lived experience \u2014 Jim Crow courtrooms, clients facing the electric chair \u2014 and defends the poor and powerless with unembarrassed consistency.", "photo": "photos/marshall.jpg"}, {"key": "blackmun", "name": "Harry Blackmun", "meta": "Nixon appointee (R)", "blurb": "The junior justice, a shy Minnesota Republican and longtime counsel to the Mayo Clinic. Washington calls him and his boyhood friend the Chief the 'Minnesota Twins' \u2014 so far he votes Burger's way more often than not.", "photo": "photos/blackmun.jpg"}, {"key": "powell", "name": "Lewis Powell", "meta": "Nixon appointee (R)", "blurb": "A courtly Richmond corporate lawyer and former ABA president, newly arrived on the bench. The establishment's ideal judge: moderate, balancing, allergic to extremes \u2014 he weighs each case like a client matter and lands, usually, near the center.", "photo": "photos/powell.jpg"}], "votes": {"burger": "yes", "douglas": "yes", "brennan": "yes", "stewart": "yes", "white": "yes", "marshall": "yes", "blackmun": "yes", "powell": "yes"}}, {"id": "clinton-v-jones", "era": "The Rehnquist Court \u00b7 October Term 1996", "caseTitle": "Clinton v. Jones", "question": "Can a private lawsuit against a sitting president go forward while he holds office?", "desc": "Paula Corbin Jones alleges that Bill Clinton, while governor of Arkansas, had a state trooper summon her to his suite at the Excelsior Hotel and crudely propositioned her; she filed a federal civil-rights suit in 1994 seeking $700,000. Clinton's lawyers argue the presidency is a full-time constitutional office \u2014 that litigation would distract the chief executive and invite a flood of politically motivated suits. Nixon v. Fitzgerald immunized presidents for official acts; this conduct, everyone agrees, was nothing of the kind.", "intro": "A former Arkansas state clerk sues the President of the United States over what she says happened in a Little Rock hotel room in 1991. The White House asks the courts to wait until he leaves office. She asks why a president is different.", "decided": "May 27, 1997", "split": "9\u20130", "answer": "yes", "justices": [{"key": "rehnquist", "name": "William Rehnquist", "meta": "Nixon appointee (R)", "blurb": "Chief Justice for nearly two decades, a genial and ruthlessly efficient administrator with a lifelong project: reviving states' rights and reining in Washington. He has spent his whole career waiting for the votes he now has.", "photo": "photos/rehnquist.jpg", "chief": true}, {"key": "stevens", "name": "John Paul Stevens", "meta": "Ford appointee (R)", "blurb": "The senior associate justice, a bow-tied Ford appointee from Chicago who now marshals the Court's liberal wing. Fiercely independent in method, he assigns the dissents whenever the Chief is on the other side.", "photo": "photos/stevens.jpg"}, {"key": "oconnor", "name": "Sandra Day O'Connor", "meta": "Reagan appointee (R)", "blurb": "A former Arizona legislator and the Court's pivotal vote \u2014 by common consent the most powerful woman in America. She distrusts absolutes and decides case by case; where she lands is usually where the law lands.", "photo": "photos/oconnor.jpg"}, {"key": "scalia", "name": "Antonin Scalia", "meta": "Reagan appointee (R)", "blurb": "The Court's combative originalist, its funniest questioner and its fiercest dissenter. He wants clear rules drawn from text and history, and treats his colleagues' balancing tests as legislation in robes.", "photo": "photos/scalia.jpg"}, {"key": "kennedy", "name": "Anthony Kennedy", "meta": "Reagan appointee (R)", "blurb": "A courtly Sacramento Republican with a taste for sweeping language about liberty and dignity. Conservative by default but persuadable at the margins \u2014 one of the two votes every advocate in the courtroom is chasing.", "photo": "photos/kennedy.jpg"}, {"key": "souter", "name": "David Souter", "meta": "George H. W. Bush appointee (R)", "blurb": "The first President Bush's 'stealth nominee,' a frugal New Hampshire bachelor who confounded his sponsors by settling into the moderate-liberal wing. A common-law traditionalist, devoted to precedent and wary of bold constitutional lurches.", "photo": "photos/souter.jpg"}, {"key": "thomas", "name": "Clarence Thomas", "meta": "George H. W. Bush appointee (R)", "blurb": "The Court's most uncompromising originalist, silent at argument and fearless in print. He would rather overrule a wrong precedent than trim it, and he stakes out positions no other justice will yet join.", "photo": "photos/thomas.jpg"}, {"key": "ginsburg", "name": "Ruth Bader Ginsburg", "meta": "Clinton appointee (D)", "blurb": "The ACLU litigator who dismantled sex-discrimination law brick by brick, now a precise, soft-spoken justice. A minimalist by temperament and a reliable liberal vote on questions of equal citizenship.", "photo": "photos/ginsburg.jpg"}, {"key": "breyer", "name": "Stephen Breyer", "meta": "Clinton appointee (D)", "blurb": "The junior justice, a Harvard administrative-law professor who thinks in workable purposes rather than absolutes. Pragmatic, optimistic about government, and forever spinning elaborate hypotheticals from the bench.", "photo": "photos/breyer.jpg"}], "votes": {"rehnquist": "yes", "stevens": "yes", "oconnor": "yes", "scalia": "yes", "kennedy": "yes", "souter": "yes", "thomas": "yes", "ginsburg": "yes", "breyer": "yes"}}, {"id": "griswold-v-connecticut", "era": "The Warren Court \u00b7 October Term 1964", "caseTitle": "Griswold v. Connecticut", "question": "May a state make it a crime for married couples to use contraceptives?", "desc": "Connecticut forbids using 'any drug or article' to prevent conception and punishes anyone who counsels it \u2014 a law enforced just often enough to keep birth-control clinics closed. Griswold and Yale physician C. Lee Buxton were fined $100 apiece for advising married couples. No privacy clause appears anywhere in the Constitution, and the justices must decide whether one is implied \u2014 or whether, as the skeptics warn, striking down a silly law would revive the free-wheeling judicial lawmaking of the Lochner era.", "intro": "Estelle Griswold opened a Planned Parenthood clinic in New Haven and was arrested within ten days \u2014 exactly as she planned. Connecticut's 1879 ban on contraception is finally before the Court.", "decided": "June 7, 1965", "split": "7\u20132", "answer": "no", "justices": [{"key": "warren", "name": "Earl Warren", "meta": "Eisenhower appointee (R)", "blurb": "The former California governor, now the most consequential Chief Justice in a century. He asks lawyers one question \u2014 'But is it fair?' \u2014 and works the conference like the politician he never stopped being.", "photo": "photos/warren.jpg", "chief": true}, {"key": "black", "name": "Hugo Black", "meta": "Franklin Roosevelt appointee (D)", "blurb": "An Alabama New Dealer who carries the Constitution in his coat pocket and reads it literally. 'No law' means no law \u2014 but rights he cannot find in the text, he will not invent.", "photo": "photos/black.jpg"}, {"key": "douglas", "name": "William O. Douglas", "meta": "Franklin Roosevelt appointee (D)", "blurb": "A restless westerner and the Court's fastest pen \u2014 impatient with doctrine, indifferent to precedent, and instinctively on the side of the lone individual against the government in nearly any form it takes.", "photo": "photos/douglas.jpg"}, {"key": "clark", "name": "Tom C. Clark", "meta": "Truman appointee (D)", "blurb": "Truman's Attorney General in a trademark bow tie \u2014 the Court's law-and-order Texan. He backs the police and the prosecutor by instinct, but he ran federal law enforcement himself and knows its temptations from the inside.", "photo": "photos/clark.jpg"}, {"key": "harlan", "name": "John Marshall Harlan", "meta": "Eisenhower appointee (R)", "blurb": "The Wall Street patrician and grandson of a great dissenter \u2014 the Court's conservative conscience. He believes in ordered liberty and lawyerly process, and objects, elegantly, when the majority moves too far, too fast.", "photo": "photos/harlan.jpg"}, {"key": "brennan", "name": "William Brennan", "meta": "Eisenhower appointee (R)", "blurb": "The Court's Irish charmer and master coalition-builder, an Eisenhower appointee who turned out to be its most effective liberal. His first rule of the shop: with five votes, you can do anything.", "photo": "photos/brennan.jpg"}, {"key": "stewart", "name": "Potter Stewart", "meta": "Eisenhower appointee (R)", "blurb": "A moderate Ohio Republican who resists both blocs' grand theories. He decides cases one at a time, asks what the Constitution actually commands, and lands \u2014 unpredictably \u2014 somewhere in the middle.", "photo": "photos/stewart.jpg"}, {"key": "white", "name": "Byron White", "meta": "Kennedy appointee (D)", "blurb": "'Whizzer' White, the All-American halfback turned Kennedy's deputy attorney general \u2014 tough-minded, unsentimental, and skeptical of newly minted rights, especially the kind that make police work harder.", "photo": "photos/white.jpg"}, {"key": "goldberg", "name": "Arthur Goldberg", "meta": "Kennedy appointee (D)", "blurb": "Kennedy's labor secretary, new to the bench in Frankfurter's old seat and his opposite in every way: an exuberant liberal who believes the Constitution grows, and that the Court should help it along.", "photo": "photos/goldberg.jpg"}], "votes": {"warren": "no", "black": "yes", "douglas": "no", "clark": "no", "harlan": "no", "brennan": "no", "stewart": "yes", "white": "no", "goldberg": "no"}}, {"id": "tva-v-hill", "era": "The Burger Court \u00b7 October Term 1977", "caseTitle": "Tennessee Valley Authority v. Hill", "question": "Must a nearly finished federal dam be halted to protect an endangered fish?", "desc": "The Endangered Species Act of 1973 forbids federal actions that would destroy the critical habitat of a listed species. A University of Tennessee biologist discovered the snail darter in the very stretch of the Little Tennessee River the dam would flood, and a law student's lawsuit has kept the gates from closing. Congress, unmoved, keeps appropriating money for the project anyway. With tens of millions already spent, the Justices must decide whether a statute means exactly what it says \u2014 whatever the cost.", "intro": "The Tellico Dam is virtually complete after a decade of construction when a three-inch fish called the snail darter \u2014 found nowhere else on Earth \u2014 swims into the path of federal law.", "decided": "June 15, 1978", "split": "6\u20133", "answer": "yes", "justices": [{"key": "burger", "name": "Warren Burger", "meta": "Nixon appointee (R)", "blurb": "Nixon's chief justice, installed to steady a Court he believes ran wild under Earl Warren. A stickler for order and the dignity of institutions, he is more cautious conservative than crusader \u2014 and ever mindful of the Court's public standing.", "photo": "photos/burger.jpg", "chief": true}, {"key": "brennan", "name": "William Brennan", "meta": "Eisenhower appointee (R)", "blurb": "Twenty years on, the great liberal playmaker works a Court that has drifted away from him. He still counts to five better than anyone alive, hunting the center for partners case by case.", "photo": "photos/brennan.jpg"}, {"key": "stewart", "name": "Potter Stewart", "meta": "Eisenhower appointee (R)", "blurb": "The Court's studied centrist, a judge of narrow rulings and practical lines. Eighteen years in, he remains the man both blocs court \u2014 skeptical of absolutes, attentive to how the law actually operates.", "photo": "photos/stewart.jpg"}, {"key": "white", "name": "Byron White", "meta": "Kennedy appointee (D)", "blurb": "The Kennedys' deputy attorney general, an All-America halfback turned no-nonsense pragmatist. Tough on crime and skeptical of newly minted rights, yet often found with the liberals on race and civil rights.", "photo": "photos/white.jpg"}, {"key": "marshall", "name": "Thurgood Marshall", "meta": "Lyndon Johnson appointee (D)", "blurb": "The architect of Brown v. Board and the Court's first Black justice. He judges from lived experience \u2014 Jim Crow courtrooms, clients facing the electric chair \u2014 and defends the poor and powerless with unembarrassed consistency.", "photo": "photos/marshall.jpg"}, {"key": "blackmun", "name": "Harry Blackmun", "meta": "Nixon appointee (R)", "blurb": "The Mayo Clinic's meticulous former counsel, an anxious drafter who agonizes over every case. Once dismissed as Burger's 'Minnesota Twin,' he is drifting from the Chief, case by case, toward a path of his own.", "photo": "photos/blackmun.jpg"}, {"key": "powell", "name": "Lewis Powell", "meta": "Nixon appointee (R)", "blurb": "A courtly Richmond corporate lawyer and former ABA president, newly arrived on the bench. The establishment's ideal judge: moderate, balancing, allergic to extremes \u2014 he weighs each case like a client matter and lands, usually, near the center.", "photo": "photos/powell.jpg"}, {"key": "rehnquist", "name": "William Rehnquist", "meta": "Nixon appointee (R)", "blurb": "The junior justice and its boldest conservative \u2014 a 47-year-old Nixon Justice Department lawyer with a brilliant pen and no fear of standing alone. He doubts much of what the Warren Court built.", "photo": "photos/rehnquist.jpg"}, {"key": "stevens", "name": "John Paul Stevens", "meta": "Ford appointee (R)", "blurb": "The newest justice, a bow-tied Chicago antitrust lawyer chosen by Gerald Ford for sheer legal craftsmanship. He belongs to no bloc, writes separate opinions constantly, and steers by his own idiosyncratic compass.", "photo": "photos/stevens.jpg"}], "votes": {"burger": "yes", "brennan": "yes", "stewart": "yes", "white": "yes", "marshall": "yes", "blackmun": "no", "powell": "no", "rehnquist": "no", "stevens": "yes"}}, {"id": "bostock-v-clayton-county", "era": "The Roberts Court \u00b7 October Term 2019", "caseTitle": "Bostock v. Clayton County", "question": "Does Title VII's ban on employment discrimination 'because of sex' protect gay and transgender workers from being fired?", "desc": "Three cases arrive together: a Georgia child-welfare coordinator fired after joining a gay recreational league, a New York skydiving instructor fired days after mentioning he was gay, and a Michigan funeral director fired after telling her boss she was transgender. No federal statute names sexual orientation or gender identity. The workers argue you cannot fire a man for loving men without firing him 'because of sex' \u2014 turning textualism's own logic into the battlefield.", "intro": "Gerald Bostock says he was fired after joining a gay softball league. Title VII bans employment discrimination 'because of sex' \u2014 words written in 1964. The question is what those words cover in 2020.", "decided": "June 15, 2020", "split": "6\u20133", "answer": "yes", "justices": [{"key": "roberts", "name": "John Roberts", "meta": "George W. Bush appointee (R)", "blurb": "A dozen years in, the chief has become the Court's institutional conscience, insisting \u2014 especially in a polarized age \u2014 that it must not look like a political body. An incrementalist by temperament: he would rather decide little than decide loudly.", "photo": "photos/roberts.jpg", "chief": true}, {"key": "thomas_roberts", "name": "Clarence Thomas", "meta": "George H. W. Bush appointee (R)", "blurb": "The Court's most uncompromising originalist, fearless in print: he will discard decades of precedent without apology and stake out positions entirely alone, serenely confident the law will someday catch up to him.", "photo": "photos/thomas_roberts.jpg"}, {"key": "ginsburg_roberts", "name": "Ruth Bader Ginsburg", "meta": "Clinton appointee (D)", "blurb": "The pioneering women's-rights litigator of the 1970s, now the liberal wing's most exacting technician. Small, quiet, and precise, she picks her battles carefully \u2014 and reads her fiercest dissents aloud from the bench when she loses one.", "photo": "photos/ginsburg_roberts.jpg"}, {"key": "breyer_roberts", "name": "Stephen Breyer", "meta": "Clinton appointee (D)", "blurb": "The Court's pragmatist professor: a former Senate staffer and administrative-law scholar who judges by consequences, not grand theory. Endlessly optimistic about government, allergic to absolutes, and famous for winding hypotheticals that leave lawyers blinking.", "photo": "photos/breyer_roberts.jpg"}, {"key": "alito", "name": "Samuel Alito", "meta": "George W. Bush appointee (R)", "blurb": "A former federal prosecutor from New Jersey, methodical and unflashy, with the most reliably conservative instincts on the bench \u2014 above all where crime, religion, or the culture wars are concerned. In dissent, his pen turns acid.", "photo": "photos/alito.jpg"}, {"key": "sotomayor", "name": "Sonia Sotomayor", "meta": "Obama appointee (D)", "blurb": "From a Bronx housing project to Princeton to the federal trial bench: the first Latina justice never lets the Court forget how doctrine lands on actual people. A former prosecutor, relentless at argument, the liberal wing's most passionate voice.", "photo": "photos/sotomayor.jpg"}, {"key": "kagan", "name": "Elena Kagan", "meta": "Obama appointee (D)", "blurb": "The former Harvard Law dean and solicitor general, a coalition-builder who learned her politics in the Clinton White House. The liberal wing's tactician: she writes in plain, wry English and plays a patient long game of her own.", "photo": "photos/kagan.jpg"}, {"key": "gorsuch", "name": "Neil Gorsuch", "meta": "Trump appointee (R)", "blurb": "Scalia's successor and a true-believing textualist from Colorado: read the words, then follow them off a cliff if necessary. A westerner with a libertarian streak, he votes his method wherever it leads \u2014 to either camp's occasional dismay.", "photo": "photos/gorsuch.jpg"}, {"key": "kavanaugh", "name": "Brett Kavanaugh", "meta": "Trump appointee (R)", "blurb": "Confirmed after the most explosive hearings in memory, the former Bush White House aide works at looking reassuringly conventional: a conservative who prizes stability, writes separately to narrow things, and courts the middle whenever there is one.", "photo": "photos/kavanaugh.jpg"}], "votes": {"roberts": "yes", "thomas_roberts": "no", "ginsburg_roberts": "yes", "breyer_roberts": "yes", "alito": "no", "sotomayor": "yes", "kagan": "yes", "gorsuch": "yes", "kavanaugh": "no"}}, {"id": "romer-v-evans", "era": "The Rehnquist Court \u00b7 October Term 1995", "caseTitle": "Romer v. Evans", "question": "May a state constitution bar every law that protects gay people from discrimination?", "desc": "Passed by referendum in 1992, Amendment 2 repealed every local gay-rights ordinance in Colorado and forbade the state or any city from ever adopting another. Richard Evans, a Denver municipal employee, sued Governor Roy Romer \u2014 who had campaigned against the measure he was now bound to defend. Colorado says the amendment merely denies 'special rights' and leaves gay citizens the same protections as everyone else. The challengers say it fences one class of people out of ordinary politics altogether.", "intro": "Denver, Boulder, and Aspen pass ordinances shielding gay residents from discrimination. Colorado's voters answer with Amendment 2, wiping the ordinances out statewide \u2014 and the fight moves from the ballot box to the Court.", "decided": "May 20, 1996", "split": "6\u20133", "answer": "no", "justices": [{"key": "rehnquist", "name": "William Rehnquist", "meta": "Nixon appointee (R)", "blurb": "Chief Justice for nearly two decades, a genial and ruthlessly efficient administrator with a lifelong project: reviving states' rights and reining in Washington. He has spent his whole career waiting for the votes he now has.", "photo": "photos/rehnquist.jpg", "chief": true}, {"key": "stevens", "name": "John Paul Stevens", "meta": "Ford appointee (R)", "blurb": "The senior associate justice, a bow-tied Ford appointee from Chicago who now marshals the Court's liberal wing. Fiercely independent in method, he assigns the dissents whenever the Chief is on the other side.", "photo": "photos/stevens.jpg"}, {"key": "oconnor", "name": "Sandra Day O'Connor", "meta": "Reagan appointee (R)", "blurb": "A former Arizona legislator and the Court's pivotal vote \u2014 by common consent the most powerful woman in America. She distrusts absolutes and decides case by case; where she lands is usually where the law lands.", "photo": "photos/oconnor.jpg"}, {"key": "scalia", "name": "Antonin Scalia", "meta": "Reagan appointee (R)", "blurb": "The Court's combative originalist, its funniest questioner and its fiercest dissenter. He wants clear rules drawn from text and history, and treats his colleagues' balancing tests as legislation in robes.", "photo": "photos/scalia.jpg"}, {"key": "kennedy", "name": "Anthony Kennedy", "meta": "Reagan appointee (R)", "blurb": "A courtly Sacramento Republican with a taste for sweeping language about liberty and dignity. Conservative by default but persuadable at the margins \u2014 one of the two votes every advocate in the courtroom is chasing.", "photo": "photos/kennedy.jpg"}, {"key": "souter", "name": "David Souter", "meta": "George H. W. Bush appointee (R)", "blurb": "The first President Bush's 'stealth nominee,' a frugal New Hampshire bachelor who confounded his sponsors by settling into the moderate-liberal wing. A common-law traditionalist, devoted to precedent and wary of bold constitutional lurches.", "photo": "photos/souter.jpg"}, {"key": "thomas", "name": "Clarence Thomas", "meta": "George H. W. Bush appointee (R)", "blurb": "The Court's most uncompromising originalist, silent at argument and fearless in print. He would rather overrule a wrong precedent than trim it, and he stakes out positions no other justice will yet join.", "photo": "photos/thomas.jpg"}, {"key": "ginsburg", "name": "Ruth Bader Ginsburg", "meta": "Clinton appointee (D)", "blurb": "The ACLU litigator who dismantled sex-discrimination law brick by brick, now a precise, soft-spoken justice. A minimalist by temperament and a reliable liberal vote on questions of equal citizenship.", "photo": "photos/ginsburg.jpg"}, {"key": "breyer", "name": "Stephen Breyer", "meta": "Clinton appointee (D)", "blurb": "The junior justice, a Harvard administrative-law professor who thinks in workable purposes rather than absolutes. Pragmatic, optimistic about government, and forever spinning elaborate hypotheticals from the bench.", "photo": "photos/breyer.jpg"}], "votes": {"rehnquist": "yes", "stevens": "no", "oconnor": "no", "scalia": "yes", "kennedy": "no", "souter": "no", "thomas": "yes", "ginsburg": "no", "breyer": "no"}}, {"id": "carpenter-v-united-states", "era": "The Roberts Court \u00b7 October Term 2017", "caseTitle": "Carpenter v. United States", "question": "Must the government get a warrant before obtaining months of a suspect's cell-phone location records?", "desc": "Carriers log a phone's position every time it connects to a tower, and under a 1986 statute the government collected 12,898 location points tracing Carpenter's movements for four months \u2014 enough to convict him of robbing cell-phone stores. Under the 'third-party doctrine,' records you share with a company get no Fourth Amendment protection: a rule built for the age of landlines and bank slips. Carpenter's lawyers call cell records a time machine into anyone's entire life.", "intro": "To tie Timothy Carpenter to a string of armed robberies, the FBI obtained 127 days of his cell-phone location records \u2014 no warrant required. The question: does the Fourth Amendment know what a smartphone is?", "decided": "June 22, 2018", "split": "5\u20134", "answer": "yes", "justices": [{"key": "roberts", "name": "John Roberts", "meta": "George W. Bush appointee (R)", "blurb": "A dozen years in, the chief has become the Court's institutional conscience, insisting \u2014 especially in a polarized age \u2014 that it must not look like a political body. An incrementalist by temperament: he would rather decide little than decide loudly.", "photo": "photos/roberts.jpg", "chief": true}, {"key": "kennedy_roberts", "name": "Anthony Kennedy", "meta": "Reagan appointee (R)", "blurb": "The swing. A courtly Sacramento Republican who controls the outcome in nearly every close case \u2014 and knows it. Liberty and dignity are his lodestars, sweeping language his signature, suspense his permanent gift to Court-watchers.", "photo": "photos/kennedy_roberts.jpg"}, {"key": "thomas_roberts", "name": "Clarence Thomas", "meta": "George H. W. Bush appointee (R)", "blurb": "The Court's most uncompromising originalist, fearless in print: he will discard decades of precedent without apology and stake out positions entirely alone, serenely confident the law will someday catch up to him.", "photo": "photos/thomas_roberts.jpg"}, {"key": "ginsburg_roberts", "name": "Ruth Bader Ginsburg", "meta": "Clinton appointee (D)", "blurb": "The pioneering women's-rights litigator of the 1970s, now the liberal wing's most exacting technician. Small, quiet, and precise, she picks her battles carefully \u2014 and reads her fiercest dissents aloud from the bench when she loses one.", "photo": "photos/ginsburg_roberts.jpg"}, {"key": "breyer_roberts", "name": "Stephen Breyer", "meta": "Clinton appointee (D)", "blurb": "The Court's pragmatist professor: a former Senate staffer and administrative-law scholar who judges by consequences, not grand theory. Endlessly optimistic about government, allergic to absolutes, and famous for winding hypotheticals that leave lawyers blinking.", "photo": "photos/breyer_roberts.jpg"}, {"key": "alito", "name": "Samuel Alito", "meta": "George W. Bush appointee (R)", "blurb": "A former federal prosecutor from New Jersey, methodical and unflashy, with the most reliably conservative instincts on the bench \u2014 above all where crime, religion, or the culture wars are concerned. In dissent, his pen turns acid.", "photo": "photos/alito.jpg"}, {"key": "sotomayor", "name": "Sonia Sotomayor", "meta": "Obama appointee (D)", "blurb": "From a Bronx housing project to Princeton to the federal trial bench: the first Latina justice never lets the Court forget how doctrine lands on actual people. A former prosecutor, relentless at argument, the liberal wing's most passionate voice.", "photo": "photos/sotomayor.jpg"}, {"key": "kagan", "name": "Elena Kagan", "meta": "Obama appointee (D)", "blurb": "The former Harvard Law dean and solicitor general, a coalition-builder who learned her politics in the Clinton White House. The liberal wing's tactician: she writes in plain, wry English and plays a patient long game of her own.", "photo": "photos/kagan.jpg"}, {"key": "gorsuch", "name": "Neil Gorsuch", "meta": "Trump appointee (R)", "blurb": "Scalia's successor and a true-believing textualist from Colorado: read the words, then follow them off a cliff if necessary. A westerner with a libertarian streak, he votes his method wherever it leads \u2014 to either camp's occasional dismay.", "photo": "photos/gorsuch.jpg"}], "votes": {"roberts": "yes", "kennedy_roberts": "no", "thomas_roberts": "no", "ginsburg_roberts": "yes", "breyer_roberts": "yes", "alito": "no", "sotomayor": "yes", "kagan": "yes", "gorsuch": "no"}}, {"id": "nysrpa-v-bruen", "era": "The Roberts Court \u00b7 October Term 2021", "caseTitle": "New York State Rifle & Pistol Assn. v. Bruen", "question": "Does the Second Amendment protect a right to carry a handgun in public for self-defense?", "desc": "Since 1911, New York has demanded that anyone seeking to carry a concealed pistol show a particular need for self-protection \u2014 ordinary fear of crime doesn't qualify, and licensing officers hold broad discretion. Two upstate men, denied unrestricted permits, sued alongside the state rifle association. Heller secured the handgun in the home but said little about the street. Half a dozen states with similar laws cover a quarter of the country's population \u2014 including its biggest cities.", "intro": "New York will license your handgun at home; carrying it outside requires 'proper cause' \u2014 a special need beyond wanting protection. Fourteen years after Heller, the Second Amendment steps out the front door.", "decided": "June 23, 2022", "split": "6\u20133", "answer": "yes", "justices": [{"key": "roberts", "name": "John Roberts", "meta": "George W. Bush appointee (R)", "blurb": "No longer the Court's median vote \u2014 a six-justice conservative majority can now rule without him. He still preaches minimalism and frets over the institution's standing, hunting for narrower paths that his colleagues increasingly decline to take.", "photo": "photos/roberts.jpg", "chief": true}, {"key": "thomas_roberts", "name": "Clarence Thomas", "meta": "George H. W. Bush appointee (R)", "blurb": "The Court's most uncompromising originalist, fearless in print: he will discard decades of precedent without apology and stake out positions entirely alone, serenely confident the law will someday catch up to him.", "photo": "photos/thomas_roberts.jpg"}, {"key": "breyer_roberts", "name": "Stephen Breyer", "meta": "Clinton appointee (D)", "blurb": "The Court's pragmatist professor: a former Senate staffer and administrative-law scholar who judges by consequences, not grand theory. Endlessly optimistic about government, allergic to absolutes, and famous for winding hypotheticals that leave lawyers blinking.", "photo": "photos/breyer_roberts.jpg"}, {"key": "alito", "name": "Samuel Alito", "meta": "George W. Bush appointee (R)", "blurb": "A former federal prosecutor from New Jersey, methodical and unflashy, with the most reliably conservative instincts on the bench \u2014 above all where crime, religion, or the culture wars are concerned. In dissent, his pen turns acid.", "photo": "photos/alito.jpg"}, {"key": "sotomayor", "name": "Sonia Sotomayor", "meta": "Obama appointee (D)", "blurb": "From a Bronx housing project to Princeton to the federal trial bench: the first Latina justice never lets the Court forget how doctrine lands on actual people. A former prosecutor, relentless at argument, the liberal wing's most passionate voice.", "photo": "photos/sotomayor.jpg"}, {"key": "kagan", "name": "Elena Kagan", "meta": "Obama appointee (D)", "blurb": "The former Harvard Law dean and solicitor general, a coalition-builder who learned her politics in the Clinton White House. The liberal wing's tactician: she writes in plain, wry English and plays a patient long game of her own.", "photo": "photos/kagan.jpg"}, {"key": "gorsuch", "name": "Neil Gorsuch", "meta": "Trump appointee (R)", "blurb": "Scalia's successor and a true-believing textualist from Colorado: read the words, then follow them off a cliff if necessary. A westerner with a libertarian streak, he votes his method wherever it leads \u2014 to either camp's occasional dismay.", "photo": "photos/gorsuch.jpg"}, {"key": "kavanaugh", "name": "Brett Kavanaugh", "meta": "Trump appointee (R)", "blurb": "Confirmed after the most explosive hearings in memory, the former Bush White House aide works at looking reassuringly conventional: a conservative who prizes stability, writes separately to narrow things, and courts the middle whenever there is one.", "photo": "photos/kavanaugh.jpg"}, {"key": "barrett", "name": "Amy Coney Barrett", "meta": "Trump appointee (R)", "blurb": "Scalia's former clerk and a Notre Dame law professor, elevated to the bench days before a presidential election. An academic originalist \u2014 careful, methodical, unshowy \u2014 still drawing her own map of where method and caution part ways.", "photo": "photos/barrett.jpg"}], "votes": {"roberts": "yes", "thomas_roberts": "yes", "breyer_roberts": "no", "alito": "yes", "sotomayor": "no", "kagan": "no", "gorsuch": "yes", "kavanaugh": "yes", "barrett": "yes"}}, {"id": "terry-v-ohio", "era": "The Warren Court \u00b7 October Term 1967", "caseTitle": "Terry v. Ohio", "question": "May an officer stop and frisk a suspect without probable cause for an arrest?", "desc": "Detective Martin McFadden had 39 years on the beat but no probable cause for an arrest when he frisked Terry \u2014 only trained suspicion. The pistol he found made the conviction; the question is whether it was ever lawfully found. Police call the street stop basic self-preservation in an armed country. Civil-rights lawyers, a year after Newark and Detroit burned, warn the Court it is about to license the wholesale harassment of Black men. The Fourth Amendment, both sides note, forbids only 'unreasonable' searches.", "intro": "A veteran Cleveland detective watches two men pace past a storefront a dozen times, conferring after each pass. Certain they are casing it, he spins John Terry around and pats him down \u2014 and finds a revolver.", "decided": "June 10, 1968", "split": "8\u20131", "answer": "yes", "justices": [{"key": "warren", "name": "Earl Warren", "meta": "Eisenhower appointee (R)", "blurb": "The former California governor, now the most consequential Chief Justice in a century. He asks lawyers one question \u2014 'But is it fair?' \u2014 and works the conference like the politician he never stopped being.", "photo": "photos/warren.jpg", "chief": true}, {"key": "black", "name": "Hugo Black", "meta": "Franklin Roosevelt appointee (D)", "blurb": "An Alabama New Dealer who carries the Constitution in his coat pocket and reads it literally. 'No law' means no law \u2014 but rights he cannot find in the text, he will not invent.", "photo": "photos/black.jpg"}, {"key": "douglas", "name": "William O. Douglas", "meta": "Franklin Roosevelt appointee (D)", "blurb": "A restless westerner and the Court's fastest pen \u2014 impatient with doctrine, indifferent to precedent, and instinctively on the side of the lone individual against the government in nearly any form it takes.", "photo": "photos/douglas.jpg"}, {"key": "harlan", "name": "John Marshall Harlan", "meta": "Eisenhower appointee (R)", "blurb": "The Wall Street patrician and grandson of a great dissenter \u2014 the Court's conservative conscience. He believes in ordered liberty and lawyerly process, and objects, elegantly, when the majority moves too far, too fast.", "photo": "photos/harlan.jpg"}, {"key": "brennan", "name": "William Brennan", "meta": "Eisenhower appointee (R)", "blurb": "The Court's Irish charmer and master coalition-builder, an Eisenhower appointee who turned out to be its most effective liberal. His first rule of the shop: with five votes, you can do anything.", "photo": "photos/brennan.jpg"}, {"key": "stewart", "name": "Potter Stewart", "meta": "Eisenhower appointee (R)", "blurb": "A moderate Ohio Republican who resists both blocs' grand theories. He decides cases one at a time, asks what the Constitution actually commands, and lands \u2014 unpredictably \u2014 somewhere in the middle.", "photo": "photos/stewart.jpg"}, {"key": "white", "name": "Byron White", "meta": "Kennedy appointee (D)", "blurb": "'Whizzer' White, the All-American halfback turned Kennedy's deputy attorney general \u2014 tough-minded, unsentimental, and skeptical of newly minted rights, especially the kind that make police work harder.", "photo": "photos/white.jpg"}, {"key": "fortas", "name": "Abe Fortas", "meta": "Lyndon Johnson appointee (D)", "blurb": "LBJ's confidant and Washington's premier lawyer, still quietly advising the President from the bench. As an advocate he won poor defendants their counsel; as a justice he champions the underdog \u2014 children included.", "photo": "photos/fortas.jpg"}, {"key": "marshall", "name": "Thurgood Marshall", "meta": "Lyndon Johnson appointee (D)", "blurb": "The architect of the NAACP's litigation war on Jim Crow and the first Black justice \u2014 a storyteller who has seen the criminal law from the defendant's side of the table and never forgets it.", "photo": "photos/marshall.jpg"}], "votes": {"warren": "yes", "black": "yes", "douglas": "no", "harlan": "yes", "brennan": "yes", "stewart": "yes", "white": "yes", "fortas": "yes", "marshall": "yes"}}, {"id": "shelby-county-v-holder", "era": "The Roberts Court \u00b7 October Term 2012", "caseTitle": "Shelby County v. Holder", "question": "May Congress keep requiring selected states, under a decades-old coverage formula, to get federal approval before changing their voting laws?", "desc": "The Voting Rights Act's preclearance regime made the federal government the South's election monitor, and Congress reauthorized it in 2006 \u2014 98 to 0 in the Senate. But the formula deciding which states are covered still turns on registration data from the 1960s and '70s. Shelby County, Alabama, says the emergency is over and the old map unconstitutional; civil-rights veterans answer that the law works precisely because it has never been allowed to lapse. The Court must decide whether history still governs.", "intro": "Since 1965, states with histories of discrimination have needed Washington's permission to change their election rules. An Alabama county argues the South of 2013 should no longer be judged by the sins of 1965.", "decided": "June 25, 2013", "split": "5\u20134", "answer": "no", "justices": [{"key": "roberts", "name": "John Roberts", "meta": "George W. Bush appointee (R)", "blurb": "The chief justice who won the job promising to call balls and strikes, not pitch or bat. A polished Supreme Court advocate turned umpire, he prefers narrow rulings and unanimity where he can get them \u2014 and moves the law by patient inches when he can't.", "photo": "photos/roberts.jpg", "chief": true}, {"key": "scalia_roberts", "name": "Antonin Scalia", "meta": "Reagan appointee (R)", "blurb": "Originalism's happy warrior, decades into his crusade to read the Constitution as its ratifiers understood it. His opinions are the Court's best copy, his scorn for 'living constitutionalism' legendary \u2014 and his method has reshaped how every case is argued.", "photo": "photos/scalia_roberts.jpg"}, {"key": "kennedy_roberts", "name": "Anthony Kennedy", "meta": "Reagan appointee (R)", "blurb": "The swing. A courtly Sacramento Republican who controls the outcome in nearly every close case \u2014 and knows it. Liberty and dignity are his lodestars, sweeping language his signature, suspense his permanent gift to Court-watchers.", "photo": "photos/kennedy_roberts.jpg"}, {"key": "thomas_roberts", "name": "Clarence Thomas", "meta": "George H. W. Bush appointee (R)", "blurb": "The Court's most uncompromising originalist, fearless in print: he will discard decades of precedent without apology and stake out positions entirely alone, serenely confident the law will someday catch up to him.", "photo": "photos/thomas_roberts.jpg"}, {"key": "ginsburg_roberts", "name": "Ruth Bader Ginsburg", "meta": "Clinton appointee (D)", "blurb": "The pioneering women's-rights litigator of the 1970s, now the liberal wing's most exacting technician. Small, quiet, and precise, she picks her battles carefully \u2014 and reads her fiercest dissents aloud from the bench when she loses one.", "photo": "photos/ginsburg_roberts.jpg"}, {"key": "breyer_roberts", "name": "Stephen Breyer", "meta": "Clinton appointee (D)", "blurb": "The Court's pragmatist professor: a former Senate staffer and administrative-law scholar who judges by consequences, not grand theory. Endlessly optimistic about government, allergic to absolutes, and famous for winding hypotheticals that leave lawyers blinking.", "photo": "photos/breyer_roberts.jpg"}, {"key": "alito", "name": "Samuel Alito", "meta": "George W. Bush appointee (R)", "blurb": "A former federal prosecutor from New Jersey, methodical and unflashy, with the most reliably conservative instincts on the bench \u2014 above all where crime, religion, or the culture wars are concerned. In dissent, his pen turns acid.", "photo": "photos/alito.jpg"}, {"key": "sotomayor", "name": "Sonia Sotomayor", "meta": "Obama appointee (D)", "blurb": "From a Bronx housing project to Princeton to the federal trial bench: the first Latina justice never lets the Court forget how doctrine lands on actual people. A former prosecutor, relentless at argument, the liberal wing's most passionate voice.", "photo": "photos/sotomayor.jpg"}, {"key": "kagan", "name": "Elena Kagan", "meta": "Obama appointee (D)", "blurb": "The former Harvard Law dean and solicitor general, a coalition-builder who learned her politics in the Clinton White House. The liberal wing's tactician: she writes in plain, wry English and plays a patient long game of her own.", "photo": "photos/kagan.jpg"}], "votes": {"roberts": "no", "scalia_roberts": "no", "kennedy_roberts": "no", "thomas_roberts": "no", "ginsburg_roberts": "yes", "breyer_roberts": "yes", "alito": "no", "sotomayor": "yes", "kagan": "yes"}}, {"id": "escobedo-v-illinois", "era": "The Warren Court \u00b7 October Term 1963", "caseTitle": "Escobedo v. Illinois", "question": "Does a suspect have the right to consult his lawyer during a police interrogation?", "desc": "Escobedo, a 22-year-old laborer, was arrested for his brother-in-law's murder and questioned through the night, handcuffed and standing. His retained lawyer was in the building for hours and repeatedly turned away while officers urged Escobedo to pin the shooting on another man \u2014 statements that convicted him instead. The right to counsel has always attached at trial; prosecutors warn that extending it into the squad room would end confessions altogether. Defense lawyers answer that a right which begins after the confession comes too late.", "intro": "Chicago, 1960. Danny Escobedo's lawyer stands in the station house demanding to see his client; down the hall, detectives tell Escobedo his lawyer 'didn't want to see' him. By morning they have a confession.", "decided": "June 22, 1964", "split": "5\u20134", "answer": "yes", "justices": [{"key": "warren", "name": "Earl Warren", "meta": "Eisenhower appointee (R)", "blurb": "The former California governor, now the most consequential Chief Justice in a century. He asks lawyers one question \u2014 'But is it fair?' \u2014 and works the conference like the politician he never stopped being.", "photo": "photos/warren.jpg", "chief": true}, {"key": "black", "name": "Hugo Black", "meta": "Franklin Roosevelt appointee (D)", "blurb": "An Alabama New Dealer who carries the Constitution in his coat pocket and reads it literally. 'No law' means no law \u2014 but rights he cannot find in the text, he will not invent.", "photo": "photos/black.jpg"}, {"key": "douglas", "name": "William O. Douglas", "meta": "Franklin Roosevelt appointee (D)", "blurb": "A restless westerner and the Court's fastest pen \u2014 impatient with doctrine, indifferent to precedent, and instinctively on the side of the lone individual against the government in nearly any form it takes.", "photo": "photos/douglas.jpg"}, {"key": "clark", "name": "Tom C. Clark", "meta": "Truman appointee (D)", "blurb": "Truman's Attorney General in a trademark bow tie \u2014 the Court's law-and-order Texan. He backs the police and the prosecutor by instinct, but he ran federal law enforcement himself and knows its temptations from the inside.", "photo": "photos/clark.jpg"}, {"key": "harlan", "name": "John Marshall Harlan", "meta": "Eisenhower appointee (R)", "blurb": "The Wall Street patrician and grandson of a great dissenter \u2014 the Court's conservative conscience. He believes in ordered liberty and lawyerly process, and objects, elegantly, when the majority moves too far, too fast.", "photo": "photos/harlan.jpg"}, {"key": "brennan", "name": "William Brennan", "meta": "Eisenhower appointee (R)", "blurb": "The Court's Irish charmer and master coalition-builder, an Eisenhower appointee who turned out to be its most effective liberal. His first rule of the shop: with five votes, you can do anything.", "photo": "photos/brennan.jpg"}, {"key": "stewart", "name": "Potter Stewart", "meta": "Eisenhower appointee (R)", "blurb": "A moderate Ohio Republican who resists both blocs' grand theories. He decides cases one at a time, asks what the Constitution actually commands, and lands \u2014 unpredictably \u2014 somewhere in the middle.", "photo": "photos/stewart.jpg"}, {"key": "white", "name": "Byron White", "meta": "Kennedy appointee (D)", "blurb": "'Whizzer' White, the All-American halfback turned Kennedy's deputy attorney general \u2014 tough-minded, unsentimental, and skeptical of newly minted rights, especially the kind that make police work harder.", "photo": "photos/white.jpg"}, {"key": "goldberg", "name": "Arthur Goldberg", "meta": "Kennedy appointee (D)", "blurb": "Kennedy's labor secretary, new to the bench in Frankfurter's old seat and his opposite in every way: an exuberant liberal who believes the Constitution grows, and that the Court should help it along.", "photo": "photos/goldberg.jpg"}], "votes": {"warren": "yes", "black": "yes", "douglas": "yes", "clark": "no", "harlan": "no", "brennan": "yes", "stewart": "no", "white": "no", "goldberg": "yes"}}, {"id": "us-v-lopez", "era": "The Rehnquist Court \u00b7 October Term 1994", "caseTitle": "United States v. Lopez", "question": "Does Congress's power over interstate commerce let it ban guns near schools?", "desc": "Alfonso Lopez Jr. was arrested under the federal Gun-Free School Zones Act of 1990, which makes it a federal crime to possess a gun within a thousand feet of a school. Since the New Deal, the Court has never met a commerce-clause claim it wouldn't sustain \u2014 the government argues that guns disrupt classrooms, classrooms produce workers, and workers feed the national economy. Skeptics answer that by that logic Congress could regulate anything at all, and the word 'commerce' would mean nothing.", "intro": "A San Antonio twelfth-grader walks into Edison High with a concealed .38 and five bullets. He is charged not under Texas law but under an act of Congress \u2014 and his lawyers ask what any of this has to do with interstate commerce.", "decided": "April 26, 1995", "split": "5\u20134", "answer": "no", "justices": [{"key": "rehnquist", "name": "William Rehnquist", "meta": "Nixon appointee (R)", "blurb": "Chief Justice for nearly two decades, a genial and ruthlessly efficient administrator with a lifelong project: reviving states' rights and reining in Washington. He has spent his whole career waiting for the votes he now has.", "photo": "photos/rehnquist.jpg", "chief": true}, {"key": "stevens", "name": "John Paul Stevens", "meta": "Ford appointee (R)", "blurb": "The senior associate justice, a bow-tied Ford appointee from Chicago who now marshals the Court's liberal wing. Fiercely independent in method, he assigns the dissents whenever the Chief is on the other side.", "photo": "photos/stevens.jpg"}, {"key": "oconnor", "name": "Sandra Day O'Connor", "meta": "Reagan appointee (R)", "blurb": "A former Arizona legislator and the Court's pivotal vote \u2014 by common consent the most powerful woman in America. She distrusts absolutes and decides case by case; where she lands is usually where the law lands.", "photo": "photos/oconnor.jpg"}, {"key": "scalia", "name": "Antonin Scalia", "meta": "Reagan appointee (R)", "blurb": "The Court's combative originalist, its funniest questioner and its fiercest dissenter. He wants clear rules drawn from text and history, and treats his colleagues' balancing tests as legislation in robes.", "photo": "photos/scalia.jpg"}, {"key": "kennedy", "name": "Anthony Kennedy", "meta": "Reagan appointee (R)", "blurb": "A courtly Sacramento Republican with a taste for sweeping language about liberty and dignity. Conservative by default but persuadable at the margins \u2014 one of the two votes every advocate in the courtroom is chasing.", "photo": "photos/kennedy.jpg"}, {"key": "souter", "name": "David Souter", "meta": "George H. W. Bush appointee (R)", "blurb": "The first President Bush's 'stealth nominee,' a frugal New Hampshire bachelor who confounded his sponsors by settling into the moderate-liberal wing. A common-law traditionalist, devoted to precedent and wary of bold constitutional lurches.", "photo": "photos/souter.jpg"}, {"key": "thomas", "name": "Clarence Thomas", "meta": "George H. W. Bush appointee (R)", "blurb": "The Court's most uncompromising originalist, silent at argument and fearless in print. He would rather overrule a wrong precedent than trim it, and he stakes out positions no other justice will yet join.", "photo": "photos/thomas.jpg"}, {"key": "ginsburg", "name": "Ruth Bader Ginsburg", "meta": "Clinton appointee (D)", "blurb": "The ACLU litigator who dismantled sex-discrimination law brick by brick, now a precise, soft-spoken justice. A minimalist by temperament and a reliable liberal vote on questions of equal citizenship.", "photo": "photos/ginsburg.jpg"}, {"key": "breyer", "name": "Stephen Breyer", "meta": "Clinton appointee (D)", "blurb": "The junior justice, a Harvard administrative-law professor who thinks in workable purposes rather than absolutes. Pragmatic, optimistic about government, and forever spinning elaborate hypotheticals from the bench.", "photo": "photos/breyer.jpg"}], "votes": {"rehnquist": "no", "stevens": "yes", "oconnor": "no", "scalia": "no", "kennedy": "no", "souter": "yes", "thomas": "no", "ginsburg": "yes", "breyer": "yes"}}, {"id": "miller-v-california", "era": "The Burger Court \u00b7 October Term 1972", "caseTitle": "Miller v. California", "question": "May a state ban the sale of obscene material, judged by local community standards?", "desc": "Marvin Miller ran a mail-order 'adult' business and blanketed California with graphic advertising; one envelope was opened by a Newport Beach restaurant owner and his mother. For sixteen years the Court has floundered over obscenity \u2014 screening seized films in its own basement, reversing convictions without ever agreeing on a test. Now, with four Nixon appointees seated, the question is whether local juries may judge obscenity by their own community's standards rather than a single national one.", "intro": "The sexual revolution meets the mailbox: a Los Angeles man mass-mails brochures for adult books, and one unwilling recipient's complaint becomes the test of what states may ban as obscene.", "decided": "June 21, 1973", "split": "5\u20134", "answer": "yes", "justices": [{"key": "burger", "name": "Warren Burger", "meta": "Nixon appointee (R)", "blurb": "Nixon's chief justice, installed to steady a Court he believes ran wild under Earl Warren. A stickler for order and the dignity of institutions, he is more cautious conservative than crusader \u2014 and ever mindful of the Court's public standing.", "photo": "photos/burger.jpg", "chief": true}, {"key": "douglas", "name": "William O. Douglas", "meta": "Franklin Roosevelt appointee (D)", "blurb": "A New Deal wunderkind grown into the Court's absolutist loner \u2014 three decades on the bench, four wives, a shelf of his own books. He votes for the individual against the government almost reflexively, and writes opinions at breakneck speed.", "photo": "photos/douglas.jpg"}, {"key": "brennan", "name": "William Brennan", "meta": "Eisenhower appointee (R)", "blurb": "The Warren Court's master coalition-builder, an Eisenhower appointee turned architect of its liberal revolution. His first rule \u2014 with five votes you can do anything \u2014 still guides him as the bench tilts rightward around him.", "photo": "photos/brennan.jpg"}, {"key": "stewart", "name": "Potter Stewart", "meta": "Eisenhower appointee (R)", "blurb": "A pragmatic Ohio Republican wary of grand theory, he decides cases narrowly and one at a time. Neither wing can count on him: he distrusts government overreach and judicial adventure in roughly equal measure.", "photo": "photos/stewart.jpg"}, {"key": "white", "name": "Byron White", "meta": "Kennedy appointee (D)", "blurb": "The Kennedys' deputy attorney general, an All-America halfback turned no-nonsense pragmatist. Tough on crime and skeptical of newly minted rights, yet often found with the liberals on race and civil rights.", "photo": "photos/white.jpg"}, {"key": "marshall", "name": "Thurgood Marshall", "meta": "Lyndon Johnson appointee (D)", "blurb": "The architect of Brown v. Board and the Court's first Black justice. He judges from lived experience \u2014 Jim Crow courtrooms, clients facing the electric chair \u2014 and defends the poor and powerless with unembarrassed consistency.", "photo": "photos/marshall.jpg"}, {"key": "blackmun", "name": "Harry Blackmun", "meta": "Nixon appointee (R)", "blurb": "The junior justice, a shy Minnesota Republican and longtime counsel to the Mayo Clinic. Washington calls him and his boyhood friend the Chief the 'Minnesota Twins' \u2014 so far he votes Burger's way more often than not.", "photo": "photos/blackmun.jpg"}, {"key": "powell", "name": "Lewis Powell", "meta": "Nixon appointee (R)", "blurb": "A courtly Richmond corporate lawyer and former ABA president, newly arrived on the bench. The establishment's ideal judge: moderate, balancing, allergic to extremes \u2014 he weighs each case like a client matter and lands, usually, near the center.", "photo": "photos/powell.jpg"}, {"key": "rehnquist", "name": "William Rehnquist", "meta": "Nixon appointee (R)", "blurb": "The junior justice and its boldest conservative \u2014 a 47-year-old Nixon Justice Department lawyer with a brilliant pen and no fear of standing alone. He doubts much of what the Warren Court built.", "photo": "photos/rehnquist.jpg"}], "votes": {"burger": "yes", "douglas": "no", "brennan": "no", "stewart": "no", "white": "yes", "marshall": "no", "blackmun": "yes", "powell": "yes", "rehnquist": "yes"}}, {"id": "masterpiece-cakeshop", "era": "The Roberts Court \u00b7 October Term 2017", "caseTitle": "Masterpiece Cakeshop v. Colorado", "question": "Did Colorado violate the Constitution when it punished a baker who refused to create a cake for a same-sex wedding?", "desc": "Jack Phillips will sell Charlie Craig and David Mullins anything in his shop \u2014 but not a custom cake celebrating their wedding, which his Christianity forbids. Colorado's civil-rights commission found illegal discrimination, and one commissioner compared religious-freedom arguments to defenses of slavery and the Holocaust. Phillips says the state is compelling his art and punishing his faith; the couple answers that a business open to the public must serve all of it. Both sides brace for a landmark.", "intro": "A Colorado baker turned away two men seeking a wedding cake, citing his faith. Five years of litigation later, the collision between gay rights and religious conscience reaches the Court on remarkably particular facts.", "decided": "June 4, 2018", "split": "7\u20132", "answer": "yes", "justices": [{"key": "roberts", "name": "John Roberts", "meta": "George W. Bush appointee (R)", "blurb": "A dozen years in, the chief has become the Court's institutional conscience, insisting \u2014 especially in a polarized age \u2014 that it must not look like a political body. An incrementalist by temperament: he would rather decide little than decide loudly.", "photo": "photos/roberts.jpg", "chief": true}, {"key": "kennedy_roberts", "name": "Anthony Kennedy", "meta": "Reagan appointee (R)", "blurb": "The swing. A courtly Sacramento Republican who controls the outcome in nearly every close case \u2014 and knows it. Liberty and dignity are his lodestars, sweeping language his signature, suspense his permanent gift to Court-watchers.", "photo": "photos/kennedy_roberts.jpg"}, {"key": "thomas_roberts", "name": "Clarence Thomas", "meta": "George H. W. Bush appointee (R)", "blurb": "The Court's most uncompromising originalist, fearless in print: he will discard decades of precedent without apology and stake out positions entirely alone, serenely confident the law will someday catch up to him.", "photo": "photos/thomas_roberts.jpg"}, {"key": "ginsburg_roberts", "name": "Ruth Bader Ginsburg", "meta": "Clinton appointee (D)", "blurb": "The pioneering women's-rights litigator of the 1970s, now the liberal wing's most exacting technician. Small, quiet, and precise, she picks her battles carefully \u2014 and reads her fiercest dissents aloud from the bench when she loses one.", "photo": "photos/ginsburg_roberts.jpg"}, {"key": "breyer_roberts", "name": "Stephen Breyer", "meta": "Clinton appointee (D)", "blurb": "The Court's pragmatist professor: a former Senate staffer and administrative-law scholar who judges by consequences, not grand theory. Endlessly optimistic about government, allergic to absolutes, and famous for winding hypotheticals that leave lawyers blinking.", "photo": "photos/breyer_roberts.jpg"}, {"key": "alito", "name": "Samuel Alito", "meta": "George W. Bush appointee (R)", "blurb": "A former federal prosecutor from New Jersey, methodical and unflashy, with the most reliably conservative instincts on the bench \u2014 above all where crime, religion, or the culture wars are concerned. In dissent, his pen turns acid.", "photo": "photos/alito.jpg"}, {"key": "sotomayor", "name": "Sonia Sotomayor", "meta": "Obama appointee (D)", "blurb": "From a Bronx housing project to Princeton to the federal trial bench: the first Latina justice never lets the Court forget how doctrine lands on actual people. A former prosecutor, relentless at argument, the liberal wing's most passionate voice.", "photo": "photos/sotomayor.jpg"}, {"key": "kagan", "name": "Elena Kagan", "meta": "Obama appointee (D)", "blurb": "The former Harvard Law dean and solicitor general, a coalition-builder who learned her politics in the Clinton White House. The liberal wing's tactician: she writes in plain, wry English and plays a patient long game of her own.", "photo": "photos/kagan.jpg"}, {"key": "gorsuch", "name": "Neil Gorsuch", "meta": "Trump appointee (R)", "blurb": "Scalia's successor and a true-believing textualist from Colorado: read the words, then follow them off a cliff if necessary. A westerner with a libertarian streak, he votes his method wherever it leads \u2014 to either camp's occasional dismay.", "photo": "photos/gorsuch.jpg"}], "votes": {"roberts": "yes", "kennedy_roberts": "yes", "thomas_roberts": "yes", "ginsburg_roberts": "no", "breyer_roberts": "yes", "alito": "yes", "sotomayor": "no", "kagan": "yes", "gorsuch": "yes"}}, {"id": "miranda-v-arizona", "era": "The Warren Court \u00b7 October Term 1965", "caseTitle": "Miranda v. Arizona", "question": "Must police warn a suspect of his rights before interrogating him?", "desc": "Miranda, a 23-year-old warehouse worker, signed a confession beneath a printed line saying he understood his rights; no one had told him what they were. Escobedo hinted two years ago that the Constitution reaches into the station house, and lower courts have split ever since. Four cases arrive together asking for a rule. Law enforcement warns that lawyers in the interrogation room mean the end of confessions; civil libertarians answer that the Fifth Amendment was never meant to carry an asterisk for the poor and unlettered.", "intro": "Ernesto Miranda confessed to kidnapping and rape after two hours in a Phoenix interrogation room \u2014 never told he could remain silent or see a lawyer. Police chiefs say the confession is the backbone of American policing.", "decided": "June 13, 1966", "split": "5\u20134", "answer": "yes", "justices": [{"key": "warren", "name": "Earl Warren", "meta": "Eisenhower appointee (R)", "blurb": "The former California governor, now the most consequential Chief Justice in a century. He asks lawyers one question \u2014 'But is it fair?' \u2014 and works the conference like the politician he never stopped being.", "photo": "photos/warren.jpg", "chief": true}, {"key": "black", "name": "Hugo Black", "meta": "Franklin Roosevelt appointee (D)", "blurb": "An Alabama New Dealer who carries the Constitution in his coat pocket and reads it literally. 'No law' means no law \u2014 but rights he cannot find in the text, he will not invent.", "photo": "photos/black.jpg"}, {"key": "douglas", "name": "William O. Douglas", "meta": "Franklin Roosevelt appointee (D)", "blurb": "A restless westerner and the Court's fastest pen \u2014 impatient with doctrine, indifferent to precedent, and instinctively on the side of the lone individual against the government in nearly any form it takes.", "photo": "photos/douglas.jpg"}, {"key": "clark", "name": "Tom C. Clark", "meta": "Truman appointee (D)", "blurb": "Truman's Attorney General in a trademark bow tie \u2014 the Court's law-and-order Texan. He backs the police and the prosecutor by instinct, but he ran federal law enforcement himself and knows its temptations from the inside.", "photo": "photos/clark.jpg"}, {"key": "harlan", "name": "John Marshall Harlan", "meta": "Eisenhower appointee (R)", "blurb": "The Wall Street patrician and grandson of a great dissenter \u2014 the Court's conservative conscience. He believes in ordered liberty and lawyerly process, and objects, elegantly, when the majority moves too far, too fast.", "photo": "photos/harlan.jpg"}, {"key": "brennan", "name": "William Brennan", "meta": "Eisenhower appointee (R)", "blurb": "The Court's Irish charmer and master coalition-builder, an Eisenhower appointee who turned out to be its most effective liberal. His first rule of the shop: with five votes, you can do anything.", "photo": "photos/brennan.jpg"}, {"key": "stewart", "name": "Potter Stewart", "meta": "Eisenhower appointee (R)", "blurb": "A moderate Ohio Republican who resists both blocs' grand theories. He decides cases one at a time, asks what the Constitution actually commands, and lands \u2014 unpredictably \u2014 somewhere in the middle.", "photo": "photos/stewart.jpg"}, {"key": "white", "name": "Byron White", "meta": "Kennedy appointee (D)", "blurb": "'Whizzer' White, the All-American halfback turned Kennedy's deputy attorney general \u2014 tough-minded, unsentimental, and skeptical of newly minted rights, especially the kind that make police work harder.", "photo": "photos/white.jpg"}, {"key": "fortas", "name": "Abe Fortas", "meta": "Lyndon Johnson appointee (D)", "blurb": "LBJ's confidant and Washington's premier lawyer, still quietly advising the President from the bench. As an advocate he won poor defendants their counsel; as a justice he champions the underdog \u2014 children included.", "photo": "photos/fortas.jpg"}], "votes": {"warren": "yes", "black": "yes", "douglas": "yes", "clark": "no", "harlan": "no", "brennan": "yes", "stewart": "no", "white": "no", "fortas": "yes"}}, {"id": "mapp-v-ohio", "era": "The Warren Court \u00b7 October Term 1960", "caseTitle": "Mapp v. Ohio", "question": "Must state courts throw out evidence that police obtained through an illegal search?", "desc": "Officers ransacked Mapp's home without a genuine warrant, found sexually explicit books in a trunk, and Ohio convicted her of possessing obscene material. Federal courts have excluded illegally seized evidence since 1914, but the Supreme Court has let each state decide for itself \u2014 and about half still admit whatever the police bring in, however they got it. Mapp's own lawyers barely raise the search issue, attacking the obscenity law instead. The deeper question: does the Fourth Amendment mean the same thing in state court?", "intro": "Cleveland, 1957. Police hunting a bombing suspect force their way into Dollree Mapp's house waving a paper they call a warrant. They never find their fugitive \u2014 but they prosecute her for what they do find.", "decided": "June 19, 1961", "split": "6\u20133", "answer": "yes", "justices": [{"key": "warren", "name": "Earl Warren", "meta": "Eisenhower appointee (R)", "blurb": "The former California governor, now the most consequential Chief Justice in a century. He asks lawyers one question \u2014 'But is it fair?' \u2014 and works the conference like the politician he never stopped being.", "photo": "photos/warren.jpg", "chief": true}, {"key": "black", "name": "Hugo Black", "meta": "Franklin Roosevelt appointee (D)", "blurb": "An Alabama New Dealer who carries the Constitution in his coat pocket and reads it literally. 'No law' means no law \u2014 but rights he cannot find in the text, he will not invent.", "photo": "photos/black.jpg"}, {"key": "frankfurter", "name": "Felix Frankfurter", "meta": "Franklin Roosevelt appointee (D)", "blurb": "The former Harvard professor and apostle of judicial restraint: courts, he preaches, must defer to legislatures even when the results offend. His seminars continue at conference, whether his colleagues want them or not.", "photo": "photos/frankfurter.jpg"}, {"key": "douglas", "name": "William O. Douglas", "meta": "Franklin Roosevelt appointee (D)", "blurb": "A restless westerner and the Court's fastest pen \u2014 impatient with doctrine, indifferent to precedent, and instinctively on the side of the lone individual against the government in nearly any form it takes.", "photo": "photos/douglas.jpg"}, {"key": "clark", "name": "Tom C. Clark", "meta": "Truman appointee (D)", "blurb": "Truman's Attorney General in a trademark bow tie \u2014 the Court's law-and-order Texan. He backs the police and the prosecutor by instinct, but he ran federal law enforcement himself and knows its temptations from the inside.", "photo": "photos/clark.jpg"}, {"key": "harlan", "name": "John Marshall Harlan", "meta": "Eisenhower appointee (R)", "blurb": "The Wall Street patrician and grandson of a great dissenter \u2014 the Court's conservative conscience. He believes in ordered liberty and lawyerly process, and objects, elegantly, when the majority moves too far, too fast.", "photo": "photos/harlan.jpg"}, {"key": "brennan", "name": "William Brennan", "meta": "Eisenhower appointee (R)", "blurb": "The Court's Irish charmer and master coalition-builder, an Eisenhower appointee who turned out to be its most effective liberal. His first rule of the shop: with five votes, you can do anything.", "photo": "photos/brennan.jpg"}, {"key": "whittaker", "name": "Charles Whittaker", "meta": "Eisenhower appointee (R)", "blurb": "A Missouri railroad lawyer who rose from farm poverty to the bench \u2014 cautious, conservative, and visibly agonized. Every close case is a torment; he is months from resigning under the strain.", "photo": "photos/whittaker.jpg"}, {"key": "stewart", "name": "Potter Stewart", "meta": "Eisenhower appointee (R)", "blurb": "A moderate Ohio Republican who resists both blocs' grand theories. He decides cases one at a time, asks what the Constitution actually commands, and lands \u2014 unpredictably \u2014 somewhere in the middle.", "photo": "photos/stewart.jpg"}], "votes": {"warren": "yes", "black": "yes", "frankfurter": "no", "douglas": "yes", "clark": "yes", "harlan": "no", "brennan": "yes", "whittaker": "no", "stewart": "yes"}}, {"id": "printz-v-us", "era": "The Rehnquist Court \u00b7 October Term 1996", "caseTitle": "Printz v. United States", "question": "May Congress order local sheriffs to run background checks on handgun buyers?", "desc": "Jay Printz, sheriff of Ravalli County, Montana, and Richard Mack of Graham County, Arizona, sued over the Brady Act's interim command that local chief law-enforcement officers perform federal background checks. The United States says it is a modest, temporary duty in service of an urgent national problem. The sheriffs say the Constitution created two governments, not one \u2014 and that Congress may no more commandeer a county sheriff than a state legislature. Nothing in the text answers it squarely; structure and history must.", "intro": "The Brady Bill is law, named for the press secretary shot beside President Reagan. Until a national instant-check system comes online, county sheriffs must vet every handgun sale \u2014 and two Western sheriffs say Washington cannot draft them.", "decided": "June 27, 1997", "split": "5\u20134", "answer": "no", "justices": [{"key": "rehnquist", "name": "William Rehnquist", "meta": "Nixon appointee (R)", "blurb": "Chief Justice for nearly two decades, a genial and ruthlessly efficient administrator with a lifelong project: reviving states' rights and reining in Washington. He has spent his whole career waiting for the votes he now has.", "photo": "photos/rehnquist.jpg", "chief": true}, {"key": "stevens", "name": "John Paul Stevens", "meta": "Ford appointee (R)", "blurb": "The senior associate justice, a bow-tied Ford appointee from Chicago who now marshals the Court's liberal wing. Fiercely independent in method, he assigns the dissents whenever the Chief is on the other side.", "photo": "photos/stevens.jpg"}, {"key": "oconnor", "name": "Sandra Day O'Connor", "meta": "Reagan appointee (R)", "blurb": "A former Arizona legislator and the Court's pivotal vote \u2014 by common consent the most powerful woman in America. She distrusts absolutes and decides case by case; where she lands is usually where the law lands.", "photo": "photos/oconnor.jpg"}, {"key": "scalia", "name": "Antonin Scalia", "meta": "Reagan appointee (R)", "blurb": "The Court's combative originalist, its funniest questioner and its fiercest dissenter. He wants clear rules drawn from text and history, and treats his colleagues' balancing tests as legislation in robes.", "photo": "photos/scalia.jpg"}, {"key": "kennedy", "name": "Anthony Kennedy", "meta": "Reagan appointee (R)", "blurb": "A courtly Sacramento Republican with a taste for sweeping language about liberty and dignity. Conservative by default but persuadable at the margins \u2014 one of the two votes every advocate in the courtroom is chasing.", "photo": "photos/kennedy.jpg"}, {"key": "souter", "name": "David Souter", "meta": "George H. W. Bush appointee (R)", "blurb": "The first President Bush's 'stealth nominee,' a frugal New Hampshire bachelor who confounded his sponsors by settling into the moderate-liberal wing. A common-law traditionalist, devoted to precedent and wary of bold constitutional lurches.", "photo": "photos/souter.jpg"}, {"key": "thomas", "name": "Clarence Thomas", "meta": "George H. W. Bush appointee (R)", "blurb": "The Court's most uncompromising originalist, silent at argument and fearless in print. He would rather overrule a wrong precedent than trim it, and he stakes out positions no other justice will yet join.", "photo": "photos/thomas.jpg"}, {"key": "ginsburg", "name": "Ruth Bader Ginsburg", "meta": "Clinton appointee (D)", "blurb": "The ACLU litigator who dismantled sex-discrimination law brick by brick, now a precise, soft-spoken justice. A minimalist by temperament and a reliable liberal vote on questions of equal citizenship.", "photo": "photos/ginsburg.jpg"}, {"key": "breyer", "name": "Stephen Breyer", "meta": "Clinton appointee (D)", "blurb": "The junior justice, a Harvard administrative-law professor who thinks in workable purposes rather than absolutes. Pragmatic, optimistic about government, and forever spinning elaborate hypotheticals from the bench.", "photo": "photos/breyer.jpg"}], "votes": {"rehnquist": "no", "stevens": "yes", "oconnor": "no", "scalia": "no", "kennedy": "no", "souter": "yes", "thomas": "no", "ginsburg": "yes", "breyer": "yes"}}, {"id": "brown-v-board", "era": "The Warren Court \u00b7 October Term 1953", "caseTitle": "Brown v. Board of Education", "question": "Does racial segregation of public schools violate the Constitution's guarantee of equal protection?", "desc": "Linda Brown walks past a whites-only school to catch a bus across Topeka. Black families in four states and the District are suing over segregated schools, and Plessy v. Ferguson's 'separate but equal' has stood for 58 years. The Justice Department calls segregation a Cold War embarrassment; the South promises massive resistance. The case has already been argued twice \u2014 the justices, deadlocked under the late Chief Justice Vinson, ordered reargument. Now Earl Warren must produce an answer the country can live with.", "intro": "Thurgood Marshall argues for the schoolchildren of Topeka; John W. Davis, in the last great case of his career, defends segregation. A brand-new Chief Justice presides over a question the Court has put off for years.", "decided": "May 17, 1954", "split": "9\u20130", "answer": "yes", "justices": [{"key": "warren54", "name": "Earl Warren", "meta": "Eisenhower appointee (R)", "blurb": "Eisenhower's brand-new Chief Justice: a three-term California governor with no judicial experience and a politician's gift for the personal touch. Washington is still guessing whether he will be a caretaker \u2014 or something else entirely.", "photo": "photos/warren54.jpg", "chief": true}, {"key": "black", "name": "Hugo Black", "meta": "Franklin Roosevelt appointee (D)", "blurb": "An Alabama New Dealer who carries the Constitution in his coat pocket and reads it literally. 'No law' means no law \u2014 but rights he cannot find in the text, he will not invent.", "photo": "photos/black.jpg"}, {"key": "reed", "name": "Stanley Reed", "meta": "Franklin Roosevelt appointee (D)", "blurb": "A courtly Kentuckian and FDR's former Solicitor General \u2014 a moderate New Dealer with Southern instincts, deeply anxious about how far, and how fast, nine unelected judges should push the country.", "photo": "photos/reed.jpg"}, {"key": "frankfurter", "name": "Felix Frankfurter", "meta": "Franklin Roosevelt appointee (D)", "blurb": "The former Harvard professor and apostle of judicial restraint: courts, he preaches, must defer to legislatures even when the results offend. His seminars continue at conference, whether his colleagues want them or not.", "photo": "photos/frankfurter.jpg"}, {"key": "douglas", "name": "William O. Douglas", "meta": "Franklin Roosevelt appointee (D)", "blurb": "A restless westerner and the Court's fastest pen \u2014 impatient with doctrine, indifferent to precedent, and instinctively on the side of the lone individual against the government in nearly any form it takes.", "photo": "photos/douglas.jpg"}, {"key": "rhjackson", "name": "Robert H. Jackson", "meta": "Franklin Roosevelt appointee (D)", "blurb": "FDR's Solicitor General and the chief Nuremberg prosecutor \u2014 the Court's finest stylist, just back from a heart attack, and wary of judicial power exercised without a firm footing in law.", "photo": "photos/rhjackson.jpg"}, {"key": "burton", "name": "Harold Burton", "meta": "Truman appointee (D)", "blurb": "A former Republican senator from Ohio appointed by his old colleague Harry Truman \u2014 a diligent, modest workhorse who reads every record and rarely makes headlines. Colleagues call him the fairest-minded man on the bench.", "photo": "photos/burton.jpg"}, {"key": "clark", "name": "Tom C. Clark", "meta": "Truman appointee (D)", "blurb": "Truman's Attorney General in a trademark bow tie \u2014 the Court's law-and-order Texan. He backs the police and the prosecutor by instinct, but he ran federal law enforcement himself and knows its temptations from the inside.", "photo": "photos/clark.jpg"}, {"key": "minton", "name": "Sherman Minton", "meta": "Truman appointee (D)", "blurb": "Truman's poker partner from Indiana, a former senator and loyal New Dealer who believes judging means restraint: the Court should follow the elected branches, not lead them anywhere.", "photo": "photos/minton.jpg"}], "votes": {"warren54": "yes", "black": "yes", "reed": "yes", "frankfurter": "yes", "douglas": "yes", "rhjackson": "yes", "burton": "yes", "clark": "yes", "minton": "yes"}}, {"id": "new-york-times-v-united-states", "era": "The Burger Court \u00b7 October Term 1970", "caseTitle": "New York Times Co. v. United States", "question": "May the government stop newspapers from publishing the classified Pentagon Papers?", "desc": "A defense analyst named Daniel Ellsberg has leaked 7,000 pages of classified Vietnam War history \u2014 the Pentagon Papers \u2014 to the press. A federal injunction has stopped the Times' presses for nearly two weeks, with the Washington Post enjoined close behind, while the government warns of grave damage to national security. The Justices hear argument on a Saturday and rule four days later \u2014 the fastest major case in memory, with the First Amendment's rule against prior restraint squarely on the line.", "intro": "June 1971. The New York Times begins printing a secret Pentagon history of the Vietnam War, and Nixon's Justice Department races into court to stop the presses \u2014 something no administration has ever done.", "decided": "June 30, 1971", "split": "6\u20133", "answer": "no", "justices": [{"key": "burger", "name": "Warren Burger", "meta": "Nixon appointee (R)", "blurb": "Nixon's chief justice, installed to steady a Court he believes ran wild under Earl Warren. A stickler for order and the dignity of institutions, he is more cautious conservative than crusader \u2014 and ever mindful of the Court's public standing.", "photo": "photos/burger.jpg", "chief": true}, {"key": "black", "name": "Hugo Black", "meta": "Franklin Roosevelt appointee (D)", "blurb": "At 85, the New Deal's last titan and the First Amendment's fiercest literalist \u2014 'no law abridging' means no law, period. Frail and near the end of 34 years on the bench, he still writes with the old fire.", "photo": "photos/black.jpg"}, {"key": "douglas", "name": "William O. Douglas", "meta": "Franklin Roosevelt appointee (D)", "blurb": "A New Deal wunderkind grown into the Court's absolutist loner \u2014 three decades on the bench, four wives, a shelf of his own books. He votes for the individual against the government almost reflexively, and writes opinions at breakneck speed.", "photo": "photos/douglas.jpg"}, {"key": "harlan", "name": "John Marshall Harlan", "meta": "Eisenhower appointee (R)", "blurb": "The Court's patrician conservative conscience, a lawyer's lawyer of precision and restraint. Nearly blind, he reads briefs held an inch from his eyes \u2014 and insists that judging is a matter of process and precedent, never passion.", "photo": "photos/harlan.jpg"}, {"key": "brennan", "name": "William Brennan", "meta": "Eisenhower appointee (R)", "blurb": "The Warren Court's master coalition-builder, an Eisenhower appointee turned architect of its liberal revolution. His first rule \u2014 with five votes you can do anything \u2014 still guides him as the bench tilts rightward around him.", "photo": "photos/brennan.jpg"}, {"key": "stewart", "name": "Potter Stewart", "meta": "Eisenhower appointee (R)", "blurb": "A pragmatic Ohio Republican wary of grand theory, he decides cases narrowly and one at a time. Neither wing can count on him: he distrusts government overreach and judicial adventure in roughly equal measure.", "photo": "photos/stewart.jpg"}, {"key": "white", "name": "Byron White", "meta": "Kennedy appointee (D)", "blurb": "The Kennedys' deputy attorney general, an All-America halfback turned no-nonsense pragmatist. Tough on crime and skeptical of newly minted rights, yet often found with the liberals on race and civil rights.", "photo": "photos/white.jpg"}, {"key": "marshall", "name": "Thurgood Marshall", "meta": "Lyndon Johnson appointee (D)", "blurb": "The architect of Brown v. Board and the Court's first Black justice. He judges from lived experience \u2014 Jim Crow courtrooms, clients facing the electric chair \u2014 and defends the poor and powerless with unembarrassed consistency.", "photo": "photos/marshall.jpg"}, {"key": "blackmun", "name": "Harry Blackmun", "meta": "Nixon appointee (R)", "blurb": "The junior justice, a shy Minnesota Republican and longtime counsel to the Mayo Clinic. Washington calls him and his boyhood friend the Chief the 'Minnesota Twins' \u2014 so far he votes Burger's way more often than not.", "photo": "photos/blackmun.jpg"}], "votes": {"burger": "yes", "black": "no", "douglas": "no", "harlan": "yes", "brennan": "no", "stewart": "no", "white": "no", "marshall": "no", "blackmun": "yes"}}, {"id": "batson-v-kentucky", "era": "The Burger Court \u00b7 October Term 1985", "caseTitle": "Batson v. Kentucky", "question": "Does a prosecutor's striking of jurors because of their race violate the Constitution?", "desc": "Peremptory challenges are as old as the jury itself: each side may strike a juror without giving any reason at all. Prosecutors have long used them, quietly, to keep Black citizens off juries in cases against Black defendants \u2014 and a 1965 precedent, Swain v. Alabama, makes such discrimination nearly impossible to prove. Batson, convicted by the all-white jury that resulted, asks the Court to confront what everyone in the courthouse can plainly see. Only the old precedent stands in the way.", "intro": "Picking a jury in Louisville, the prosecutor uses his peremptory strikes to remove every Black member of the panel \u2014 and an all-white jury convicts James Batson of burglary.", "decided": "April 30, 1986", "split": "7\u20132", "answer": "yes", "justices": [{"key": "burger", "name": "Warren Burger", "meta": "Nixon appointee (R)", "blurb": "Seventeen years into the center chair, as much administrator as judge \u2014 obsessed with judicial efficiency and courtroom decorum. Reliably conservative on crime and social questions, though colleagues grumble that his opinion assignments follow strategy more than principle.", "photo": "photos/burger.jpg", "chief": true}, {"key": "brennan", "name": "William Brennan", "meta": "Eisenhower appointee (R)", "blurb": "The aging captain of the Court's shrinking liberal wing, three decades in. He can still conjure a majority from thin air on a good day \u2014 but these days he is more often assigning dissents than opinions.", "photo": "photos/brennan.jpg"}, {"key": "white", "name": "Byron White", "meta": "Kennedy appointee (D)", "blurb": "JFK's last appointee has hardened into the Court's flintiest pragmatist \u2014 tough on crime, dismissive of rights he cannot find in the Constitution's text, still steady on race and equal protection.", "photo": "photos/white.jpg"}, {"key": "marshall", "name": "Thurgood Marshall", "meta": "Lyndon Johnson appointee (D)", "blurb": "The civil-rights giant in winter, increasingly isolated as the Court moves right. He and Brennan vote as a pair on the death penalty and much else, filing dissent after dissent for a future Court to find.", "photo": "photos/marshall.jpg"}, {"key": "blackmun", "name": "Harry Blackmun", "meta": "Nixon appointee (R)", "blurb": "The onetime 'Minnesota Twin' has completed a long migration: the shy Nixon appointee now votes more often with Brennan and Marshall than with the Chief he grew up beside \u2014 above all on privacy and equality.", "photo": "photos/blackmun.jpg"}, {"key": "powell", "name": "Lewis Powell", "meta": "Nixon appointee (R)", "blurb": "The Court's gentle fulcrum. The courtly Richmond lawyer decides the close ones \u2014 law clerks joke that the Constitution means whatever Lewis Powell thinks it means \u2014 balancing order against liberty with a counselor's caution.", "photo": "photos/powell.jpg"}, {"key": "rehnquist", "name": "William Rehnquist", "meta": "Nixon appointee (R)", "blurb": "The Court's anchor on the right, so fond of solo dissents that his clerks once gave him a Lone Ranger doll. Federalism, law enforcement, judicial restraint: his positions never wobble \u2014 and the Court, increasingly, comes to him.", "photo": "photos/rehnquist.jpg"}, {"key": "stevens", "name": "John Paul Stevens", "meta": "Ford appointee (R)", "blurb": "The bow-tied Chicagoan defies sorting \u2014 a Ford Republican drifting toward the Court's left flank, case by idiosyncratic case. He writes more separate opinions than anyone, trusting his own reading of the law over any bloc's.", "photo": "photos/stevens.jpg"}, {"key": "oconnor", "name": "Sandra Day O'Connor", "meta": "Reagan appointee (R)", "blurb": "The first woman on the Court, a former Arizona legislative leader who judges like a lawmaker \u2014 narrow rulings, workable compromises, close attention to the facts. Reliably conservative on crime; harder to predict everywhere else.", "photo": "photos/oconnor.jpg"}], "votes": {"burger": "no", "brennan": "yes", "white": "yes", "marshall": "yes", "blackmun": "yes", "powell": "yes", "rehnquist": "no", "stevens": "yes", "oconnor": "yes"}}, {"id": "kelo-v-new-london", "era": "The Rehnquist Court \u00b7 October Term 2004", "caseTitle": "Kelo v. City of New London", "question": "May a city take homes by eminent domain and hand the land to a private developer?", "desc": "New London, its Navy base closed and its unemployment double the state's, approved a plan for offices, upscale housing, and a hotel beside Pfizer's new headquarters \u2014 and condemned the Fort Trumbull homes in the way. Kelo, a nurse, and her neighbors, including a woman born in her house in 1918, refuse to sell. The Fifth Amendment permits takings only for 'public use.' The city says jobs and taxes are use enough; the homeowners say that reading lets any government trade anyone's home to a richer owner.", "intro": "Susette Kelo's little pink house overlooks the Thames River in New London, Connecticut \u2014 squarely inside ninety acres the struggling city has promised to a private redevelopment plan anchored by a gleaming new Pfizer research campus.", "decided": "June 23, 2005", "split": "5\u20134", "answer": "yes", "justices": [{"key": "rehnquist", "name": "William Rehnquist", "meta": "Nixon appointee (R)", "blurb": "Chief Justice for nearly two decades, a genial and ruthlessly efficient administrator with a lifelong project: reviving states' rights and reining in Washington. He has spent his whole career waiting for the votes he now has.", "photo": "photos/rehnquist.jpg", "chief": true}, {"key": "stevens", "name": "John Paul Stevens", "meta": "Ford appointee (R)", "blurb": "The senior associate justice, a bow-tied Ford appointee from Chicago who now marshals the Court's liberal wing. Fiercely independent in method, he assigns the dissents whenever the Chief is on the other side.", "photo": "photos/stevens.jpg"}, {"key": "oconnor", "name": "Sandra Day O'Connor", "meta": "Reagan appointee (R)", "blurb": "A former Arizona legislator and the Court's pivotal vote \u2014 by common consent the most powerful woman in America. She distrusts absolutes and decides case by case; where she lands is usually where the law lands.", "photo": "photos/oconnor.jpg"}, {"key": "scalia", "name": "Antonin Scalia", "meta": "Reagan appointee (R)", "blurb": "The Court's combative originalist, its funniest questioner and its fiercest dissenter. He wants clear rules drawn from text and history, and treats his colleagues' balancing tests as legislation in robes.", "photo": "photos/scalia.jpg"}, {"key": "kennedy", "name": "Anthony Kennedy", "meta": "Reagan appointee (R)", "blurb": "A courtly Sacramento Republican with a taste for sweeping language about liberty and dignity. Conservative by default but persuadable at the margins \u2014 one of the two votes every advocate in the courtroom is chasing.", "photo": "photos/kennedy.jpg"}, {"key": "souter", "name": "David Souter", "meta": "George H. W. Bush appointee (R)", "blurb": "The first President Bush's 'stealth nominee,' a frugal New Hampshire bachelor who confounded his sponsors by settling into the moderate-liberal wing. A common-law traditionalist, devoted to precedent and wary of bold constitutional lurches.", "photo": "photos/souter.jpg"}, {"key": "thomas", "name": "Clarence Thomas", "meta": "George H. W. Bush appointee (R)", "blurb": "The Court's most uncompromising originalist, silent at argument and fearless in print. He would rather overrule a wrong precedent than trim it, and he stakes out positions no other justice will yet join.", "photo": "photos/thomas.jpg"}, {"key": "ginsburg", "name": "Ruth Bader Ginsburg", "meta": "Clinton appointee (D)", "blurb": "The ACLU litigator who dismantled sex-discrimination law brick by brick, now a precise, soft-spoken justice. A minimalist by temperament and a reliable liberal vote on questions of equal citizenship.", "photo": "photos/ginsburg.jpg"}, {"key": "breyer", "name": "Stephen Breyer", "meta": "Clinton appointee (D)", "blurb": "The junior justice, a Harvard administrative-law professor who thinks in workable purposes rather than absolutes. Pragmatic, optimistic about government, and forever spinning elaborate hypotheticals from the bench.", "photo": "photos/breyer.jpg"}], "votes": {"rehnquist": "no", "stevens": "yes", "oconnor": "no", "scalia": "no", "kennedy": "yes", "souter": "yes", "thomas": "no", "ginsburg": "yes", "breyer": "yes"}}, {"id": "dobbs-v-jackson", "era": "The Roberts Court \u00b7 October Term 2021", "caseTitle": "Dobbs v. Jackson Women's Health", "question": "May a state ban most abortions after fifteen weeks of pregnancy, well before fetal viability?", "desc": "Jackson Women's Health, the last abortion clinic in Mississippi, challenges the state's Gestational Age Act: almost no abortions after fifteen weeks, two months short of the viability line that Roe and Casey made the constitutional rule for half a century. Mississippi asks the Court not merely to uphold the law but to overrule Roe outright. Between argument and decision, a draft opinion leaks to the press \u2014 an unprecedented breach that puts security fencing around the building.", "intro": "Mississippi bans most abortions after fifteen weeks \u2014 a law written to defy Roe v. Wade and force exactly this case. A leaked draft opinion has already set the country on fire. Now comes the decision itself.", "decided": "June 24, 2022", "split": "6\u20133", "answer": "yes", "justices": [{"key": "roberts", "name": "John Roberts", "meta": "George W. Bush appointee (R)", "blurb": "No longer the Court's median vote \u2014 a six-justice conservative majority can now rule without him. He still preaches minimalism and frets over the institution's standing, hunting for narrower paths that his colleagues increasingly decline to take.", "photo": "photos/roberts.jpg", "chief": true}, {"key": "thomas_roberts", "name": "Clarence Thomas", "meta": "George H. W. Bush appointee (R)", "blurb": "The Court's most uncompromising originalist, fearless in print: he will discard decades of precedent without apology and stake out positions entirely alone, serenely confident the law will someday catch up to him.", "photo": "photos/thomas_roberts.jpg"}, {"key": "breyer_roberts", "name": "Stephen Breyer", "meta": "Clinton appointee (D)", "blurb": "The Court's pragmatist professor: a former Senate staffer and administrative-law scholar who judges by consequences, not grand theory. Endlessly optimistic about government, allergic to absolutes, and famous for winding hypotheticals that leave lawyers blinking.", "photo": "photos/breyer_roberts.jpg"}, {"key": "alito", "name": "Samuel Alito", "meta": "George W. Bush appointee (R)", "blurb": "A former federal prosecutor from New Jersey, methodical and unflashy, with the most reliably conservative instincts on the bench \u2014 above all where crime, religion, or the culture wars are concerned. In dissent, his pen turns acid.", "photo": "photos/alito.jpg"}, {"key": "sotomayor", "name": "Sonia Sotomayor", "meta": "Obama appointee (D)", "blurb": "From a Bronx housing project to Princeton to the federal trial bench: the first Latina justice never lets the Court forget how doctrine lands on actual people. A former prosecutor, relentless at argument, the liberal wing's most passionate voice.", "photo": "photos/sotomayor.jpg"}, {"key": "kagan", "name": "Elena Kagan", "meta": "Obama appointee (D)", "blurb": "The former Harvard Law dean and solicitor general, a coalition-builder who learned her politics in the Clinton White House. The liberal wing's tactician: she writes in plain, wry English and plays a patient long game of her own.", "photo": "photos/kagan.jpg"}, {"key": "gorsuch", "name": "Neil Gorsuch", "meta": "Trump appointee (R)", "blurb": "Scalia's successor and a true-believing textualist from Colorado: read the words, then follow them off a cliff if necessary. A westerner with a libertarian streak, he votes his method wherever it leads \u2014 to either camp's occasional dismay.", "photo": "photos/gorsuch.jpg"}, {"key": "kavanaugh", "name": "Brett Kavanaugh", "meta": "Trump appointee (R)", "blurb": "Confirmed after the most explosive hearings in memory, the former Bush White House aide works at looking reassuringly conventional: a conservative who prizes stability, writes separately to narrow things, and courts the middle whenever there is one.", "photo": "photos/kavanaugh.jpg"}, {"key": "barrett", "name": "Amy Coney Barrett", "meta": "Trump appointee (R)", "blurb": "Scalia's former clerk and a Notre Dame law professor, elevated to the bench days before a presidential election. An academic originalist \u2014 careful, methodical, unshowy \u2014 still drawing her own map of where method and caution part ways.", "photo": "photos/barrett.jpg"}], "votes": {"roberts": "yes", "thomas_roberts": "yes", "breyer_roberts": "no", "alito": "yes", "sotomayor": "no", "kagan": "no", "gorsuch": "yes", "kavanaugh": "yes", "barrett": "yes"}}, {"id": "duncan-v-louisiana", "era": "The Warren Court \u00b7 October Term 1967", "caseTitle": "Duncan v. Louisiana", "question": "Must a state provide a jury trial to a defendant charged with a serious crime?", "desc": "Duncan got sixty days and a $150 fine from a judge sitting alone, in a parish ruled by segregationist boss Leander Perez, where the schools had just been ordered to integrate and the charge, his lawyers say, was retaliation. The Sixth Amendment guarantees a jury in federal court; whether the Fourteenth imposes the same rule on the states has been argued since 1884. Louisiana calls the offense petty. The Court has been applying the Bill of Rights to the states one clause at a time; the jury is next.", "intro": "Gary Duncan, a 19-year-old Black man in Plaquemines Parish, touched a white boy's arm while breaking up a roadside argument. Charged with simple battery, he asked for a jury. Louisiana tries crimes carrying up to two years without one.", "decided": "May 20, 1968", "split": "7\u20132", "answer": "yes", "justices": [{"key": "warren", "name": "Earl Warren", "meta": "Eisenhower appointee (R)", "blurb": "The former California governor, now the most consequential Chief Justice in a century. He asks lawyers one question \u2014 'But is it fair?' \u2014 and works the conference like the politician he never stopped being.", "photo": "photos/warren.jpg", "chief": true}, {"key": "black", "name": "Hugo Black", "meta": "Franklin Roosevelt appointee (D)", "blurb": "An Alabama New Dealer who carries the Constitution in his coat pocket and reads it literally. 'No law' means no law \u2014 but rights he cannot find in the text, he will not invent.", "photo": "photos/black.jpg"}, {"key": "douglas", "name": "William O. Douglas", "meta": "Franklin Roosevelt appointee (D)", "blurb": "A restless westerner and the Court's fastest pen \u2014 impatient with doctrine, indifferent to precedent, and instinctively on the side of the lone individual against the government in nearly any form it takes.", "photo": "photos/douglas.jpg"}, {"key": "harlan", "name": "John Marshall Harlan", "meta": "Eisenhower appointee (R)", "blurb": "The Wall Street patrician and grandson of a great dissenter \u2014 the Court's conservative conscience. He believes in ordered liberty and lawyerly process, and objects, elegantly, when the majority moves too far, too fast.", "photo": "photos/harlan.jpg"}, {"key": "brennan", "name": "William Brennan", "meta": "Eisenhower appointee (R)", "blurb": "The Court's Irish charmer and master coalition-builder, an Eisenhower appointee who turned out to be its most effective liberal. His first rule of the shop: with five votes, you can do anything.", "photo": "photos/brennan.jpg"}, {"key": "stewart", "name": "Potter Stewart", "meta": "Eisenhower appointee (R)", "blurb": "A moderate Ohio Republican who resists both blocs' grand theories. He decides cases one at a time, asks what the Constitution actually commands, and lands \u2014 unpredictably \u2014 somewhere in the middle.", "photo": "photos/stewart.jpg"}, {"key": "white", "name": "Byron White", "meta": "Kennedy appointee (D)", "blurb": "'Whizzer' White, the All-American halfback turned Kennedy's deputy attorney general \u2014 tough-minded, unsentimental, and skeptical of newly minted rights, especially the kind that make police work harder.", "photo": "photos/white.jpg"}, {"key": "fortas", "name": "Abe Fortas", "meta": "Lyndon Johnson appointee (D)", "blurb": "LBJ's confidant and Washington's premier lawyer, still quietly advising the President from the bench. As an advocate he won poor defendants their counsel; as a justice he champions the underdog \u2014 children included.", "photo": "photos/fortas.jpg"}, {"key": "marshall", "name": "Thurgood Marshall", "meta": "Lyndon Johnson appointee (D)", "blurb": "The architect of the NAACP's litigation war on Jim Crow and the first Black justice \u2014 a storyteller who has seen the criminal law from the defendant's side of the table and never forgets it.", "photo": "photos/marshall.jpg"}], "votes": {"warren": "yes", "black": "yes", "douglas": "yes", "harlan": "no", "brennan": "yes", "stewart": "no", "white": "yes", "fortas": "yes", "marshall": "yes"}}, {"id": "kyllo-v-united-states", "era": "The Rehnquist Court \u00b7 October Term 2000", "caseTitle": "Kyllo v. United States", "question": "Is scanning a home with a thermal imager from the street a 'search' that requires a warrant?", "desc": "The Agema Thermovision 210 detects infrared radiation; a few minutes' scan from a public street showed Kyllo's garage and one wall unusually warm, consistent with halide grow lamps. With utility bills and a tip, that supported a warrant; agents found more than a hundred plants. Kyllo argues that reading the heat of a home's walls is a search of the home. The government answers that it merely observed what leaked into the open air, as anyone with a camera might. The Fourth Amendment meets a device that sees through walls.", "intro": "Federal agents suspecting Danny Kyllo of growing marijuana park across from his Oregon triplex and aim a thermal imager at it. The scan shows the garage roof glowing hot. They never set foot inside \u2014 and never asked a judge.", "decided": "June 11, 2001", "split": "5\u20134", "answer": "yes", "justices": [{"key": "rehnquist", "name": "William Rehnquist", "meta": "Nixon appointee (R)", "blurb": "Chief Justice for nearly two decades, a genial and ruthlessly efficient administrator with a lifelong project: reviving states' rights and reining in Washington. He has spent his whole career waiting for the votes he now has.", "photo": "photos/rehnquist.jpg", "chief": true}, {"key": "stevens", "name": "John Paul Stevens", "meta": "Ford appointee (R)", "blurb": "The senior associate justice, a bow-tied Ford appointee from Chicago who now marshals the Court's liberal wing. Fiercely independent in method, he assigns the dissents whenever the Chief is on the other side.", "photo": "photos/stevens.jpg"}, {"key": "oconnor", "name": "Sandra Day O'Connor", "meta": "Reagan appointee (R)", "blurb": "A former Arizona legislator and the Court's pivotal vote \u2014 by common consent the most powerful woman in America. She distrusts absolutes and decides case by case; where she lands is usually where the law lands.", "photo": "photos/oconnor.jpg"}, {"key": "scalia", "name": "Antonin Scalia", "meta": "Reagan appointee (R)", "blurb": "The Court's combative originalist, its funniest questioner and its fiercest dissenter. He wants clear rules drawn from text and history, and treats his colleagues' balancing tests as legislation in robes.", "photo": "photos/scalia.jpg"}, {"key": "kennedy", "name": "Anthony Kennedy", "meta": "Reagan appointee (R)", "blurb": "A courtly Sacramento Republican with a taste for sweeping language about liberty and dignity. Conservative by default but persuadable at the margins \u2014 one of the two votes every advocate in the courtroom is chasing.", "photo": "photos/kennedy.jpg"}, {"key": "souter", "name": "David Souter", "meta": "George H. W. Bush appointee (R)", "blurb": "The first President Bush's 'stealth nominee,' a frugal New Hampshire bachelor who confounded his sponsors by settling into the moderate-liberal wing. A common-law traditionalist, devoted to precedent and wary of bold constitutional lurches.", "photo": "photos/souter.jpg"}, {"key": "thomas", "name": "Clarence Thomas", "meta": "George H. W. Bush appointee (R)", "blurb": "The Court's most uncompromising originalist, silent at argument and fearless in print. He would rather overrule a wrong precedent than trim it, and he stakes out positions no other justice will yet join.", "photo": "photos/thomas.jpg"}, {"key": "ginsburg", "name": "Ruth Bader Ginsburg", "meta": "Clinton appointee (D)", "blurb": "The ACLU litigator who dismantled sex-discrimination law brick by brick, now a precise, soft-spoken justice. A minimalist by temperament and a reliable liberal vote on questions of equal citizenship.", "photo": "photos/ginsburg.jpg"}, {"key": "breyer", "name": "Stephen Breyer", "meta": "Clinton appointee (D)", "blurb": "The junior justice, a Harvard administrative-law professor who thinks in workable purposes rather than absolutes. Pragmatic, optimistic about government, and forever spinning elaborate hypotheticals from the bench.", "photo": "photos/breyer.jpg"}], "votes": {"rehnquist": "no", "stevens": "no", "oconnor": "no", "scalia": "yes", "kennedy": "no", "souter": "yes", "thomas": "yes", "ginsburg": "yes", "breyer": "yes"}}, {"id": "cooper-v-aaron", "era": "The Warren Court \u00b7 Special Term, August 1958", "caseTitle": "Cooper v. Aaron", "question": "May a school board postpone court-ordered desegregation because of the violent resistance it has met?", "desc": "Governor Orval Faubus called out the Arkansas National Guard to keep the Little Rock Nine out of Central High; President Eisenhower sent paratroopers to get them in. The year was ugly \u2014 mobs, threats, students harassed in the halls. Now the board says chaos makes integration impossible for now, and a federal judge has agreed. Faubus and the legislature insist Brown binds only the parties to it, not Arkansas. Thurgood Marshall answers that a right which yields to a mob is no right at all.", "intro": "Little Rock, one year after the 101st Airborne escorted nine Black students into Central High. The school board asks for a two-and-a-half-year pause, and the justices return from summer recess to hear it before school opens.", "decided": "September 12, 1958", "split": "9\u20130", "answer": "no", "justices": [{"key": "warren", "name": "Earl Warren", "meta": "Eisenhower appointee (R)", "blurb": "The former California governor, now the most consequential Chief Justice in a century. He asks lawyers one question \u2014 'But is it fair?' \u2014 and works the conference like the politician he never stopped being.", "photo": "photos/warren.jpg", "chief": true}, {"key": "black", "name": "Hugo Black", "meta": "Franklin Roosevelt appointee (D)", "blurb": "An Alabama New Dealer who carries the Constitution in his coat pocket and reads it literally. 'No law' means no law \u2014 but rights he cannot find in the text, he will not invent.", "photo": "photos/black.jpg"}, {"key": "frankfurter", "name": "Felix Frankfurter", "meta": "Franklin Roosevelt appointee (D)", "blurb": "The former Harvard professor and apostle of judicial restraint: courts, he preaches, must defer to legislatures even when the results offend. His seminars continue at conference, whether his colleagues want them or not.", "photo": "photos/frankfurter.jpg"}, {"key": "douglas", "name": "William O. Douglas", "meta": "Franklin Roosevelt appointee (D)", "blurb": "A restless westerner and the Court's fastest pen \u2014 impatient with doctrine, indifferent to precedent, and instinctively on the side of the lone individual against the government in nearly any form it takes.", "photo": "photos/douglas.jpg"}, {"key": "burton", "name": "Harold Burton", "meta": "Truman appointee (D)", "blurb": "A former Republican senator from Ohio appointed by his old colleague Harry Truman \u2014 a diligent, modest workhorse who reads every record and rarely makes headlines. Colleagues call him the fairest-minded man on the bench.", "photo": "photos/burton.jpg"}, {"key": "clark", "name": "Tom C. Clark", "meta": "Truman appointee (D)", "blurb": "Truman's Attorney General in a trademark bow tie \u2014 the Court's law-and-order Texan. He backs the police and the prosecutor by instinct, but he ran federal law enforcement himself and knows its temptations from the inside.", "photo": "photos/clark.jpg"}, {"key": "harlan", "name": "John Marshall Harlan", "meta": "Eisenhower appointee (R)", "blurb": "The Wall Street patrician and grandson of a great dissenter \u2014 the Court's conservative conscience. He believes in ordered liberty and lawyerly process, and objects, elegantly, when the majority moves too far, too fast.", "photo": "photos/harlan.jpg"}, {"key": "brennan", "name": "William Brennan", "meta": "Eisenhower appointee (R)", "blurb": "The Court's Irish charmer and master coalition-builder, an Eisenhower appointee who turned out to be its most effective liberal. His first rule of the shop: with five votes, you can do anything.", "photo": "photos/brennan.jpg"}, {"key": "whittaker", "name": "Charles Whittaker", "meta": "Eisenhower appointee (R)", "blurb": "A Missouri railroad lawyer who rose from farm poverty to the bench \u2014 cautious, conservative, and visibly agonized by close cases. He drafts opinions for both sides before choosing, and the choosing costs him sleep.", "photo": "photos/whittaker.jpg"}], "votes": {"warren": "no", "black": "no", "frankfurter": "no", "douglas": "no", "burton": "no", "clark": "no", "harlan": "no", "brennan": "no", "whittaker": "no"}}, {"id": "goss-v-lopez", "era": "The Burger Court \u00b7 October Term 1974", "caseTitle": "Goss v. Lopez", "question": "Must a public school give a student notice and a chance to tell his side before suspending him?", "desc": "Dwight Lopez says he was a bystander when a lunchroom disturbance broke out at Central High; he was sent home for ten days and learned the reason, if at all, by letter. Ohio law lets principals suspend without any hearing. The students argue that a free public education is a right the state has granted and cannot snatch away without due process; the board replies that principals are not judges and hallways are not courtrooms. At stake is whether the Fourteenth Amendment follows a teenager into the principal's office.", "intro": "Columbus, Ohio, in a winter of racial unrest. Seventy-five students are suspended for ten days each in a single sweep \u2014 many without being told what they were accused of. Nine of them sue.", "decided": "January 22, 1975", "split": "5\u20134", "answer": "yes", "justices": [{"key": "burger", "name": "Warren Burger", "meta": "Nixon appointee (R)", "blurb": "Nixon's chief justice, installed to steady a Court he believes ran wild under Earl Warren. A stickler for order and the dignity of institutions, he is more cautious conservative than crusader \u2014 and ever mindful of the Court's public standing.", "photo": "photos/burger.jpg", "chief": true}, {"key": "douglas", "name": "William O. Douglas", "meta": "Franklin Roosevelt appointee (D)", "blurb": "A New Deal wunderkind grown into the Court's absolutist loner \u2014 three decades on the bench, four wives, a shelf of his own books. He votes for the individual against the government almost reflexively, and writes opinions at breakneck speed.", "photo": "photos/douglas.jpg"}, {"key": "brennan", "name": "William Brennan", "meta": "Eisenhower appointee (R)", "blurb": "The Warren Court's master coalition-builder, an Eisenhower appointee turned architect of its liberal revolution. His first rule \u2014 with five votes you can do anything \u2014 still guides him as the bench tilts rightward around him.", "photo": "photos/brennan.jpg"}, {"key": "stewart", "name": "Potter Stewart", "meta": "Eisenhower appointee (R)", "blurb": "A pragmatic Ohio Republican wary of grand theory, he decides cases narrowly and one at a time. Neither wing can count on him: he distrusts government overreach and judicial adventure in roughly equal measure.", "photo": "photos/stewart.jpg"}, {"key": "white", "name": "Byron White", "meta": "Kennedy appointee (D)", "blurb": "The Kennedys' deputy attorney general, an All-America halfback turned no-nonsense pragmatist. Tough on crime and skeptical of newly minted rights, yet often found with the liberals on race and civil rights.", "photo": "photos/white.jpg"}, {"key": "marshall", "name": "Thurgood Marshall", "meta": "Lyndon Johnson appointee (D)", "blurb": "The architect of Brown v. Board and the Court's first Black justice. He judges from lived experience \u2014 Jim Crow courtrooms, clients facing the electric chair \u2014 and defends the poor and powerless with unembarrassed consistency.", "photo": "photos/marshall.jpg"}, {"key": "blackmun", "name": "Harry Blackmun", "meta": "Nixon appointee (R)", "blurb": "The junior justice, a shy Minnesota Republican and longtime counsel to the Mayo Clinic. Washington calls him and his boyhood friend the Chief the 'Minnesota Twins' \u2014 so far he votes Burger's way more often than not.", "photo": "photos/blackmun.jpg"}, {"key": "powell", "name": "Lewis Powell", "meta": "Nixon appointee (R)", "blurb": "A courtly Richmond corporate lawyer and former ABA president, newly arrived on the bench. The establishment's ideal judge: moderate, balancing, allergic to extremes \u2014 he weighs each case like a client matter and lands, usually, near the center.", "photo": "photos/powell.jpg"}, {"key": "rehnquist", "name": "William Rehnquist", "meta": "Nixon appointee (R)", "blurb": "The junior justice and its boldest conservative \u2014 a 47-year-old Nixon Justice Department lawyer with a brilliant pen and no fear of standing alone. He doubts much of what the Warren Court built.", "photo": "photos/rehnquist.jpg"}], "votes": {"burger": "no", "douglas": "yes", "brennan": "yes", "stewart": "yes", "white": "yes", "marshall": "yes", "blackmun": "no", "powell": "no", "rehnquist": "no"}}, {"id": "powell-v-mccormack", "era": "The Warren Court \u00b7 October Term 1968", "caseTitle": "Powell v. McCormack", "question": "May the House of Representatives refuse to seat a duly elected member who meets the Constitution's age, citizenship and residency requirements?", "desc": "A House committee found that Powell had misused travel funds, kept his wife on the payroll in Puerto Rico, and defied New York courts in a defamation case. Rather than seat and then expel him, which takes two-thirds, the House excluded him by majority vote. Powell sued Speaker John McCormack; Harlem re-elected him twice, and the new Congress has seated him with a fine. The House says each chamber judges its own members and courts cannot second-guess it. Powell says the Constitution lists three qualifications, and he meets them all.", "intro": "Adam Clayton Powell Jr., Harlem's congressman for 22 years and chairman of the Education and Labor Committee, was re-elected in 1966 by a landslide. In March 1967 the House voted 307 to 116 not to let him in.", "decided": "June 16, 1969", "split": "7\u20131", "answer": "no", "justices": [{"key": "warren", "name": "Earl Warren", "meta": "Eisenhower appointee (R)", "blurb": "The former California governor, now the most consequential Chief Justice in a century. He asks lawyers one question \u2014 'But is it fair?' \u2014 and works the conference like the politician he never stopped being.", "photo": "photos/warren.jpg", "chief": true}, {"key": "black", "name": "Hugo Black", "meta": "Franklin Roosevelt appointee (D)", "blurb": "An Alabama New Dealer who carries the Constitution in his coat pocket and reads it literally. 'No law' means no law \u2014 but rights he cannot find in the text, he will not invent.", "photo": "photos/black.jpg"}, {"key": "douglas", "name": "William O. Douglas", "meta": "Franklin Roosevelt appointee (D)", "blurb": "A restless westerner and the Court's fastest pen \u2014 impatient with doctrine, indifferent to precedent, and instinctively on the side of the lone individual against the government in nearly any form it takes.", "photo": "photos/douglas.jpg"}, {"key": "harlan", "name": "John Marshall Harlan", "meta": "Eisenhower appointee (R)", "blurb": "The Wall Street patrician and grandson of a great dissenter \u2014 the Court's conservative conscience. He believes in ordered liberty and lawyerly process, and objects, elegantly, when the majority moves too far, too fast.", "photo": "photos/harlan.jpg"}, {"key": "brennan", "name": "William Brennan", "meta": "Eisenhower appointee (R)", "blurb": "The Court's Irish charmer and master coalition-builder, an Eisenhower appointee who turned out to be its most effective liberal. His first rule of the shop: with five votes, you can do anything.", "photo": "photos/brennan.jpg"}, {"key": "stewart", "name": "Potter Stewart", "meta": "Eisenhower appointee (R)", "blurb": "A moderate Ohio Republican who resists both blocs' grand theories. He decides cases one at a time, asks what the Constitution actually commands, and lands \u2014 unpredictably \u2014 somewhere in the middle.", "photo": "photos/stewart.jpg"}, {"key": "white", "name": "Byron White", "meta": "Kennedy appointee (D)", "blurb": "'Whizzer' White, the All-American halfback turned Kennedy's deputy attorney general \u2014 tough-minded, unsentimental, and skeptical of newly minted rights, especially the kind that make police work harder.", "photo": "photos/white.jpg"}, {"key": "marshall", "name": "Thurgood Marshall", "meta": "Lyndon Johnson appointee (D)", "blurb": "The architect of the NAACP's litigation war on Jim Crow and the first Black justice \u2014 a storyteller who has seen the criminal law from the defendant's side of the table and never forgets it.", "photo": "photos/marshall.jpg"}], "votes": {"warren": "no", "black": "no", "douglas": "no", "harlan": "no", "brennan": "no", "stewart": "yes", "white": "no", "marshall": "no"}}, {"id": "schmerber-v-california", "era": "The Warren Court \u00b7 October Term 1965", "caseTitle": "Schmerber v. California", "question": "May police have a doctor draw blood from a drunk-driving suspect over his objection and use the result against him?", "desc": "The blood sample convicted Schmerber of driving under the influence. His lawyers say the needle violated nearly everything: due process, the privilege against self-incrimination, the right to counsel, and the ban on unreasonable searches \u2014 a seizure not of papers but of the body itself. California answers that alcohol in the blood vanishes by the hour, that the procedure was routine and painless, and that the Fifth Amendment protects what a man says, not what his veins contain. The Court last faced the question in 1957.", "intro": "Armando Schmerber crashed his car in Los Angeles and was taken to the hospital smelling of liquor. On a police officer's orders, and over Schmerber's refusal on his lawyer's advice, a physician drew his blood. It tested drunk.", "decided": "June 20, 1966", "split": "5\u20134", "answer": "yes", "justices": [{"key": "warren", "name": "Earl Warren", "meta": "Eisenhower appointee (R)", "blurb": "The former California governor, now the most consequential Chief Justice in a century. He asks lawyers one question \u2014 'But is it fair?' \u2014 and works the conference like the politician he never stopped being.", "photo": "photos/warren.jpg", "chief": true}, {"key": "black", "name": "Hugo Black", "meta": "Franklin Roosevelt appointee (D)", "blurb": "An Alabama New Dealer who carries the Constitution in his coat pocket and reads it literally. 'No law' means no law \u2014 but rights he cannot find in the text, he will not invent.", "photo": "photos/black.jpg"}, {"key": "douglas", "name": "William O. Douglas", "meta": "Franklin Roosevelt appointee (D)", "blurb": "A restless westerner and the Court's fastest pen \u2014 impatient with doctrine, indifferent to precedent, and instinctively on the side of the lone individual against the government in nearly any form it takes.", "photo": "photos/douglas.jpg"}, {"key": "clark", "name": "Tom C. Clark", "meta": "Truman appointee (D)", "blurb": "Truman's Attorney General in a trademark bow tie \u2014 the Court's law-and-order Texan. He backs the police and the prosecutor by instinct, but he ran federal law enforcement himself and knows its temptations from the inside.", "photo": "photos/clark.jpg"}, {"key": "harlan", "name": "John Marshall Harlan", "meta": "Eisenhower appointee (R)", "blurb": "The Wall Street patrician and grandson of a great dissenter \u2014 the Court's conservative conscience. He believes in ordered liberty and lawyerly process, and objects, elegantly, when the majority moves too far, too fast.", "photo": "photos/harlan.jpg"}, {"key": "brennan", "name": "William Brennan", "meta": "Eisenhower appointee (R)", "blurb": "The Court's Irish charmer and master coalition-builder, an Eisenhower appointee who turned out to be its most effective liberal. His first rule of the shop: with five votes, you can do anything.", "photo": "photos/brennan.jpg"}, {"key": "stewart", "name": "Potter Stewart", "meta": "Eisenhower appointee (R)", "blurb": "A moderate Ohio Republican who resists both blocs' grand theories. He decides cases one at a time, asks what the Constitution actually commands, and lands \u2014 unpredictably \u2014 somewhere in the middle.", "photo": "photos/stewart.jpg"}, {"key": "white", "name": "Byron White", "meta": "Kennedy appointee (D)", "blurb": "'Whizzer' White, the All-American halfback turned Kennedy's deputy attorney general \u2014 tough-minded, unsentimental, and skeptical of newly minted rights, especially the kind that make police work harder.", "photo": "photos/white.jpg"}, {"key": "fortas", "name": "Abe Fortas", "meta": "Lyndon Johnson appointee (D)", "blurb": "LBJ's confidant and Washington's premier lawyer, still quietly advising the President from the bench. As an advocate he won poor defendants their counsel; as a justice he champions the underdog \u2014 children included.", "photo": "photos/fortas.jpg"}], "votes": {"warren": "no", "black": "no", "douglas": "no", "clark": "yes", "harlan": "yes", "brennan": "yes", "stewart": "yes", "white": "yes", "fortas": "no"}}, {"id": "cohen-v-california", "era": "The Burger Court \u00b7 October Term 1970", "caseTitle": "Cohen v. California", "question": "May a state convict a man for wearing a jacket reading 'F--- the Draft' in a courthouse corridor?", "desc": "Paul Robert Cohen wore the jacket through a corridor full of women and children in April 1968; he took it off in the courtroom and was arrested anyway for 'offensive conduct' disturbing the peace. Nobody fought, nobody was threatened \u2014 the only offense was the word. The Chief Justice warns counsel it will not be necessary to say it aloud. California argues a state may police the vocabulary of public places; Cohen's lawyers answer that the Constitution protects the emotion of a message as well as its content.", "intro": "A nineteen-year-old walks through the Los Angeles County Courthouse in a jacket bearing three words about the draft \u2014 and spends thirty days in jail for it. Now the words reach the marble temple.", "decided": "June 7, 1971", "split": "5\u20134", "answer": "no", "justices": [{"key": "burger", "name": "Warren Burger", "meta": "Nixon appointee (R)", "blurb": "Nixon's chief justice, installed to steady a Court he believes ran wild under Earl Warren. A stickler for order and the dignity of institutions, he is more cautious conservative than crusader \u2014 and ever mindful of the Court's public standing.", "photo": "photos/burger.jpg", "chief": true}, {"key": "black", "name": "Hugo Black", "meta": "Franklin Roosevelt appointee (D)", "blurb": "At 85, the New Deal's last titan and the First Amendment's fiercest literalist \u2014 'no law abridging' means no law, period. Frail and near the end of 34 years on the bench, he still writes with the old fire.", "photo": "photos/black.jpg"}, {"key": "douglas", "name": "William O. Douglas", "meta": "Franklin Roosevelt appointee (D)", "blurb": "A New Deal wunderkind grown into the Court's absolutist loner \u2014 three decades on the bench, four wives, a shelf of his own books. He votes for the individual against the government almost reflexively, and writes opinions at breakneck speed.", "photo": "photos/douglas.jpg"}, {"key": "harlan", "name": "John Marshall Harlan", "meta": "Eisenhower appointee (R)", "blurb": "The Court's patrician conservative conscience, a lawyer's lawyer of precision and restraint. Nearly blind, he reads briefs held an inch from his eyes \u2014 and insists that judging is a matter of process and precedent, never passion.", "photo": "photos/harlan.jpg"}, {"key": "brennan", "name": "William Brennan", "meta": "Eisenhower appointee (R)", "blurb": "The Warren Court's master coalition-builder, an Eisenhower appointee turned architect of its liberal revolution. His first rule \u2014 with five votes you can do anything \u2014 still guides him as the bench tilts rightward around him.", "photo": "photos/brennan.jpg"}, {"key": "stewart", "name": "Potter Stewart", "meta": "Eisenhower appointee (R)", "blurb": "A pragmatic Ohio Republican wary of grand theory, he decides cases narrowly and one at a time. Neither wing can count on him: he distrusts government overreach and judicial adventure in roughly equal measure.", "photo": "photos/stewart.jpg"}, {"key": "white", "name": "Byron White", "meta": "Kennedy appointee (D)", "blurb": "The Kennedys' deputy attorney general, an All-America halfback turned no-nonsense pragmatist. Tough on crime and skeptical of newly minted rights, yet often found with the liberals on race and civil rights.", "photo": "photos/white.jpg"}, {"key": "marshall", "name": "Thurgood Marshall", "meta": "Lyndon Johnson appointee (D)", "blurb": "The architect of Brown v. Board and the Court's first Black justice. He judges from lived experience \u2014 Jim Crow courtrooms, clients facing the electric chair \u2014 and defends the poor and powerless with unembarrassed consistency.", "photo": "photos/marshall.jpg"}, {"key": "blackmun", "name": "Harry Blackmun", "meta": "Nixon appointee (R)", "blurb": "The junior justice, a shy Minnesota Republican and longtime counsel to the Mayo Clinic. Washington calls him and his boyhood friend the Chief the 'Minnesota Twins' \u2014 so far he votes Burger's way more often than not.", "photo": "photos/blackmun.jpg"}], "votes": {"burger": "yes", "black": "yes", "douglas": "no", "harlan": "no", "brennan": "no", "stewart": "no", "white": "yes", "marshall": "no", "blackmun": "yes"}}, {"id": "branzburg-v-hayes", "era": "The Burger Court \u00b7 October Term 1971", "caseTitle": "Branzburg v. Hayes", "question": "Does the First Amendment let a reporter refuse to tell a grand jury what he saw while reporting?", "desc": "Paul Branzburg of the Courier-Journal wrote about the drug trade from the inside; Earl Caldwell of the New York Times earned the trust of the Black Panthers; Paul Pappas, a New Bedford cameraman, spent a night in a Panther headquarters. Each has refused a grand jury's demand to testify, arguing that sources will dry up the moment reporters become investigators' eyes. Prosecutors answer that every citizen owes the grand jury his evidence. Nineteen states have shield laws; the Constitution has never been read to contain one.", "intro": "A Louisville reporter watches two young men cook hashish for a story, promises not to name them \u2014 and is subpoenaed. Three newsmen, three grand juries, one question: does the press get a privilege?", "decided": "June 29, 1972", "split": "5\u20134", "answer": "no", "justices": [{"key": "burger", "name": "Warren Burger", "meta": "Nixon appointee (R)", "blurb": "Nixon's chief justice, installed to steady a Court he believes ran wild under Earl Warren. A stickler for order and the dignity of institutions, he is more cautious conservative than crusader \u2014 and ever mindful of the Court's public standing.", "photo": "photos/burger.jpg", "chief": true}, {"key": "douglas", "name": "William O. Douglas", "meta": "Franklin Roosevelt appointee (D)", "blurb": "A New Deal wunderkind grown into the Court's absolutist loner \u2014 three decades on the bench, four wives, a shelf of his own books. He votes for the individual against the government almost reflexively, and writes opinions at breakneck speed.", "photo": "photos/douglas.jpg"}, {"key": "brennan", "name": "William Brennan", "meta": "Eisenhower appointee (R)", "blurb": "The Warren Court's master coalition-builder, an Eisenhower appointee turned architect of its liberal revolution. His first rule \u2014 with five votes you can do anything \u2014 still guides him as the bench tilts rightward around him.", "photo": "photos/brennan.jpg"}, {"key": "stewart", "name": "Potter Stewart", "meta": "Eisenhower appointee (R)", "blurb": "A pragmatic Ohio Republican wary of grand theory, he decides cases narrowly and one at a time. Neither wing can count on him: he distrusts government overreach and judicial adventure in roughly equal measure.", "photo": "photos/stewart.jpg"}, {"key": "white", "name": "Byron White", "meta": "Kennedy appointee (D)", "blurb": "The Kennedys' deputy attorney general, an All-America halfback turned no-nonsense pragmatist. Tough on crime and skeptical of newly minted rights, yet often found with the liberals on race and civil rights.", "photo": "photos/white.jpg"}, {"key": "marshall", "name": "Thurgood Marshall", "meta": "Lyndon Johnson appointee (D)", "blurb": "The architect of Brown v. Board and the Court's first Black justice. He judges from lived experience \u2014 Jim Crow courtrooms, clients facing the electric chair \u2014 and defends the poor and powerless with unembarrassed consistency.", "photo": "photos/marshall.jpg"}, {"key": "blackmun", "name": "Harry Blackmun", "meta": "Nixon appointee (R)", "blurb": "The junior justice, a shy Minnesota Republican and longtime counsel to the Mayo Clinic. Washington calls him and his boyhood friend the Chief the 'Minnesota Twins' \u2014 so far he votes Burger's way more often than not.", "photo": "photos/blackmun.jpg"}, {"key": "powell", "name": "Lewis Powell", "meta": "Nixon appointee (R)", "blurb": "A courtly Richmond corporate lawyer and former ABA president, newly arrived on the bench. The establishment's ideal judge: moderate, balancing, allergic to extremes \u2014 he weighs each case like a client matter and lands, usually, near the center.", "photo": "photos/powell.jpg"}, {"key": "rehnquist", "name": "William Rehnquist", "meta": "Nixon appointee (R)", "blurb": "The junior justice and its boldest conservative \u2014 a 47-year-old Nixon Justice Department lawyer with a brilliant pen and no fear of standing alone. He doubts much of what the Warren Court built.", "photo": "photos/rehnquist.jpg"}], "votes": {"burger": "no", "douglas": "yes", "brennan": "yes", "stewart": "yes", "white": "no", "marshall": "yes", "blackmun": "no", "powell": "no", "rehnquist": "no"}}, {"id": "lynch-v-donnelly", "era": "The Burger Court \u00b7 October Term 1983", "caseTitle": "Lynch v. Donnelly", "question": "May a city include a Nativity scene in its official Christmas display?", "desc": "The cr\u00e8che is city-owned, erected by city workers in a park beside the shopping district, surrounded by cut-out carolers, a talking wishing well and a banner reading SEASONS GREETINGS. Daniel Donnelly says a city that displays the infant Jesus endorses Christianity, and two lower courts agreed. Mayor Dennis Lynch calls the display a secular holiday tradition that happens to acknowledge its origin, and the Reagan administration backs him. Thirteen years after the Lemon test, the Justices must say whether the Establishment Clause reaches a plastic manger in a public square.", "intro": "Every December for forty years Pawtucket, Rhode Island, has set up Santa's house, a Christmas tree, reindeer and a manger scene downtown. A local resident and the ACLU ask the courts to take the manger away.", "decided": "March 5, 1984", "split": "5\u20134", "answer": "yes", "justices": [{"key": "burger", "name": "Warren Burger", "meta": "Nixon appointee (R)", "blurb": "Seventeen years into the center chair, as much administrator as judge \u2014 obsessed with judicial efficiency and courtroom decorum. Reliably conservative on crime and social questions, though colleagues grumble that his opinion assignments follow strategy more than principle.", "photo": "photos/burger.jpg", "chief": true}, {"key": "brennan", "name": "William Brennan", "meta": "Eisenhower appointee (R)", "blurb": "The aging captain of the Court's shrinking liberal wing, three decades in. He can still conjure a majority from thin air on a good day \u2014 but these days he is more often assigning dissents than opinions.", "photo": "photos/brennan.jpg"}, {"key": "white", "name": "Byron White", "meta": "Kennedy appointee (D)", "blurb": "JFK's last appointee has hardened into the Court's flintiest pragmatist \u2014 tough on crime, dismissive of rights he cannot find in the Constitution's text, still steady on race and equal protection.", "photo": "photos/white.jpg"}, {"key": "marshall", "name": "Thurgood Marshall", "meta": "Lyndon Johnson appointee (D)", "blurb": "The civil-rights giant in winter, increasingly isolated as the Court moves right. He and Brennan vote as a pair on the death penalty and much else, filing dissent after dissent for a future Court to find.", "photo": "photos/marshall.jpg"}, {"key": "blackmun", "name": "Harry Blackmun", "meta": "Nixon appointee (R)", "blurb": "The onetime 'Minnesota Twin' has completed a long migration: the shy Nixon appointee now votes more often with Brennan and Marshall than with the Chief he grew up beside \u2014 above all on privacy and equality.", "photo": "photos/blackmun.jpg"}, {"key": "powell", "name": "Lewis Powell", "meta": "Nixon appointee (R)", "blurb": "The Court's gentle fulcrum. The courtly Richmond lawyer decides the close ones \u2014 law clerks joke that the Constitution means whatever Lewis Powell thinks it means \u2014 balancing order against liberty with a counselor's caution.", "photo": "photos/powell.jpg"}, {"key": "rehnquist", "name": "William Rehnquist", "meta": "Nixon appointee (R)", "blurb": "The Court's anchor on the right, so fond of solo dissents that his clerks once gave him a Lone Ranger doll. Federalism, law enforcement, judicial restraint: his positions never wobble \u2014 and the Court, increasingly, comes to him.", "photo": "photos/rehnquist.jpg"}, {"key": "stevens", "name": "John Paul Stevens", "meta": "Ford appointee (R)", "blurb": "The bow-tied Chicagoan defies sorting \u2014 a Ford Republican drifting toward the Court's left flank, case by idiosyncratic case. He writes more separate opinions than anyone, trusting his own reading of the law over any bloc's.", "photo": "photos/stevens.jpg"}, {"key": "oconnor", "name": "Sandra Day O'Connor", "meta": "Reagan appointee (R)", "blurb": "The first woman on the Court, a former Arizona legislative leader who judges like a lawmaker \u2014 narrow rulings, workable compromises, close attention to the facts. Reliably conservative on crime; harder to predict everywhere else.", "photo": "photos/oconnor.jpg"}], "votes": {"burger": "yes", "brennan": "no", "white": "yes", "marshall": "no", "blackmun": "no", "powell": "yes", "rehnquist": "yes", "stevens": "no", "oconnor": "yes"}}, {"id": "trump-v-hawaii", "era": "The Roberts Court \u00b7 October Term 2017", "caseTitle": "Trump v. Hawaii", "question": "May the president bar entry to nationals of several mostly Muslim countries under his power to suspend immigration?", "desc": "Proclamation 9645 restricts entry from Iran, Libya, Somalia, Syria, Yemen, and North Korea, plus certain Venezuelan officials, after a worldwide review of vetting practices. Hawaii, joined by an imam whose Syrian mother-in-law cannot visit, argues it exceeds the President's immigration powers and \u2014 given candidate Trump's call for 'a total and complete shutdown of Muslims entering the United States' \u2014 violates the Establishment Clause. The government says the statute lets the President suspend entry of 'any class of aliens' he finds detrimental, and that courts may not second-guess national security.", "intro": "A week into his presidency, Donald Trump bars travelers from seven Muslim-majority countries, and chaos erupts at the airports. Two rewrites and eighteen months later, the third version of the travel ban reaches the Court.", "decided": "June 26, 2018", "split": "5\u20134", "answer": "yes", "justices": [{"key": "roberts", "name": "John Roberts", "meta": "George W. Bush appointee (R)", "blurb": "A dozen years in, the chief has become the Court's institutional conscience, insisting \u2014 especially in a polarized age \u2014 that it must not look like a political body. An incrementalist by temperament: he would rather decide little than decide loudly.", "photo": "photos/roberts.jpg", "chief": true}, {"key": "kennedy_roberts", "name": "Anthony Kennedy", "meta": "Reagan appointee (R)", "blurb": "The swing. A courtly Sacramento Republican who controls the outcome in nearly every close case \u2014 and knows it. Liberty and dignity are his lodestars, sweeping language his signature, suspense his permanent gift to Court-watchers.", "photo": "photos/kennedy_roberts.jpg"}, {"key": "thomas_roberts", "name": "Clarence Thomas", "meta": "George H. W. Bush appointee (R)", "blurb": "The Court's most uncompromising originalist, fearless in print: he will discard decades of precedent without apology and stake out positions entirely alone, serenely confident the law will someday catch up to him.", "photo": "photos/thomas_roberts.jpg"}, {"key": "ginsburg_roberts", "name": "Ruth Bader Ginsburg", "meta": "Clinton appointee (D)", "blurb": "The pioneering women's-rights litigator of the 1970s, now the liberal wing's most exacting technician. Small, quiet, and precise, she picks her battles carefully \u2014 and reads her fiercest dissents aloud from the bench when she loses one.", "photo": "photos/ginsburg_roberts.jpg"}, {"key": "breyer_roberts", "name": "Stephen Breyer", "meta": "Clinton appointee (D)", "blurb": "The Court's pragmatist professor: a former Senate staffer and administrative-law scholar who judges by consequences, not grand theory. Endlessly optimistic about government, allergic to absolutes, and famous for winding hypotheticals that leave lawyers blinking.", "photo": "photos/breyer_roberts.jpg"}, {"key": "alito", "name": "Samuel Alito", "meta": "George W. Bush appointee (R)", "blurb": "A former federal prosecutor from New Jersey, methodical and unflashy, with the most reliably conservative instincts on the bench \u2014 above all where crime, religion, or the culture wars are concerned. In dissent, his pen turns acid.", "photo": "photos/alito.jpg"}, {"key": "sotomayor", "name": "Sonia Sotomayor", "meta": "Obama appointee (D)", "blurb": "From a Bronx housing project to Princeton to the federal trial bench: the first Latina justice never lets the Court forget how doctrine lands on actual people. A former prosecutor, relentless at argument, the liberal wing's most passionate voice.", "photo": "photos/sotomayor.jpg"}, {"key": "kagan", "name": "Elena Kagan", "meta": "Obama appointee (D)", "blurb": "The former Harvard Law dean and solicitor general, a coalition-builder who learned her politics in the Clinton White House. The liberal wing's tactician: she writes in plain, wry English and plays a patient long game of her own.", "photo": "photos/kagan.jpg"}, {"key": "gorsuch", "name": "Neil Gorsuch", "meta": "Trump appointee (R)", "blurb": "Scalia's successor and a true-believing textualist from Colorado: read the words, then follow them off a cliff if necessary. A westerner with a libertarian streak, he votes his method wherever it leads \u2014 to either camp's occasional dismay.", "photo": "photos/gorsuch.jpg"}], "votes": {"roberts": "yes", "kennedy_roberts": "yes", "thomas_roberts": "yes", "ginsburg_roberts": "no", "breyer_roberts": "no", "alito": "yes", "sotomayor": "no", "kagan": "no", "gorsuch": "yes"}}, {"id": "lee-v-weisman", "era": "The Rehnquist Court \u00b7 October Term 1991", "caseTitle": "Lee v. Weisman", "question": "May a public school invite a clergyman to deliver a prayer at its graduation ceremony?", "desc": "Providence's public schools let principals invite clergy to open and close graduation, handing them a pamphlet on composing civic prayers. Rabbi Leslie Gutterman thanked God for 'the legacy of America, where diversity is celebrated.' Deborah Weisman, fourteen, attended; her father sued to stop the practice at her future high school. Since 1962 the Court has barred classroom prayer, and the Solicitor General now urges the justices to allow ceremonial religion wherever no one is coerced. The school says attendance is voluntary; the Weismans say no graduate really has a choice.", "intro": "At Nathan Bishop Middle School in Providence, a rabbi offers a short nonsectarian prayer at graduation. Daniel Weisman, whose daughter Deborah is in the eighth-grade class, asks the courts to forbid it. The Bush administration joins the school's side.", "decided": "June 24, 1992", "split": "5\u20134", "answer": "no", "justices": [{"key": "rehnquist88", "name": "William Rehnquist", "meta": "Nixon appointee (R)", "blurb": "Six years into the chief justiceship, a genial poker-playing states'-rights man who finally has the numbers: Brennan and Marshall are gone, replaced by two Bush appointees. He assigns the opinions and expects the long-promised conservative turn to arrive.", "photo": "photos/rehnquist88.jpg", "chief": true}, {"key": "white", "name": "Byron White", "meta": "Kennedy appointee (D)", "blurb": "Thirty years on the bench, the Court's gruff elder \u2014 a Kennedy appointee and former NFL halfback who defies every label: hard on criminal defendants, cool toward newly minted rights, steady on civil rights. Short opinions, no apologies.", "photo": "photos/white.jpg"}, {"key": "blackmun", "name": "Harry Blackmun", "meta": "Nixon appointee (R)", "blurb": "The author of Roe v. Wade, now 83 and the Court's most anguished liberal, writing with his heart on his sleeve. With Brennan and Marshall retired he leads the diminished left \u2014 and wonders aloud how long Roe can last.", "photo": "photos/blackmun.jpg"}, {"key": "stevens88", "name": "John Paul Stevens", "meta": "Ford appointee (R)", "blurb": "A bow-tied Ford appointee from Chicago, fiercely independent in method, who has become the senior voice of the Court's liberal side almost by default. He follows his own analysis wherever it leads and scatters solo opinions along the way.", "photo": "photos/stevens88.jpg"}, {"key": "oconnor88", "name": "Sandra Day O'Connor", "meta": "Reagan appointee (R)", "blurb": "A former Arizona legislator who judges the way she once governed: case by case, fact by fact, wary of sweeping rules. The vote both sides must win, and increasingly the one deciding where the line falls.", "photo": "photos/oconnor88.jpg"}, {"key": "scalia88", "name": "Antonin Scalia", "meta": "Reagan appointee (R)", "blurb": "Reagan's combative originalist, six terms in and the Court's sharpest pen. He wants clear rules drawn from text and history and treats his colleagues' balancing tests as legislation in robes \u2014 in dissent if he must.", "photo": "photos/scalia88.jpg"}, {"key": "kennedy88", "name": "Anthony Kennedy", "meta": "Reagan appointee (R)", "blurb": "A courtly Sacramento Republican confirmed unanimously after the Bork nomination collapsed. Expected to be a dependable conservative vote, but given to grand talk about liberty and the dignity of the individual \u2014 and lately harder to predict.", "photo": "photos/kennedy88.jpg"}, {"key": "souter", "name": "David Souter", "meta": "George H. W. Bush appointee (R)", "blurb": "The first President Bush's 'stealth nominee,' a frugal New Hampshire bachelor and common-law traditionalist who has barely begun to show his hand. Devoted to precedent, wary of grand theory, and watched closely by both camps.", "photo": "photos/souter.jpg"}, {"key": "thomas", "name": "Clarence Thomas", "meta": "George H. W. Bush appointee (R)", "blurb": "The newest justice, confirmed 52\u201348 after the Anita Hill hearings: a Georgia-born originalist who says little at argument and writes with uncompromising clarity. Expected to be a reliable conservative, and already showing an appetite for first principles.", "photo": "photos/thomas.jpg"}], "votes": {"rehnquist88": "yes", "white": "yes", "blackmun": "no", "stevens88": "no", "oconnor88": "no", "scalia88": "yes", "kennedy88": "no", "souter": "no", "thomas": "yes"}}, {"id": "jones-v-alfred-h-mayer", "era": "The Warren Court \u00b7 October Term 1967", "caseTitle": "Jones v. Alfred H. Mayer Co.", "question": "May Congress forbid a private developer from refusing to sell a home to a buyer because he is Black?", "desc": "The Civil Rights Act of 1866 gives all citizens the same right 'as is enjoyed by white citizens' to buy and sell property. For a century courts read it to reach only state action \u2014 Jim Crow statutes, not private bigotry. The Joneses argue the plain words cover any seller, and that the Thirteenth Amendment, which bans slavery and its badges, let Congress say so. The developer answers that choosing one's buyer was never a badge of slavery. Meanwhile Dr. King is murdered and Congress passes a Fair Housing Act.", "intro": "Joseph Lee Jones and his wife Barbara tried to buy a house in Paddock Woods, a new subdivision in St. Louis County. The developer would not sell to a Black man. Their lawyers reach for a law passed in 1866.", "decided": "June 17, 1968", "split": "7\u20132", "answer": "yes", "justices": [{"key": "warren", "name": "Earl Warren", "meta": "Eisenhower appointee (R)", "blurb": "The former California governor, now the most consequential Chief Justice in a century. He asks lawyers one question \u2014 'But is it fair?' \u2014 and works the conference like the politician he never stopped being.", "photo": "photos/warren.jpg", "chief": true}, {"key": "black", "name": "Hugo Black", "meta": "Franklin Roosevelt appointee (D)", "blurb": "An Alabama New Dealer who carries the Constitution in his coat pocket and reads it literally. 'No law' means no law \u2014 but rights he cannot find in the text, he will not invent.", "photo": "photos/black.jpg"}, {"key": "douglas", "name": "William O. Douglas", "meta": "Franklin Roosevelt appointee (D)", "blurb": "A restless westerner and the Court's fastest pen \u2014 impatient with doctrine, indifferent to precedent, and instinctively on the side of the lone individual against the government in nearly any form it takes.", "photo": "photos/douglas.jpg"}, {"key": "harlan", "name": "John Marshall Harlan", "meta": "Eisenhower appointee (R)", "blurb": "The Wall Street patrician and grandson of a great dissenter \u2014 the Court's conservative conscience. He believes in ordered liberty and lawyerly process, and objects, elegantly, when the majority moves too far, too fast.", "photo": "photos/harlan.jpg"}, {"key": "brennan", "name": "William Brennan", "meta": "Eisenhower appointee (R)", "blurb": "The Court's Irish charmer and master coalition-builder, an Eisenhower appointee who turned out to be its most effective liberal. His first rule of the shop: with five votes, you can do anything.", "photo": "photos/brennan.jpg"}, {"key": "stewart", "name": "Potter Stewart", "meta": "Eisenhower appointee (R)", "blurb": "A moderate Ohio Republican who resists both blocs' grand theories. He decides cases one at a time, asks what the Constitution actually commands, and lands \u2014 unpredictably \u2014 somewhere in the middle.", "photo": "photos/stewart.jpg"}, {"key": "white", "name": "Byron White", "meta": "Kennedy appointee (D)", "blurb": "'Whizzer' White, the All-American halfback turned Kennedy's deputy attorney general \u2014 tough-minded, unsentimental, and skeptical of newly minted rights, especially the kind that make police work harder.", "photo": "photos/white.jpg"}, {"key": "fortas", "name": "Abe Fortas", "meta": "Lyndon Johnson appointee (D)", "blurb": "LBJ's confidant and Washington's premier lawyer, still quietly advising the President from the bench. As an advocate he won poor defendants their counsel; as a justice he champions the underdog \u2014 children included.", "photo": "photos/fortas.jpg"}, {"key": "marshall", "name": "Thurgood Marshall", "meta": "Lyndon Johnson appointee (D)", "blurb": "The architect of the NAACP's litigation war on Jim Crow and the first Black justice \u2014 a storyteller who has seen the criminal law from the defendant's side of the table and never forgets it.", "photo": "photos/marshall.jpg"}], "votes": {"warren": "yes", "black": "yes", "douglas": "yes", "harlan": "no", "brennan": "yes", "stewart": "yes", "white": "no", "fortas": "yes", "marshall": "yes"}}, {"id": "engel-v-vitale", "era": "The Warren Court \u00b7 October Term 1961", "caseTitle": "Engel v. Vitale", "question": "May a public school open each day with a short, nondenominational prayer written by state officials?", "desc": "Steven Engel, a Jewish father, joined four other parents \u2014 Jewish, Unitarian, Ethical Culture, and one nonbeliever \u2014 to sue the school board headed by William Vitale. The Regents' prayer is voluntary and names no denomination, and New York's courts upheld it as harmless civic piety. The parents answer that a government which composes a prayer and leads children in it has established religion as surely as any state church. Religious groups across the country wait on the answer; a ruling either way will land in a thousand classrooms.", "intro": "Every morning in New Hyde Park, Long Island, schoolchildren recite twenty-two words composed by the New York Board of Regents: 'Almighty God, we acknowledge our dependence upon Thee...' Five parents say the state has no business writing prayers.", "decided": "June 25, 1962", "split": "6\u20131", "answer": "no", "justices": [{"key": "warren", "name": "Earl Warren", "meta": "Eisenhower appointee (R)", "blurb": "The former California governor, now the most consequential Chief Justice in a century. He asks lawyers one question \u2014 'But is it fair?' \u2014 and works the conference like the politician he never stopped being.", "photo": "photos/warren.jpg", "chief": true}, {"key": "black", "name": "Hugo Black", "meta": "Franklin Roosevelt appointee (D)", "blurb": "An Alabama New Dealer who carries the Constitution in his coat pocket and reads it literally. 'No law' means no law \u2014 but rights he cannot find in the text, he will not invent.", "photo": "photos/black.jpg"}, {"key": "douglas", "name": "William O. Douglas", "meta": "Franklin Roosevelt appointee (D)", "blurb": "A restless westerner and the Court's fastest pen \u2014 impatient with doctrine, indifferent to precedent, and instinctively on the side of the lone individual against the government in nearly any form it takes.", "photo": "photos/douglas.jpg"}, {"key": "clark", "name": "Tom C. Clark", "meta": "Truman appointee (D)", "blurb": "Truman's Attorney General in a trademark bow tie \u2014 the Court's law-and-order Texan. He backs the police and the prosecutor by instinct, but he ran federal law enforcement himself and knows its temptations from the inside.", "photo": "photos/clark.jpg"}, {"key": "harlan", "name": "John Marshall Harlan", "meta": "Eisenhower appointee (R)", "blurb": "The Wall Street patrician and grandson of a great dissenter \u2014 the Court's conservative conscience. He believes in ordered liberty and lawyerly process, and objects, elegantly, when the majority moves too far, too fast.", "photo": "photos/harlan.jpg"}, {"key": "brennan", "name": "William Brennan", "meta": "Eisenhower appointee (R)", "blurb": "The Court's Irish charmer and master coalition-builder, an Eisenhower appointee who turned out to be its most effective liberal. His first rule of the shop: with five votes, you can do anything.", "photo": "photos/brennan.jpg"}, {"key": "stewart", "name": "Potter Stewart", "meta": "Eisenhower appointee (R)", "blurb": "A moderate Ohio Republican who resists both blocs' grand theories. He decides cases one at a time, asks what the Constitution actually commands, and lands \u2014 unpredictably \u2014 somewhere in the middle.", "photo": "photos/stewart.jpg"}], "votes": {"warren": "no", "black": "no", "douglas": "no", "clark": "no", "harlan": "no", "brennan": "no", "stewart": "yes"}}, {"id": "grutter-v-bollinger", "era": "The Rehnquist Court \u00b7 October Term 2002", "caseTitle": "Grutter v. Bollinger", "question": "May a public university consider an applicant's race as one factor in admissions to achieve a diverse student body?", "desc": "Michigan's law school, among the nation's most selective, reads every file whole: grades and test scores, but also essays, recommendations, and race \u2014 seeking enough Black, Hispanic, and Native American students that none feels a token. Grutter, rejected in 1997, says the policy is a quota in disguise. Retired generals, Fortune 500 companies, and the Bush administration have filed briefs; a companion case against the undergraduate college's points system arrives the same day. Justice Powell's lone opinion in Bakke allowed race as a 'plus'; no majority has ever said so.", "intro": "Barbara Grutter, a white Michigan resident with a 3.8 average, is turned down by the University of Michigan Law School, which admits to weighing race in pursuit of a 'critical mass' of minority students. A quarter-century after Bakke, affirmative action is back.", "decided": "June 23, 2003", "split": "5\u20134", "answer": "yes", "justices": [{"key": "rehnquist", "name": "William Rehnquist", "meta": "Nixon appointee (R)", "blurb": "Chief Justice for nearly two decades, a genial and ruthlessly efficient administrator with a lifelong project: reviving states' rights and reining in Washington. He has spent his whole career waiting for the votes he now has.", "photo": "photos/rehnquist.jpg", "chief": true}, {"key": "stevens", "name": "John Paul Stevens", "meta": "Ford appointee (R)", "blurb": "The senior associate justice, a bow-tied Ford appointee from Chicago who now marshals the Court's liberal wing. Fiercely independent in method, he assigns the dissents whenever the Chief is on the other side.", "photo": "photos/stevens.jpg"}, {"key": "oconnor", "name": "Sandra Day O'Connor", "meta": "Reagan appointee (R)", "blurb": "A former Arizona legislator and the Court's pivotal vote \u2014 by common consent the most powerful woman in America. She distrusts absolutes and decides case by case; where she lands is usually where the law lands.", "photo": "photos/oconnor.jpg"}, {"key": "scalia", "name": "Antonin Scalia", "meta": "Reagan appointee (R)", "blurb": "The Court's combative originalist, its funniest questioner and its fiercest dissenter. He wants clear rules drawn from text and history, and treats his colleagues' balancing tests as legislation in robes.", "photo": "photos/scalia.jpg"}, {"key": "kennedy", "name": "Anthony Kennedy", "meta": "Reagan appointee (R)", "blurb": "A courtly Sacramento Republican with a taste for sweeping language about liberty and dignity. Conservative by default but persuadable at the margins \u2014 one of the two votes every advocate in the courtroom is chasing.", "photo": "photos/kennedy.jpg"}, {"key": "souter", "name": "David Souter", "meta": "George H. W. Bush appointee (R)", "blurb": "The first President Bush's 'stealth nominee,' a frugal New Hampshire bachelor who confounded his sponsors by settling into the moderate-liberal wing. A common-law traditionalist, devoted to precedent and wary of bold constitutional lurches.", "photo": "photos/souter.jpg"}, {"key": "thomas", "name": "Clarence Thomas", "meta": "George H. W. Bush appointee (R)", "blurb": "The Court's most uncompromising originalist, silent at argument and fearless in print. He would rather overrule a wrong precedent than trim it, and he stakes out positions no other justice will yet join.", "photo": "photos/thomas.jpg"}, {"key": "ginsburg", "name": "Ruth Bader Ginsburg", "meta": "Clinton appointee (D)", "blurb": "The ACLU litigator who dismantled sex-discrimination law brick by brick, now a precise, soft-spoken justice. A minimalist by temperament and a reliable liberal vote on questions of equal citizenship.", "photo": "photos/ginsburg.jpg"}, {"key": "breyer", "name": "Stephen Breyer", "meta": "Clinton appointee (D)", "blurb": "The junior justice, a Harvard administrative-law professor who thinks in workable purposes rather than absolutes. Pragmatic, optimistic about government, and forever spinning elaborate hypotheticals from the bench.", "photo": "photos/breyer.jpg"}], "votes": {"rehnquist": "no", "stevens": "yes", "oconnor": "yes", "scalia": "no", "kennedy": "no", "souter": "yes", "thomas": "no", "ginsburg": "yes", "breyer": "yes"}}, {"id": "rostker-v-goldberg", "era": "The Burger Court \u00b7 October Term 1980", "caseTitle": "Rostker v. Goldberg", "question": "May Congress require only men, and not women, to register for a military draft?", "desc": "Robert Goldberg and other young men first sued in 1971, when the Vietnam draft was live, arguing that a system that conscripts men alone discriminates against them. The case lay dormant until registration returned in 1980. Congress held hearings and concluded that because women are barred from combat, registering them would serve no military purpose. A federal court struck the law down days before the first registration deadline. The Justices must weigh their new scrutiny of sex-based laws against the deference they have always given Congress over the armed forces.", "intro": "The Soviets are in Afghanistan, and President Carter has revived draft registration. He asked Congress to register women too; Congress refused. A lawsuit filed by draft resisters a decade earlier springs back to life.", "decided": "June 25, 1981", "split": "6\u20133", "answer": "yes", "justices": [{"key": "burger", "name": "Warren Burger", "meta": "Nixon appointee (R)", "blurb": "A dozen years into the center chair, the silver-maned Chief looks the part and guards the institution's dignity above all. Conservative on crime and schools, surprisingly pragmatic elsewhere, he assigns opinions with one eye on the headlines.", "photo": "photos/burger.jpg", "chief": true}, {"key": "brennan", "name": "William Brennan", "meta": "Eisenhower appointee (R)", "blurb": "Twenty years on, the great liberal playmaker works a Court that has drifted away from him. He still counts to five better than anyone alive, hunting the center for partners case by case.", "photo": "photos/brennan.jpg"}, {"key": "stewart", "name": "Potter Stewart", "meta": "Eisenhower appointee (R)", "blurb": "The Court's studied centrist, a judge of narrow rulings and practical lines. Eighteen years in, he remains the man both blocs court \u2014 skeptical of absolutes, attentive to how the law actually operates.", "photo": "photos/stewart.jpg"}, {"key": "white", "name": "Byron White", "meta": "Kennedy appointee (D)", "blurb": "JFK's last appointee has hardened into the Court's flintiest pragmatist \u2014 tough on crime, dismissive of rights he cannot find in the Constitution's text, still steady on race and equal protection.", "photo": "photos/white.jpg"}, {"key": "marshall", "name": "Thurgood Marshall", "meta": "Lyndon Johnson appointee (D)", "blurb": "The civil-rights giant in winter, increasingly isolated as the Court moves right. He and Brennan vote as a pair on the death penalty and much else, filing dissent after dissent for a future Court to find.", "photo": "photos/marshall.jpg"}, {"key": "blackmun", "name": "Harry Blackmun", "meta": "Nixon appointee (R)", "blurb": "The Mayo Clinic's meticulous former counsel, an anxious drafter who agonizes over every case. Once dismissed as Burger's 'Minnesota Twin,' he is drifting from the Chief, case by case, toward a path of his own.", "photo": "photos/blackmun.jpg"}, {"key": "powell", "name": "Lewis Powell", "meta": "Nixon appointee (R)", "blurb": "The courtly Richmond lawyer has settled into the Court's center seat, a balancer who distrusts bright lines and sweeping theories alike. He weighs each case like a client matter, writes with a counselor's caution, and seldom finds himself in dissent.", "photo": "photos/powell.jpg"}, {"key": "rehnquist", "name": "William Rehnquist", "meta": "Nixon appointee (R)", "blurb": "The Court's most unapologetic conservative, a brilliant and cheerful writer who would rather dissent alone than join an opinion he doubts. States' rights, law enforcement, judicial restraint \u2014 his compass never wavers, whatever the company.", "photo": "photos/rehnquist.jpg"}, {"key": "stevens", "name": "John Paul Stevens", "meta": "Ford appointee (R)", "blurb": "The newest justice, a bow-tied Chicago antitrust lawyer chosen by Gerald Ford for sheer legal craftsmanship. He belongs to no bloc, writes separate opinions constantly, and steers by his own idiosyncratic compass.", "photo": "photos/stevens.jpg"}], "votes": {"burger": "yes", "brennan": "no", "stewart": "yes", "white": "no", "marshall": "no", "blackmun": "yes", "powell": "yes", "rehnquist": "yes", "stevens": "yes"}}, {"id": "boumediene-v-bush", "era": "The Roberts Court \u00b7 October Term 2007", "caseTitle": "Boumediene v. Bush", "question": "Do foreign detainees held at Guant\u00e1namo have a constitutional right to challenge their detention in federal court?", "desc": "Lakhdar Boumediene, a Red Crescent aid worker, was arrested in Sarajevo in 2001 on suspicion of a plot against the U.S. embassy, cleared by Bosnian courts, and flown to Cuba anyway. The Military Commissions Act of 2006 bars any court from hearing a Guant\u00e1namo detainee's habeas corpus claim, substituting Pentagon review tribunals. The government says a leased base on foreign soil lies outside the Constitution's reach, and wartime detention is for the President and Congress. The detainees say the Great Writ follows the flag wherever America holds a man indefinitely.", "intro": "Six Algerians seized in Bosnia have spent six years at Guant\u00e1namo Bay without charge. Congress has twice stripped the federal courts of power to hear their habeas petitions. The question is whether the Constitution reaches the base at all.", "decided": "June 12, 2008", "split": "5\u20134", "answer": "yes", "justices": [{"key": "roberts", "name": "John Roberts", "meta": "George W. Bush appointee (R)", "blurb": "The chief justice who won the job promising to call balls and strikes, not pitch or bat. A polished Supreme Court advocate turned umpire, he prefers narrow rulings and unanimity where he can get them \u2014 and moves the law by patient inches when he can't.", "photo": "photos/roberts.jpg", "chief": true}, {"key": "stevens_roberts", "name": "John Paul Stevens", "meta": "Ford appointee (R)", "blurb": "The senior associate justice, pushing ninety and sharper than ever: a bow-tied Republican antitrust lawyer appointed by Gerald Ford who became the anchor of the Court's liberal wing. He insists the Court moved, not him.", "photo": "photos/stevens_roberts.jpg"}, {"key": "scalia_roberts", "name": "Antonin Scalia", "meta": "Reagan appointee (R)", "blurb": "Originalism's happy warrior, decades into his crusade to read the Constitution as its ratifiers understood it. His opinions are the Court's best copy, his scorn for 'living constitutionalism' legendary \u2014 and his method has reshaped how every case is argued.", "photo": "photos/scalia_roberts.jpg"}, {"key": "kennedy_roberts", "name": "Anthony Kennedy", "meta": "Reagan appointee (R)", "blurb": "The swing. A courtly Sacramento Republican who controls the outcome in nearly every close case \u2014 and knows it. Liberty and dignity are his lodestars, sweeping language his signature, suspense his permanent gift to Court-watchers.", "photo": "photos/kennedy_roberts.jpg"}, {"key": "souter_roberts", "name": "David Souter", "meta": "George H. W. Bush appointee (R)", "blurb": "A frugal New Hampshire Yankee named by the first President Bush as a 'home run' for conservatives \u2014 who drifted steadily toward the Court's left instead. Skeptical of grand theories, devoted to precedent and to history's complications.", "photo": "photos/souter_roberts.jpg"}, {"key": "thomas_roberts", "name": "Clarence Thomas", "meta": "George H. W. Bush appointee (R)", "blurb": "The Court's most uncompromising originalist, fearless in print: he will discard decades of precedent without apology and stake out positions entirely alone, serenely confident the law will someday catch up to him.", "photo": "photos/thomas_roberts.jpg"}, {"key": "ginsburg_roberts", "name": "Ruth Bader Ginsburg", "meta": "Clinton appointee (D)", "blurb": "The pioneering women's-rights litigator of the 1970s, now the liberal wing's most exacting technician. Small, quiet, and precise, she picks her battles carefully \u2014 and reads her fiercest dissents aloud from the bench when she loses one.", "photo": "photos/ginsburg_roberts.jpg"}, {"key": "breyer_roberts", "name": "Stephen Breyer", "meta": "Clinton appointee (D)", "blurb": "The Court's pragmatist professor: a former Senate staffer and administrative-law scholar who judges by consequences, not grand theory. Endlessly optimistic about government, allergic to absolutes, and famous for winding hypotheticals that leave lawyers blinking.", "photo": "photos/breyer_roberts.jpg"}, {"key": "alito", "name": "Samuel Alito", "meta": "George W. Bush appointee (R)", "blurb": "A former federal prosecutor from New Jersey, methodical and unflashy, with the most reliably conservative instincts on the bench \u2014 above all where crime, religion, or the culture wars are concerned. In dissent, his pen turns acid.", "photo": "photos/alito.jpg"}], "votes": {"roberts": "no", "stevens_roberts": "yes", "scalia_roberts": "no", "kennedy_roberts": "yes", "souter_roberts": "yes", "thomas_roberts": "no", "ginsburg_roberts": "yes", "breyer_roberts": "yes", "alito": "no"}}, {"id": "wallace-v-jaffree", "era": "The Burger Court \u00b7 October Term 1984", "caseTitle": "Wallace v. Jaffree", "question": "May a state set aside a minute of classroom silence 'for meditation or voluntary prayer'?", "desc": "Ishmael Jaffree, an agnostic legal-aid lawyer, says his children were taunted for sitting out classroom prayers. Alabama already had a moment-of-silence law for 'meditation'; in 1981 the legislature added 'or voluntary prayer,' and its sponsor said plainly that the purpose was to return prayer to the schools. A federal judge upheld the law by ruling that the Establishment Clause does not bind the states at all. Twenty-three years after the Court barred official school prayer, the question is whether a silent minute labeled for prayer crosses the same line.", "intro": "Mobile, Alabama. A father of three complains that his children are being led in prayer at public school, and the state answers with a law reserving a daily minute of silence 'for meditation or voluntary prayer.'", "decided": "June 4, 1985", "split": "6\u20133", "answer": "no", "justices": [{"key": "burger", "name": "Warren Burger", "meta": "Nixon appointee (R)", "blurb": "Seventeen years into the center chair, as much administrator as judge \u2014 obsessed with judicial efficiency and courtroom decorum. Reliably conservative on crime and social questions, though colleagues grumble that his opinion assignments follow strategy more than principle.", "photo": "photos/burger.jpg", "chief": true}, {"key": "brennan", "name": "William Brennan", "meta": "Eisenhower appointee (R)", "blurb": "The aging captain of the Court's shrinking liberal wing, three decades in. He can still conjure a majority from thin air on a good day \u2014 but these days he is more often assigning dissents than opinions.", "photo": "photos/brennan.jpg"}, {"key": "white", "name": "Byron White", "meta": "Kennedy appointee (D)", "blurb": "JFK's last appointee has hardened into the Court's flintiest pragmatist \u2014 tough on crime, dismissive of rights he cannot find in the Constitution's text, still steady on race and equal protection.", "photo": "photos/white.jpg"}, {"key": "marshall", "name": "Thurgood Marshall", "meta": "Lyndon Johnson appointee (D)", "blurb": "The civil-rights giant in winter, increasingly isolated as the Court moves right. He and Brennan vote as a pair on the death penalty and much else, filing dissent after dissent for a future Court to find.", "photo": "photos/marshall.jpg"}, {"key": "blackmun", "name": "Harry Blackmun", "meta": "Nixon appointee (R)", "blurb": "The onetime 'Minnesota Twin' has completed a long migration: the shy Nixon appointee now votes more often with Brennan and Marshall than with the Chief he grew up beside \u2014 above all on privacy and equality.", "photo": "photos/blackmun.jpg"}, {"key": "powell", "name": "Lewis Powell", "meta": "Nixon appointee (R)", "blurb": "The Court's gentle fulcrum. The courtly Richmond lawyer decides the close ones \u2014 law clerks joke that the Constitution means whatever Lewis Powell thinks it means \u2014 balancing order against liberty with a counselor's caution.", "photo": "photos/powell.jpg"}, {"key": "rehnquist", "name": "William Rehnquist", "meta": "Nixon appointee (R)", "blurb": "The Court's anchor on the right, so fond of solo dissents that his clerks once gave him a Lone Ranger doll. Federalism, law enforcement, judicial restraint: his positions never wobble \u2014 and the Court, increasingly, comes to him.", "photo": "photos/rehnquist.jpg"}, {"key": "stevens", "name": "John Paul Stevens", "meta": "Ford appointee (R)", "blurb": "The bow-tied Chicagoan defies sorting \u2014 a Ford Republican drifting toward the Court's left flank, case by idiosyncratic case. He writes more separate opinions than anyone, trusting his own reading of the law over any bloc's.", "photo": "photos/stevens.jpg"}, {"key": "oconnor", "name": "Sandra Day O'Connor", "meta": "Reagan appointee (R)", "blurb": "The first woman on the Court, a former Arizona legislative leader who judges like a lawmaker \u2014 narrow rulings, workable compromises, close attention to the facts. Reliably conservative on crime; harder to predict everywhere else.", "photo": "photos/oconnor.jpg"}], "votes": {"burger": "yes", "brennan": "no", "white": "yes", "marshall": "no", "blackmun": "no", "powell": "no", "rehnquist": "yes", "stevens": "no", "oconnor": "no"}}, {"id": "lemon-v-kurtzman", "era": "The Burger Court \u00b7 October Term 1970", "caseTitle": "Lemon v. Kurtzman", "question": "May a state use tax money to help pay the salaries of teachers in church-run schools?", "desc": "Pennsylvania reimburses parochial schools for teachers' salaries, textbooks and materials in secular subjects; Rhode Island pays a fifteen-percent supplement straight to nonpublic-school teachers, nearly all of them in Catholic classrooms. The states insist the money buys mathematics and reading, not catechism. The challengers answer that no one can police where arithmetic ends and religion begins, and that the policing itself entangles church and state. Thurgood Marshall sits out the Pennsylvania case; eight justices will write the rule for every state tempted to follow.", "intro": "Catholic schools are closing by the hundreds, and Pennsylvania and Rhode Island have begun writing checks to keep their teachers paid. A Philadelphia taxpayer named Alton Lemon says the checks must stop.", "decided": "June 28, 1971", "split": "8\u20130", "answer": "no", "justices": [{"key": "burger", "name": "Warren Burger", "meta": "Nixon appointee (R)", "blurb": "Nixon's chief justice, installed to steady a Court he believes ran wild under Earl Warren. A stickler for order and the dignity of institutions, he is more cautious conservative than crusader \u2014 and ever mindful of the Court's public standing.", "photo": "photos/burger.jpg", "chief": true}, {"key": "black", "name": "Hugo Black", "meta": "Franklin Roosevelt appointee (D)", "blurb": "At 85, the New Deal's last titan and the First Amendment's fiercest literalist \u2014 'no law abridging' means no law, period. Frail and near the end of 34 years on the bench, he still writes with the old fire.", "photo": "photos/black.jpg"}, {"key": "douglas", "name": "William O. Douglas", "meta": "Franklin Roosevelt appointee (D)", "blurb": "A New Deal wunderkind grown into the Court's absolutist loner \u2014 three decades on the bench, four wives, a shelf of his own books. He votes for the individual against the government almost reflexively, and writes opinions at breakneck speed.", "photo": "photos/douglas.jpg"}, {"key": "harlan", "name": "John Marshall Harlan", "meta": "Eisenhower appointee (R)", "blurb": "The Court's patrician conservative conscience, a lawyer's lawyer of precision and restraint. Nearly blind, he reads briefs held an inch from his eyes \u2014 and insists that judging is a matter of process and precedent, never passion.", "photo": "photos/harlan.jpg"}, {"key": "brennan", "name": "William Brennan", "meta": "Eisenhower appointee (R)", "blurb": "The Warren Court's master coalition-builder, an Eisenhower appointee turned architect of its liberal revolution. His first rule \u2014 with five votes you can do anything \u2014 still guides him as the bench tilts rightward around him.", "photo": "photos/brennan.jpg"}, {"key": "stewart", "name": "Potter Stewart", "meta": "Eisenhower appointee (R)", "blurb": "A pragmatic Ohio Republican wary of grand theory, he decides cases narrowly and one at a time. Neither wing can count on him: he distrusts government overreach and judicial adventure in roughly equal measure.", "photo": "photos/stewart.jpg"}, {"key": "white", "name": "Byron White", "meta": "Kennedy appointee (D)", "blurb": "The Kennedys' deputy attorney general, an All-America halfback turned no-nonsense pragmatist. Tough on crime and skeptical of newly minted rights, yet often found with the liberals on race and civil rights.", "photo": "photos/white.jpg"}, {"key": "blackmun", "name": "Harry Blackmun", "meta": "Nixon appointee (R)", "blurb": "The junior justice, a shy Minnesota Republican and longtime counsel to the Mayo Clinic. Washington calls him and his boyhood friend the Chief the 'Minnesota Twins' \u2014 so far he votes Burger's way more often than not.", "photo": "photos/blackmun.jpg"}], "votes": {"burger": "no", "black": "no", "douglas": "no", "harlan": "no", "brennan": "no", "stewart": "no", "white": "no", "blackmun": "no"}}, {"id": "plyler-v-doe", "era": "The Burger Court \u00b7 October Term 1981", "caseTitle": "Plyler v. Doe", "question": "May Texas deny a free public education to children who are in the country illegally?", "desc": "A 1975 Texas law withholds state money for the schooling of children not legally admitted to the country and lets districts bar them outright. Tyler chose tuition instead, a sum no farmworker family can pay. Texas says it owes nothing to children whose presence violates federal law. The children's lawyers answer that the Fourteenth Amendment protects every 'person within its jurisdiction,' and that a state cannot create an underclass of illiterates for the sins of their parents. Nine years earlier the Court said education was not a fundamental right.", "intro": "Tyler, Texas. The school district begins charging a thousand dollars a year to any child who cannot prove lawful residence \u2014 and four families of Mexican farmworkers, suing as 'Doe,' ask a federal court to stop it.", "decided": "June 15, 1982", "split": "5\u20134", "answer": "no", "justices": [{"key": "burger", "name": "Warren Burger", "meta": "Nixon appointee (R)", "blurb": "A dozen years into the center chair, the silver-maned Chief looks the part and guards the institution's dignity above all. Conservative on crime and schools, surprisingly pragmatic elsewhere, he assigns opinions with one eye on the headlines.", "photo": "photos/burger.jpg", "chief": true}, {"key": "brennan", "name": "William Brennan", "meta": "Eisenhower appointee (R)", "blurb": "A quarter-century in, the Warren Court's great playmaker now leads a liberal wing of two or three. He still hunts the center vote in every conference, and still lands a surprising number of them \u2014 his clerks call it the rule of five.", "photo": "photos/brennan.jpg"}, {"key": "white", "name": "Byron White", "meta": "Kennedy appointee (D)", "blurb": "JFK's last appointee has hardened into the Court's flintiest pragmatist \u2014 tough on crime, dismissive of rights he cannot find in the Constitution's text, still steady on race and equal protection.", "photo": "photos/white.jpg"}, {"key": "marshall", "name": "Thurgood Marshall", "meta": "Lyndon Johnson appointee (D)", "blurb": "The civil-rights giant in winter, increasingly isolated as the Court moves right. He and Brennan vote as a pair on the death penalty and much else, filing dissent after dissent for a future Court to find.", "photo": "photos/marshall.jpg"}, {"key": "blackmun", "name": "Harry Blackmun", "meta": "Nixon appointee (R)", "blurb": "The onetime 'Minnesota Twin' has completed a long migration: the shy Nixon appointee now votes more often with Brennan and Marshall than with the Chief he grew up beside \u2014 above all on privacy and equality.", "photo": "photos/blackmun.jpg"}, {"key": "powell", "name": "Lewis Powell", "meta": "Nixon appointee (R)", "blurb": "The Court's gentle fulcrum. The courtly Richmond lawyer decides the close ones \u2014 law clerks joke that the Constitution means whatever Lewis Powell thinks it means \u2014 balancing order against liberty with a counselor's caution.", "photo": "photos/powell.jpg"}, {"key": "rehnquist", "name": "William Rehnquist", "meta": "Nixon appointee (R)", "blurb": "The Court's anchor on the right, so fond of solo dissents that his clerks once gave him a Lone Ranger doll. Federalism, law enforcement, judicial restraint: his positions never wobble \u2014 and the Court, increasingly, comes to him.", "photo": "photos/rehnquist.jpg"}, {"key": "stevens", "name": "John Paul Stevens", "meta": "Ford appointee (R)", "blurb": "The bow-tied Chicagoan defies sorting \u2014 a Ford Republican drifting toward the Court's left flank, case by idiosyncratic case. He writes more separate opinions than anyone, trusting his own reading of the law over any bloc's.", "photo": "photos/stevens.jpg"}, {"key": "oconnor", "name": "Sandra Day O'Connor", "meta": "Reagan appointee (R)", "blurb": "The newest justice and the first woman to sit on the Court, a former Arizona legislative leader sworn in last fall. She judges like a lawmaker \u2014 narrow rulings, workable compromises, close attention to the facts \u2014 and no one yet knows where she lands.", "photo": "photos/oconnor.jpg"}], "votes": {"burger": "yes", "brennan": "no", "white": "yes", "marshall": "no", "blackmun": "no", "powell": "no", "rehnquist": "yes", "stevens": "no", "oconnor": "yes"}}, {"id": "milliken-v-bradley", "era": "The Burger Court \u00b7 October Term 1973", "caseTitle": "Milliken v. Bradley", "question": "May a federal court order Detroit's suburbs into a busing plan to desegregate the city's schools?", "desc": "Ronald Bradley was a kindergartner when the NAACP sued in his name. Judge Stephen Roth found Detroit had deliberately segregated its schools, then concluded that any remedy confined to the city would only speed white flight across its borders \u2014 so he ordered buses across them. The suburbs, never found to have done anything wrong, say they are being punished for Detroit's sins. The NAACP answers that a district line is just a line. This is the Court's first look at busing beyond the city limits.", "intro": "Detroit's schools are nearly three-quarters Black and the suburbs nearly all white. A federal judge has decided there is only one way to integrate them: fold fifty-three suburban districts into one metropolitan plan.", "decided": "July 25, 1974", "split": "5\u20134", "answer": "no", "justices": [{"key": "burger", "name": "Warren Burger", "meta": "Nixon appointee (R)", "blurb": "Nixon's chief justice, installed to steady a Court he believes ran wild under Earl Warren. A stickler for order and the dignity of institutions, he is more cautious conservative than crusader \u2014 and ever mindful of the Court's public standing.", "photo": "photos/burger.jpg", "chief": true}, {"key": "douglas", "name": "William O. Douglas", "meta": "Franklin Roosevelt appointee (D)", "blurb": "A New Deal wunderkind grown into the Court's absolutist loner \u2014 three decades on the bench, four wives, a shelf of his own books. He votes for the individual against the government almost reflexively, and writes opinions at breakneck speed.", "photo": "photos/douglas.jpg"}, {"key": "brennan", "name": "William Brennan", "meta": "Eisenhower appointee (R)", "blurb": "The Warren Court's master coalition-builder, an Eisenhower appointee turned architect of its liberal revolution. His first rule \u2014 with five votes you can do anything \u2014 still guides him as the bench tilts rightward around him.", "photo": "photos/brennan.jpg"}, {"key": "stewart", "name": "Potter Stewart", "meta": "Eisenhower appointee (R)", "blurb": "A pragmatic Ohio Republican wary of grand theory, he decides cases narrowly and one at a time. Neither wing can count on him: he distrusts government overreach and judicial adventure in roughly equal measure.", "photo": "photos/stewart.jpg"}, {"key": "white", "name": "Byron White", "meta": "Kennedy appointee (D)", "blurb": "The Kennedys' deputy attorney general, an All-America halfback turned no-nonsense pragmatist. Tough on crime and skeptical of newly minted rights, yet often found with the liberals on race and civil rights.", "photo": "photos/white.jpg"}, {"key": "marshall", "name": "Thurgood Marshall", "meta": "Lyndon Johnson appointee (D)", "blurb": "The architect of Brown v. Board and the Court's first Black justice. He judges from lived experience \u2014 Jim Crow courtrooms, clients facing the electric chair \u2014 and defends the poor and powerless with unembarrassed consistency.", "photo": "photos/marshall.jpg"}, {"key": "blackmun", "name": "Harry Blackmun", "meta": "Nixon appointee (R)", "blurb": "The junior justice, a shy Minnesota Republican and longtime counsel to the Mayo Clinic. Washington calls him and his boyhood friend the Chief the 'Minnesota Twins' \u2014 so far he votes Burger's way more often than not.", "photo": "photos/blackmun.jpg"}, {"key": "powell", "name": "Lewis Powell", "meta": "Nixon appointee (R)", "blurb": "A courtly Richmond corporate lawyer and former ABA president, newly arrived on the bench. The establishment's ideal judge: moderate, balancing, allergic to extremes \u2014 he weighs each case like a client matter and lands, usually, near the center.", "photo": "photos/powell.jpg"}, {"key": "rehnquist", "name": "William Rehnquist", "meta": "Nixon appointee (R)", "blurb": "The junior justice and its boldest conservative \u2014 a 47-year-old Nixon Justice Department lawyer with a brilliant pen and no fear of standing alone. He doubts much of what the Warren Court built.", "photo": "photos/rehnquist.jpg"}], "votes": {"burger": "no", "douglas": "yes", "brennan": "yes", "stewart": "no", "white": "yes", "marshall": "yes", "blackmun": "no", "powell": "no", "rehnquist": "no"}}, {"id": "in-re-gault", "era": "The Warren Court \u00b7 October Term 1966", "caseTitle": "In re Gault", "question": "Does a child facing juvenile court have a constitutional right to notice of the charges, a lawyer, and the chance to confront his accusers?", "desc": "Gerald's parents learned of the hearing after it began; the complaining neighbor never appeared; no witnesses were sworn, no record kept, no lawyer present, and Arizona allows no appeal. Juvenile courts have worked this way since 1899, on the theory that the state acts as a kindly parent and formal rights would only get in the way. Reformers say the theory has produced a system with the punishments of criminal law and none of its protections. The Court must decide whether the Bill of Rights is for adults only.", "intro": "Gerald Gault, fifteen, was picked up in Gila County, Arizona, for a lewd phone call to a neighbor. An adult would have faced a $50 fine or two months in jail. Gerald was committed to the state industrial school until he turned twenty-one.", "decided": "May 15, 1967", "split": "8\u20131", "answer": "yes", "justices": [{"key": "warren", "name": "Earl Warren", "meta": "Eisenhower appointee (R)", "blurb": "The former California governor, now the most consequential Chief Justice in a century. He asks lawyers one question \u2014 'But is it fair?' \u2014 and works the conference like the politician he never stopped being.", "photo": "photos/warren.jpg", "chief": true}, {"key": "black", "name": "Hugo Black", "meta": "Franklin Roosevelt appointee (D)", "blurb": "An Alabama New Dealer who carries the Constitution in his coat pocket and reads it literally. 'No law' means no law \u2014 but rights he cannot find in the text, he will not invent.", "photo": "photos/black.jpg"}, {"key": "douglas", "name": "William O. Douglas", "meta": "Franklin Roosevelt appointee (D)", "blurb": "A restless westerner and the Court's fastest pen \u2014 impatient with doctrine, indifferent to precedent, and instinctively on the side of the lone individual against the government in nearly any form it takes.", "photo": "photos/douglas.jpg"}, {"key": "clark", "name": "Tom C. Clark", "meta": "Truman appointee (D)", "blurb": "Truman's Attorney General in a trademark bow tie \u2014 the Court's law-and-order Texan. He backs the police and the prosecutor by instinct, but he ran federal law enforcement himself and knows its temptations from the inside.", "photo": "photos/clark.jpg"}, {"key": "harlan", "name": "John Marshall Harlan", "meta": "Eisenhower appointee (R)", "blurb": "The Wall Street patrician and grandson of a great dissenter \u2014 the Court's conservative conscience. He believes in ordered liberty and lawyerly process, and objects, elegantly, when the majority moves too far, too fast.", "photo": "photos/harlan.jpg"}, {"key": "brennan", "name": "William Brennan", "meta": "Eisenhower appointee (R)", "blurb": "The Court's Irish charmer and master coalition-builder, an Eisenhower appointee who turned out to be its most effective liberal. His first rule of the shop: with five votes, you can do anything.", "photo": "photos/brennan.jpg"}, {"key": "stewart", "name": "Potter Stewart", "meta": "Eisenhower appointee (R)", "blurb": "A moderate Ohio Republican who resists both blocs' grand theories. He decides cases one at a time, asks what the Constitution actually commands, and lands \u2014 unpredictably \u2014 somewhere in the middle.", "photo": "photos/stewart.jpg"}, {"key": "white", "name": "Byron White", "meta": "Kennedy appointee (D)", "blurb": "'Whizzer' White, the All-American halfback turned Kennedy's deputy attorney general \u2014 tough-minded, unsentimental, and skeptical of newly minted rights, especially the kind that make police work harder.", "photo": "photos/white.jpg"}, {"key": "fortas", "name": "Abe Fortas", "meta": "Lyndon Johnson appointee (D)", "blurb": "LBJ's confidant and Washington's premier lawyer, still quietly advising the President from the bench. As an advocate he won poor defendants their counsel; as a justice he champions the underdog \u2014 children included.", "photo": "photos/fortas.jpg"}], "votes": {"warren": "yes", "black": "yes", "douglas": "yes", "clark": "yes", "harlan": "yes", "brennan": "yes", "stewart": "no", "white": "yes", "fortas": "yes"}}, {"id": "harper-v-virginia", "era": "The Warren Court \u00b7 October Term 1965", "caseTitle": "Harper v. Virginia Board of Elections", "question": "May a state require payment of a poll tax as a condition of voting in state elections?", "desc": "Annie Harper, a retired domestic worker from Fairfax County, cannot afford Virginia's poll tax and sues to vote without paying it. Four states still levy one. The Court upheld such taxes in 1937, and Virginia notes that a modest fee applies to everyone regardless of race. The challengers answer that the tax was adopted in 1902 to clear Black and poor white voters from the rolls, and that it works. May wealth have anything to do with the franchise \u2014 and should the Court, rather than an amendment, say so?", "intro": "Virginia charges $1.50 a year to vote, payable six months before the election, three years in arrears if you have lapsed. The Twenty-fourth Amendment abolished the tax in federal elections two years ago; state elections are another matter.", "decided": "March 24, 1966", "split": "6\u20133", "answer": "no", "justices": [{"key": "warren", "name": "Earl Warren", "meta": "Eisenhower appointee (R)", "blurb": "The former California governor, now the most consequential Chief Justice in a century. He asks lawyers one question \u2014 'But is it fair?' \u2014 and works the conference like the politician he never stopped being.", "photo": "photos/warren.jpg", "chief": true}, {"key": "black", "name": "Hugo Black", "meta": "Franklin Roosevelt appointee (D)", "blurb": "An Alabama New Dealer who carries the Constitution in his coat pocket and reads it literally. 'No law' means no law \u2014 but rights he cannot find in the text, he will not invent.", "photo": "photos/black.jpg"}, {"key": "douglas", "name": "William O. Douglas", "meta": "Franklin Roosevelt appointee (D)", "blurb": "A restless westerner and the Court's fastest pen \u2014 impatient with doctrine, indifferent to precedent, and instinctively on the side of the lone individual against the government in nearly any form it takes.", "photo": "photos/douglas.jpg"}, {"key": "clark", "name": "Tom C. Clark", "meta": "Truman appointee (D)", "blurb": "Truman's Attorney General in a trademark bow tie \u2014 the Court's law-and-order Texan. He backs the police and the prosecutor by instinct, but he ran federal law enforcement himself and knows its temptations from the inside.", "photo": "photos/clark.jpg"}, {"key": "harlan", "name": "John Marshall Harlan", "meta": "Eisenhower appointee (R)", "blurb": "The Wall Street patrician and grandson of a great dissenter \u2014 the Court's conservative conscience. He believes in ordered liberty and lawyerly process, and objects, elegantly, when the majority moves too far, too fast.", "photo": "photos/harlan.jpg"}, {"key": "brennan", "name": "William Brennan", "meta": "Eisenhower appointee (R)", "blurb": "The Court's Irish charmer and master coalition-builder, an Eisenhower appointee who turned out to be its most effective liberal. His first rule of the shop: with five votes, you can do anything.", "photo": "photos/brennan.jpg"}, {"key": "stewart", "name": "Potter Stewart", "meta": "Eisenhower appointee (R)", "blurb": "A moderate Ohio Republican who resists both blocs' grand theories. He decides cases one at a time, asks what the Constitution actually commands, and lands \u2014 unpredictably \u2014 somewhere in the middle.", "photo": "photos/stewart.jpg"}, {"key": "white", "name": "Byron White", "meta": "Kennedy appointee (D)", "blurb": "'Whizzer' White, the All-American halfback turned Kennedy's deputy attorney general \u2014 tough-minded, unsentimental, and skeptical of newly minted rights, especially the kind that make police work harder.", "photo": "photos/white.jpg"}, {"key": "fortas", "name": "Abe Fortas", "meta": "Lyndon Johnson appointee (D)", "blurb": "LBJ's confidant and Washington's premier lawyer, still quietly advising the President from the bench. As an advocate he won poor defendants their counsel; as a justice he champions the underdog \u2014 children included.", "photo": "photos/fortas.jpg"}], "votes": {"warren": "no", "black": "yes", "douglas": "no", "clark": "no", "harlan": "yes", "brennan": "no", "stewart": "yes", "white": "no", "fortas": "no"}}, {"id": "hazelwood-v-kuhlmeier", "era": "The Rehnquist Court \u00b7 October Term 1987", "caseTitle": "Hazelwood School District v. Kuhlmeier", "question": "May a public school principal cut stories from a student newspaper produced in a journalism class?", "desc": "The Spectrum was written and edited by the Journalism II class and printed with school money. Principal Robert Reynolds, reviewing page proofs, found the pregnancy story \u2014 three pregnant students, anonymous but perhaps recognizable \u2014 unfit for younger readers, and the divorce piece unfair to a father who had no chance to respond. With the deadline hours away, he deleted both pages. Cathy Kuhlmeier and two classmates sued. Tinker protected students' armbands two decades ago; the school says a classroom newspaper is a different thing from a student's own speech.", "intro": "At Hazelwood East High School outside St. Louis, the principal pulls two pages from the student newspaper before it goes to press: a story on teen pregnancy and one on divorce. Three student journalists say he has censored them.", "decided": "January 13, 1988", "split": "5\u20133", "answer": "yes", "justices": [{"key": "rehnquist88", "name": "William Rehnquist", "meta": "Nixon appointee (R)", "blurb": "Two terms into the chief justiceship after fifteen years as the Court's lone-wolf conservative dissenter \u2014 a genial, poker-playing states'-rights man who now assigns the opinions and is learning to hold majorities rather than write dissents.", "photo": "photos/rehnquist88.jpg", "chief": true}, {"key": "brennan", "name": "William Brennan", "meta": "Eisenhower appointee (R)", "blurb": "The architect of the Warren Court's rights revolution, now 81 and the senior associate justice. Still the Court's great coalition-builder \u2014 'five votes can do anything around here' \u2014 and with Powell gone, counting harder than ever.", "photo": "photos/brennan.jpg"}, {"key": "white", "name": "Byron White", "meta": "Kennedy appointee (D)", "blurb": "A Kennedy appointee and former NFL halfback, gruff and unsentimental. Hard on criminal defendants, skeptical of newly minted rights, steady on civil rights \u2014 he defies every label, writes short opinions, and asks no one's permission.", "photo": "photos/white.jpg"}, {"key": "marshall", "name": "Thurgood Marshall", "meta": "Lyndon Johnson appointee (D)", "blurb": "The lawyer who won Brown v. Board of Education, now the Court's most unwavering liberal. He votes against every death sentence and speaks for the poor and powerless \u2014 increasingly in dissent, shoulder to shoulder with Brennan.", "photo": "photos/marshall.jpg"}, {"key": "blackmun", "name": "Harry Blackmun", "meta": "Nixon appointee (R)", "blurb": "The Nixon appointee who wrote Roe v. Wade and has drifted left ever since, marked by the backlash. A meticulous former counsel to the Mayo Clinic, sensitive and deliberate, usually found alongside Brennan and Marshall.", "photo": "photos/blackmun.jpg"}, {"key": "stevens88", "name": "John Paul Stevens", "meta": "Ford appointee (R)", "blurb": "A Ford appointee and Chicago antitrust lawyer with a bow tie and a ferociously independent streak. He follows his own analysis wherever it leads and scatters solo opinions along the way \u2014 beholden to no bloc.", "photo": "photos/stevens88.jpg"}, {"key": "oconnor88", "name": "Sandra Day O'Connor", "meta": "Reagan appointee (R)", "blurb": "The first woman on the Court, a former Arizona legislative leader who judges the way she once governed: case by case, fact by fact, wary of sweeping rules. With Powell retired, she is the Court's center of gravity.", "photo": "photos/oconnor88.jpg"}, {"key": "scalia88", "name": "Antonin Scalia", "meta": "Reagan appointee (R)", "blurb": "Reagan's combative textualist, in only his second term and already the Court's sharpest pen. He reads constitutional text at face value wherever it points \u2014 and delights in skewering colleagues who balance interests instead.", "photo": "photos/scalia88.jpg"}], "votes": {"rehnquist88": "yes", "brennan": "no", "white": "yes", "marshall": "no", "blackmun": "no", "stevens88": "yes", "oconnor88": "yes", "scalia88": "yes"}}, {"id": "bob-jones-university-v-us", "era": "The Burger Court \u00b7 October Term 1982", "caseTitle": "Bob Jones University v. United States", "question": "May the IRS deny tax-exempt status to a religious university that bans interracial dating?", "desc": "Bob Jones University admitted no Black students until 1971 and still expels any student who dates or marries outside his race. Since 1970 the IRS has refused charitable status to schools that discriminate by race, reasoning that a charity must serve the public good. In January 1982 the Reagan Justice Department switched to the university's side, and the Court appointed an outside lawyer, William Coleman, to defend the government's old position. At stake: whether the tax code may enforce national policy against sincere religious belief.", "intro": "A fundamentalist college in Greenville, South Carolina, forbids its students to date across racial lines, citing Scripture. The IRS says that forfeits its tax exemption. The Reagan administration, mid-case, switches sides.", "decided": "May 24, 1983", "split": "8\u20131", "answer": "yes", "justices": [{"key": "burger", "name": "Warren Burger", "meta": "Nixon appointee (R)", "blurb": "A dozen years into the center chair, the silver-maned Chief looks the part and guards the institution's dignity above all. Conservative on crime and schools, surprisingly pragmatic elsewhere, he assigns opinions with one eye on the headlines.", "photo": "photos/burger.jpg", "chief": true}, {"key": "brennan", "name": "William Brennan", "meta": "Eisenhower appointee (R)", "blurb": "A quarter-century in, the Warren Court's great playmaker now leads a liberal wing of two or three. He still hunts the center vote in every conference, and still lands a surprising number of them \u2014 his clerks call it the rule of five.", "photo": "photos/brennan.jpg"}, {"key": "white", "name": "Byron White", "meta": "Kennedy appointee (D)", "blurb": "JFK's last appointee has hardened into the Court's flintiest pragmatist \u2014 tough on crime, dismissive of rights he cannot find in the Constitution's text, still steady on race and equal protection.", "photo": "photos/white.jpg"}, {"key": "marshall", "name": "Thurgood Marshall", "meta": "Lyndon Johnson appointee (D)", "blurb": "The civil-rights giant in winter, increasingly isolated as the Court moves right. He and Brennan vote as a pair on the death penalty and much else, filing dissent after dissent for a future Court to find.", "photo": "photos/marshall.jpg"}, {"key": "blackmun", "name": "Harry Blackmun", "meta": "Nixon appointee (R)", "blurb": "The onetime 'Minnesota Twin' has completed a long migration: the shy Nixon appointee now votes more often with Brennan and Marshall than with the Chief he grew up beside \u2014 above all on privacy and equality.", "photo": "photos/blackmun.jpg"}, {"key": "powell", "name": "Lewis Powell", "meta": "Nixon appointee (R)", "blurb": "The Court's gentle fulcrum. The courtly Richmond lawyer decides the close ones \u2014 law clerks joke that the Constitution means whatever Lewis Powell thinks it means \u2014 balancing order against liberty with a counselor's caution.", "photo": "photos/powell.jpg"}, {"key": "rehnquist", "name": "William Rehnquist", "meta": "Nixon appointee (R)", "blurb": "The Court's anchor on the right, so fond of solo dissents that his clerks once gave him a Lone Ranger doll. Federalism, law enforcement, judicial restraint: his positions never wobble \u2014 and the Court, increasingly, comes to him.", "photo": "photos/rehnquist.jpg"}, {"key": "stevens", "name": "John Paul Stevens", "meta": "Ford appointee (R)", "blurb": "The bow-tied Chicagoan defies sorting \u2014 a Ford Republican drifting toward the Court's left flank, case by idiosyncratic case. He writes more separate opinions than anyone, trusting his own reading of the law over any bloc's.", "photo": "photos/stevens.jpg"}, {"key": "oconnor", "name": "Sandra Day O'Connor", "meta": "Reagan appointee (R)", "blurb": "The newest justice and the first woman to sit on the Court, a former Arizona legislative leader sworn in last fall. She judges like a lawmaker \u2014 narrow rulings, workable compromises, close attention to the facts \u2014 and no one yet knows where she lands.", "photo": "photos/oconnor.jpg"}], "votes": {"burger": "yes", "brennan": "yes", "white": "yes", "marshall": "yes", "blackmun": "yes", "powell": "yes", "rehnquist": "no", "stevens": "yes", "oconnor": "yes"}}, {"id": "snyder-v-phelps", "era": "The Roberts Court \u00b7 October Term 2010", "caseTitle": "Snyder v. Phelps", "question": "Does the First Amendment shield funeral picketers from a lawsuit by the grieving family they distressed?", "desc": "Fred Phelps and his family have picketed hundreds of military funerals, preaching that American war deaths are God's punishment for tolerating homosexuality. They notified police, obeyed every ordinance, and stayed on public land where Albert Snyder saw only the tops of their signs; he read their message later on the news. A jury awarded him millions for intentional infliction of emotional distress and invasion of privacy. Forty-eight states and the Senate majority leader back Snyder; the press and civil libertarians, holding their noses, back Westboro's right to say it.", "intro": "Marine Lance Corporal Matthew Snyder is killed in Iraq. At his funeral in Westminster, Maryland, members of Westboro Baptist Church stand a thousand feet away with signs reading 'Thank God for Dead Soldiers.' His father sues them.", "decided": "March 2, 2011", "split": "8\u20131", "answer": "yes", "justices": [{"key": "roberts", "name": "John Roberts", "meta": "George W. Bush appointee (R)", "blurb": "The chief justice who won the job promising to call balls and strikes, not pitch or bat. A polished Supreme Court advocate turned umpire, he prefers narrow rulings and unanimity where he can get them \u2014 and moves the law by patient inches when he can't.", "photo": "photos/roberts.jpg", "chief": true}, {"key": "scalia_roberts", "name": "Antonin Scalia", "meta": "Reagan appointee (R)", "blurb": "Originalism's happy warrior, decades into his crusade to read the Constitution as its ratifiers understood it. His opinions are the Court's best copy, his scorn for 'living constitutionalism' legendary \u2014 and his method has reshaped how every case is argued.", "photo": "photos/scalia_roberts.jpg"}, {"key": "kennedy_roberts", "name": "Anthony Kennedy", "meta": "Reagan appointee (R)", "blurb": "The swing. A courtly Sacramento Republican who controls the outcome in nearly every close case \u2014 and knows it. Liberty and dignity are his lodestars, sweeping language his signature, suspense his permanent gift to Court-watchers.", "photo": "photos/kennedy_roberts.jpg"}, {"key": "thomas_roberts", "name": "Clarence Thomas", "meta": "George H. W. Bush appointee (R)", "blurb": "The Court's most uncompromising originalist, fearless in print: he will discard decades of precedent without apology and stake out positions entirely alone, serenely confident the law will someday catch up to him.", "photo": "photos/thomas_roberts.jpg"}, {"key": "ginsburg_roberts", "name": "Ruth Bader Ginsburg", "meta": "Clinton appointee (D)", "blurb": "The pioneering women's-rights litigator of the 1970s, now the liberal wing's most exacting technician. Small, quiet, and precise, she picks her battles carefully \u2014 and reads her fiercest dissents aloud from the bench when she loses one.", "photo": "photos/ginsburg_roberts.jpg"}, {"key": "breyer_roberts", "name": "Stephen Breyer", "meta": "Clinton appointee (D)", "blurb": "The Court's pragmatist professor: a former Senate staffer and administrative-law scholar who judges by consequences, not grand theory. Endlessly optimistic about government, allergic to absolutes, and famous for winding hypotheticals that leave lawyers blinking.", "photo": "photos/breyer_roberts.jpg"}, {"key": "alito", "name": "Samuel Alito", "meta": "George W. Bush appointee (R)", "blurb": "A former federal prosecutor from New Jersey, methodical and unflashy, with the most reliably conservative instincts on the bench \u2014 above all where crime, religion, or the culture wars are concerned. In dissent, his pen turns acid.", "photo": "photos/alito.jpg"}, {"key": "sotomayor", "name": "Sonia Sotomayor", "meta": "Obama appointee (D)", "blurb": "From a Bronx housing project to Princeton to the federal trial bench: the first Latina justice never lets the Court forget how doctrine lands on actual people. A former prosecutor, relentless at argument, the liberal wing's most passionate voice.", "photo": "photos/sotomayor.jpg"}, {"key": "kagan", "name": "Elena Kagan", "meta": "Obama appointee (D)", "blurb": "The former Harvard Law dean and solicitor general, a coalition-builder who learned her politics in the Clinton White House. The liberal wing's tactician: she writes in plain, wry English and plays a patient long game of her own.", "photo": "photos/kagan.jpg"}], "votes": {"roberts": "yes", "scalia_roberts": "yes", "kennedy_roberts": "yes", "thomas_roberts": "yes", "ginsburg_roberts": "yes", "breyer_roberts": "yes", "alito": "no", "sotomayor": "yes", "kagan": "yes"}}, {"id": "burwell-v-hobby-lobby", "era": "The Roberts Court \u00b7 October Term 2013", "caseTitle": "Burwell v. Hobby Lobby Stores", "question": "May a closely held for-profit company refuse on religious grounds to cover contraception in its employees' health plan?", "desc": "Under the contraceptive mandate, employer plans must cover all FDA-approved birth control; the Greens object to four methods, including morning-after pills and IUDs, that they believe can end a fertilized egg. The fine for refusing would run to $475 million a year. The Religious Freedom Restoration Act forbids the government to substantially burden a 'person's' exercise of religion without a compelling reason. Does a for-profit corporation have religion to exercise? Churches and nonprofits already have exemptions; the government says the line stops there. Thousands of employees' coverage hangs on it.", "intro": "The Green family runs Hobby Lobby \u2014 500 craft stores, 13,000 employees \u2014 as a Christian business closed on Sundays. The Affordable Care Act now requires their health plan to cover contraceptives they consider abortifacients: a choice, they say, between faith and ruin.", "decided": "June 30, 2014", "split": "5\u20134", "answer": "yes", "justices": [{"key": "roberts", "name": "John Roberts", "meta": "George W. Bush appointee (R)", "blurb": "The chief justice who won the job promising to call balls and strikes, not pitch or bat. A polished Supreme Court advocate turned umpire, he prefers narrow rulings and unanimity where he can get them \u2014 and moves the law by patient inches when he can't.", "photo": "photos/roberts.jpg", "chief": true}, {"key": "scalia_roberts", "name": "Antonin Scalia", "meta": "Reagan appointee (R)", "blurb": "Originalism's happy warrior, decades into his crusade to read the Constitution as its ratifiers understood it. His opinions are the Court's best copy, his scorn for 'living constitutionalism' legendary \u2014 and his method has reshaped how every case is argued.", "photo": "photos/scalia_roberts.jpg"}, {"key": "kennedy_roberts", "name": "Anthony Kennedy", "meta": "Reagan appointee (R)", "blurb": "The swing. A courtly Sacramento Republican who controls the outcome in nearly every close case \u2014 and knows it. Liberty and dignity are his lodestars, sweeping language his signature, suspense his permanent gift to Court-watchers.", "photo": "photos/kennedy_roberts.jpg"}, {"key": "thomas_roberts", "name": "Clarence Thomas", "meta": "George H. W. Bush appointee (R)", "blurb": "The Court's most uncompromising originalist, fearless in print: he will discard decades of precedent without apology and stake out positions entirely alone, serenely confident the law will someday catch up to him.", "photo": "photos/thomas_roberts.jpg"}, {"key": "ginsburg_roberts", "name": "Ruth Bader Ginsburg", "meta": "Clinton appointee (D)", "blurb": "The pioneering women's-rights litigator of the 1970s, now the liberal wing's most exacting technician. Small, quiet, and precise, she picks her battles carefully \u2014 and reads her fiercest dissents aloud from the bench when she loses one.", "photo": "photos/ginsburg_roberts.jpg"}, {"key": "breyer_roberts", "name": "Stephen Breyer", "meta": "Clinton appointee (D)", "blurb": "The Court's pragmatist professor: a former Senate staffer and administrative-law scholar who judges by consequences, not grand theory. Endlessly optimistic about government, allergic to absolutes, and famous for winding hypotheticals that leave lawyers blinking.", "photo": "photos/breyer_roberts.jpg"}, {"key": "alito", "name": "Samuel Alito", "meta": "George W. Bush appointee (R)", "blurb": "A former federal prosecutor from New Jersey, methodical and unflashy, with the most reliably conservative instincts on the bench \u2014 above all where crime, religion, or the culture wars are concerned. In dissent, his pen turns acid.", "photo": "photos/alito.jpg"}, {"key": "sotomayor", "name": "Sonia Sotomayor", "meta": "Obama appointee (D)", "blurb": "From a Bronx housing project to Princeton to the federal trial bench: the first Latina justice never lets the Court forget how doctrine lands on actual people. A former prosecutor, relentless at argument, the liberal wing's most passionate voice.", "photo": "photos/sotomayor.jpg"}, {"key": "kagan", "name": "Elena Kagan", "meta": "Obama appointee (D)", "blurb": "The former Harvard Law dean and solicitor general, a coalition-builder who learned her politics in the Clinton White House. The liberal wing's tactician: she writes in plain, wry English and plays a patient long game of her own.", "photo": "photos/kagan.jpg"}], "votes": {"roberts": "yes", "scalia_roberts": "yes", "kennedy_roberts": "yes", "thomas_roberts": "yes", "ginsburg_roberts": "no", "breyer_roberts": "no", "alito": "yes", "sotomayor": "no", "kagan": "no"}}, {"id": "shapiro-v-thompson", "era": "The Warren Court \u00b7 October Term 1968", "caseTitle": "Shapiro v. Thompson", "question": "May a state deny welfare benefits to needy families who moved there less than a year ago?", "desc": "Forty states and the District of Columbia impose a one-year residency requirement for public assistance, and Congress has expressly permitted it. The states say the rule protects their treasuries from an influx of the poor and ensures newcomers have some stake in the community before drawing on it. Thompson's lawyers, from the new federally funded legal-services movement, answer that the Constitution guarantees a right to travel, and that sorting citizens into old and new residents \u2014 the new left hungry \u2014 denies equal protection. The case has been argued twice.", "intro": "Vivian Thompson, nineteen, pregnant and the mother of a toddler, moved from Boston to Hartford to be near her mother. Connecticut turned down her application for aid: she had not lived in the state for a year.", "decided": "April 21, 1969", "split": "6\u20133", "answer": "no", "justices": [{"key": "warren", "name": "Earl Warren", "meta": "Eisenhower appointee (R)", "blurb": "The former California governor, now the most consequential Chief Justice in a century. He asks lawyers one question \u2014 'But is it fair?' \u2014 and works the conference like the politician he never stopped being.", "photo": "photos/warren.jpg", "chief": true}, {"key": "black", "name": "Hugo Black", "meta": "Franklin Roosevelt appointee (D)", "blurb": "An Alabama New Dealer who carries the Constitution in his coat pocket and reads it literally. 'No law' means no law \u2014 but rights he cannot find in the text, he will not invent.", "photo": "photos/black.jpg"}, {"key": "douglas", "name": "William O. Douglas", "meta": "Franklin Roosevelt appointee (D)", "blurb": "A restless westerner and the Court's fastest pen \u2014 impatient with doctrine, indifferent to precedent, and instinctively on the side of the lone individual against the government in nearly any form it takes.", "photo": "photos/douglas.jpg"}, {"key": "harlan", "name": "John Marshall Harlan", "meta": "Eisenhower appointee (R)", "blurb": "The Wall Street patrician and grandson of a great dissenter \u2014 the Court's conservative conscience. He believes in ordered liberty and lawyerly process, and objects, elegantly, when the majority moves too far, too fast.", "photo": "photos/harlan.jpg"}, {"key": "brennan", "name": "William Brennan", "meta": "Eisenhower appointee (R)", "blurb": "The Court's Irish charmer and master coalition-builder, an Eisenhower appointee who turned out to be its most effective liberal. His first rule of the shop: with five votes, you can do anything.", "photo": "photos/brennan.jpg"}, {"key": "stewart", "name": "Potter Stewart", "meta": "Eisenhower appointee (R)", "blurb": "A moderate Ohio Republican who resists both blocs' grand theories. He decides cases one at a time, asks what the Constitution actually commands, and lands \u2014 unpredictably \u2014 somewhere in the middle.", "photo": "photos/stewart.jpg"}, {"key": "white", "name": "Byron White", "meta": "Kennedy appointee (D)", "blurb": "'Whizzer' White, the All-American halfback turned Kennedy's deputy attorney general \u2014 tough-minded, unsentimental, and skeptical of newly minted rights, especially the kind that make police work harder.", "photo": "photos/white.jpg"}, {"key": "fortas", "name": "Abe Fortas", "meta": "Lyndon Johnson appointee (D)", "blurb": "LBJ's confidant and Washington's premier lawyer, still quietly advising the President from the bench. As an advocate he won poor defendants their counsel; as a justice he champions the underdog \u2014 children included.", "photo": "photos/fortas.jpg"}, {"key": "marshall", "name": "Thurgood Marshall", "meta": "Lyndon Johnson appointee (D)", "blurb": "The architect of the NAACP's litigation war on Jim Crow and the first Black justice \u2014 a storyteller who has seen the criminal law from the defendant's side of the table and never forgets it.", "photo": "photos/marshall.jpg"}], "votes": {"warren": "yes", "black": "yes", "douglas": "no", "harlan": "yes", "brennan": "no", "stewart": "no", "white": "no", "fortas": "no", "marshall": "no"}}, {"id": "south-carolina-v-katzenbach", "era": "The Warren Court \u00b7 October Term 1965", "caseTitle": "South Carolina v. Katzenbach", "question": "May Congress require states with a history of voting discrimination to get federal approval before changing their election laws?", "desc": "The Act covers any state that used a literacy test and had less than half its adults voting in 1964 \u2014 six Southern states and part of a seventh. None may change a voting rule without clearance from the Attorney General or a federal court in Washington. South Carolina, backed by five other states, says Congress has singled out sovereign states for punishment and seized their power over the ballot. Attorney General Nicholas Katzenbach answers that ninety-five years of case-by-case litigation failed, and the Fifteenth Amendment lets Congress enforce it.", "intro": "Seven months after Selma, the Voting Rights Act of 1965 suspends literacy tests across the Deep South and sends federal examiners to register voters. South Carolina goes straight to the Supreme Court to call the whole thing unconstitutional.", "decided": "March 7, 1966", "split": "8\u20131", "answer": "yes", "justices": [{"key": "warren", "name": "Earl Warren", "meta": "Eisenhower appointee (R)", "blurb": "The former California governor, now the most consequential Chief Justice in a century. He asks lawyers one question \u2014 'But is it fair?' \u2014 and works the conference like the politician he never stopped being.", "photo": "photos/warren.jpg", "chief": true}, {"key": "black", "name": "Hugo Black", "meta": "Franklin Roosevelt appointee (D)", "blurb": "An Alabama New Dealer who carries the Constitution in his coat pocket and reads it literally. 'No law' means no law \u2014 but rights he cannot find in the text, he will not invent.", "photo": "photos/black.jpg"}, {"key": "douglas", "name": "William O. Douglas", "meta": "Franklin Roosevelt appointee (D)", "blurb": "A restless westerner and the Court's fastest pen \u2014 impatient with doctrine, indifferent to precedent, and instinctively on the side of the lone individual against the government in nearly any form it takes.", "photo": "photos/douglas.jpg"}, {"key": "clark", "name": "Tom C. Clark", "meta": "Truman appointee (D)", "blurb": "Truman's Attorney General in a trademark bow tie \u2014 the Court's law-and-order Texan. He backs the police and the prosecutor by instinct, but he ran federal law enforcement himself and knows its temptations from the inside.", "photo": "photos/clark.jpg"}, {"key": "harlan", "name": "John Marshall Harlan", "meta": "Eisenhower appointee (R)", "blurb": "The Wall Street patrician and grandson of a great dissenter \u2014 the Court's conservative conscience. He believes in ordered liberty and lawyerly process, and objects, elegantly, when the majority moves too far, too fast.", "photo": "photos/harlan.jpg"}, {"key": "brennan", "name": "William Brennan", "meta": "Eisenhower appointee (R)", "blurb": "The Court's Irish charmer and master coalition-builder, an Eisenhower appointee who turned out to be its most effective liberal. His first rule of the shop: with five votes, you can do anything.", "photo": "photos/brennan.jpg"}, {"key": "stewart", "name": "Potter Stewart", "meta": "Eisenhower appointee (R)", "blurb": "A moderate Ohio Republican who resists both blocs' grand theories. He decides cases one at a time, asks what the Constitution actually commands, and lands \u2014 unpredictably \u2014 somewhere in the middle.", "photo": "photos/stewart.jpg"}, {"key": "white", "name": "Byron White", "meta": "Kennedy appointee (D)", "blurb": "'Whizzer' White, the All-American halfback turned Kennedy's deputy attorney general \u2014 tough-minded, unsentimental, and skeptical of newly minted rights, especially the kind that make police work harder.", "photo": "photos/white.jpg"}, {"key": "fortas", "name": "Abe Fortas", "meta": "Lyndon Johnson appointee (D)", "blurb": "LBJ's confidant and Washington's premier lawyer, still quietly advising the President from the bench. As an advocate he won poor defendants their counsel; as a justice he champions the underdog \u2014 children included.", "photo": "photos/fortas.jpg"}], "votes": {"warren": "yes", "black": "no", "douglas": "yes", "clark": "yes", "harlan": "yes", "brennan": "yes", "stewart": "yes", "white": "yes", "fortas": "yes"}}, {"id": "us-term-limits-v-thornton", "era": "The Rehnquist Court \u00b7 October Term 1994", "caseTitle": "U.S. Term Limits v. Thornton", "question": "May a state impose term limits on its own members of Congress?", "desc": "Amendment 73 passed with sixty percent of the vote, riding the national term-limits wave of the early nineties. Thornton, a Democrat seeking a fourth House term, argues that the Constitution fixes the qualifications for Congress \u2014 age, citizenship, residence \u2014 and that no state may add to them. U.S. Term Limits, the group behind the measure, replies that a ballot-access rule is no qualification, and that powers not forbidden to the states remain theirs. Underneath lies the union itself: are members of Congress the people's agents, or the states'?", "intro": "In 1992 Arkansas voters amend their constitution to keep anyone who has served three terms in the House, or two in the Senate, off the ballot. Twenty-two other states have done something similar. Congressman Ray Thornton sues.", "decided": "May 22, 1995", "split": "5\u20134", "answer": "no", "justices": [{"key": "rehnquist", "name": "William Rehnquist", "meta": "Nixon appointee (R)", "blurb": "Chief Justice for nearly two decades, a genial and ruthlessly efficient administrator with a lifelong project: reviving states' rights and reining in Washington. He has spent his whole career waiting for the votes he now has.", "photo": "photos/rehnquist.jpg", "chief": true}, {"key": "stevens", "name": "John Paul Stevens", "meta": "Ford appointee (R)", "blurb": "The senior associate justice, a bow-tied Ford appointee from Chicago who now marshals the Court's liberal wing. Fiercely independent in method, he assigns the dissents whenever the Chief is on the other side.", "photo": "photos/stevens.jpg"}, {"key": "oconnor", "name": "Sandra Day O'Connor", "meta": "Reagan appointee (R)", "blurb": "A former Arizona legislator and the Court's pivotal vote \u2014 by common consent the most powerful woman in America. She distrusts absolutes and decides case by case; where she lands is usually where the law lands.", "photo": "photos/oconnor.jpg"}, {"key": "scalia", "name": "Antonin Scalia", "meta": "Reagan appointee (R)", "blurb": "The Court's combative originalist, its funniest questioner and its fiercest dissenter. He wants clear rules drawn from text and history, and treats his colleagues' balancing tests as legislation in robes.", "photo": "photos/scalia.jpg"}, {"key": "kennedy", "name": "Anthony Kennedy", "meta": "Reagan appointee (R)", "blurb": "A courtly Sacramento Republican with a taste for sweeping language about liberty and dignity. Conservative by default but persuadable at the margins \u2014 one of the two votes every advocate in the courtroom is chasing.", "photo": "photos/kennedy.jpg"}, {"key": "souter", "name": "David Souter", "meta": "George H. W. Bush appointee (R)", "blurb": "The first President Bush's 'stealth nominee,' a frugal New Hampshire bachelor who confounded his sponsors by settling into the moderate-liberal wing. A common-law traditionalist, devoted to precedent and wary of bold constitutional lurches.", "photo": "photos/souter.jpg"}, {"key": "thomas", "name": "Clarence Thomas", "meta": "George H. W. Bush appointee (R)", "blurb": "The Court's most uncompromising originalist, silent at argument and fearless in print. He would rather overrule a wrong precedent than trim it, and he stakes out positions no other justice will yet join.", "photo": "photos/thomas.jpg"}, {"key": "ginsburg", "name": "Ruth Bader Ginsburg", "meta": "Clinton appointee (D)", "blurb": "The ACLU litigator who dismantled sex-discrimination law brick by brick, now a precise, soft-spoken justice. A minimalist by temperament and a reliable liberal vote on questions of equal citizenship.", "photo": "photos/ginsburg.jpg"}, {"key": "breyer", "name": "Stephen Breyer", "meta": "Clinton appointee (D)", "blurb": "The junior justice, a Harvard administrative-law professor who thinks in workable purposes rather than absolutes. Pragmatic, optimistic about government, and forever spinning elaborate hypotheticals from the bench.", "photo": "photos/breyer.jpg"}], "votes": {"rehnquist": "yes", "stevens": "no", "oconnor": "yes", "scalia": "yes", "kennedy": "no", "souter": "no", "thomas": "yes", "ginsburg": "no", "breyer": "no"}}, {"id": "kennedy-v-bremerton", "era": "The Roberts Court \u00b7 October Term 2021", "caseTitle": "Kennedy v. Bremerton School District", "question": "Does the Constitution protect a public-school football coach's postgame prayer at midfield?", "desc": "Kennedy, a former Marine, began the prayers alone in 2008; they grew into huddles with players from both teams. Alerted by a visiting coach's complaint, the district offered him a private place to pray; he prayed at midfield instead, with news cameras and a state legislator looking on. The district put him on leave and let his contract lapse. He says the First Amendment protects a citizen's quiet prayer; the district says a coach on duty is the government speaking \u2014 and students felt they had to kneel.", "intro": "After each game, Bremerton High's assistant football coach Joseph Kennedy walks to the fifty-yard line, kneels, and prays. For years players joined him. When the Washington school district tells him to stop, he refuses, and loses his job.", "decided": "June 27, 2022", "split": "6\u20133", "answer": "yes", "justices": [{"key": "roberts", "name": "John Roberts", "meta": "George W. Bush appointee (R)", "blurb": "No longer the Court's median vote \u2014 a six-justice conservative majority can now rule without him. He still preaches minimalism and frets over the institution's standing, hunting for narrower paths that his colleagues increasingly decline to take.", "photo": "photos/roberts.jpg", "chief": true}, {"key": "thomas_roberts", "name": "Clarence Thomas", "meta": "George H. W. Bush appointee (R)", "blurb": "The Court's most uncompromising originalist, fearless in print: he will discard decades of precedent without apology and stake out positions entirely alone, serenely confident the law will someday catch up to him.", "photo": "photos/thomas_roberts.jpg"}, {"key": "breyer_roberts", "name": "Stephen Breyer", "meta": "Clinton appointee (D)", "blurb": "The Court's pragmatist professor: a former Senate staffer and administrative-law scholar who judges by consequences, not grand theory. Endlessly optimistic about government, allergic to absolutes, and famous for winding hypotheticals that leave lawyers blinking.", "photo": "photos/breyer_roberts.jpg"}, {"key": "alito", "name": "Samuel Alito", "meta": "George W. Bush appointee (R)", "blurb": "A former federal prosecutor from New Jersey, methodical and unflashy, with the most reliably conservative instincts on the bench \u2014 above all where crime, religion, or the culture wars are concerned. In dissent, his pen turns acid.", "photo": "photos/alito.jpg"}, {"key": "sotomayor", "name": "Sonia Sotomayor", "meta": "Obama appointee (D)", "blurb": "From a Bronx housing project to Princeton to the federal trial bench: the first Latina justice never lets the Court forget how doctrine lands on actual people. A former prosecutor, relentless at argument, the liberal wing's most passionate voice.", "photo": "photos/sotomayor.jpg"}, {"key": "kagan", "name": "Elena Kagan", "meta": "Obama appointee (D)", "blurb": "The former Harvard Law dean and solicitor general, a coalition-builder who learned her politics in the Clinton White House. The liberal wing's tactician: she writes in plain, wry English and plays a patient long game of her own.", "photo": "photos/kagan.jpg"}, {"key": "gorsuch", "name": "Neil Gorsuch", "meta": "Trump appointee (R)", "blurb": "Scalia's successor and a true-believing textualist from Colorado: read the words, then follow them off a cliff if necessary. A westerner with a libertarian streak, he votes his method wherever it leads \u2014 to either camp's occasional dismay.", "photo": "photos/gorsuch.jpg"}, {"key": "kavanaugh", "name": "Brett Kavanaugh", "meta": "Trump appointee (R)", "blurb": "Confirmed after the most explosive hearings in memory, the former Bush White House aide works at looking reassuringly conventional: a conservative who prizes stability, writes separately to narrow things, and courts the middle whenever there is one.", "photo": "photos/kavanaugh.jpg"}, {"key": "barrett", "name": "Amy Coney Barrett", "meta": "Trump appointee (R)", "blurb": "Scalia's former clerk and a Notre Dame law professor, elevated to the bench days before a presidential election. An academic originalist \u2014 careful, methodical, unshowy \u2014 still drawing her own map of where method and caution part ways.", "photo": "photos/barrett.jpg"}], "votes": {"roberts": "yes", "thomas_roberts": "yes", "breyer_roberts": "no", "alito": "yes", "sotomayor": "no", "kagan": "no", "gorsuch": "yes", "kavanaugh": "yes", "barrett": "yes"}}, {"id": "nixon-v-fitzgerald", "era": "The Burger Court \u00b7 October Term 1981", "caseTitle": "Nixon v. Fitzgerald", "question": "Is a former President immune from being sued for damages over his official acts in office?", "desc": "A. Ernest Fitzgerald testified in 1968 about runaway costs on the C-5A cargo plane; in 1970 his position was abolished. On the White House tapes Nixon can be heard saying to get rid of him, and at a 1973 press conference the President took responsibility before his staff retracted it. Nixon, out of office and pardoned, argues that a President who can be sued over every official decision cannot govern. Fitzgerald answers that no office in America places a man above the law. Nixon has already quietly paid him $142,000.", "intro": "An Air Force cost analyst told Congress the truth about a two-billion-dollar overrun, lost his job in a 'reorganization,' and sued the man he says ordered it: Richard Nixon.", "decided": "June 24, 1982", "split": "5\u20134", "answer": "yes", "justices": [{"key": "burger", "name": "Warren Burger", "meta": "Nixon appointee (R)", "blurb": "A dozen years into the center chair, the silver-maned Chief looks the part and guards the institution's dignity above all. Conservative on crime and schools, surprisingly pragmatic elsewhere, he assigns opinions with one eye on the headlines.", "photo": "photos/burger.jpg", "chief": true}, {"key": "brennan", "name": "William Brennan", "meta": "Eisenhower appointee (R)", "blurb": "A quarter-century in, the Warren Court's great playmaker now leads a liberal wing of two or three. He still hunts the center vote in every conference, and still lands a surprising number of them \u2014 his clerks call it the rule of five.", "photo": "photos/brennan.jpg"}, {"key": "white", "name": "Byron White", "meta": "Kennedy appointee (D)", "blurb": "JFK's last appointee has hardened into the Court's flintiest pragmatist \u2014 tough on crime, dismissive of rights he cannot find in the Constitution's text, still steady on race and equal protection.", "photo": "photos/white.jpg"}, {"key": "marshall", "name": "Thurgood Marshall", "meta": "Lyndon Johnson appointee (D)", "blurb": "The civil-rights giant in winter, increasingly isolated as the Court moves right. He and Brennan vote as a pair on the death penalty and much else, filing dissent after dissent for a future Court to find.", "photo": "photos/marshall.jpg"}, {"key": "blackmun", "name": "Harry Blackmun", "meta": "Nixon appointee (R)", "blurb": "The onetime 'Minnesota Twin' has completed a long migration: the shy Nixon appointee now votes more often with Brennan and Marshall than with the Chief he grew up beside \u2014 above all on privacy and equality.", "photo": "photos/blackmun.jpg"}, {"key": "powell", "name": "Lewis Powell", "meta": "Nixon appointee (R)", "blurb": "The Court's gentle fulcrum. The courtly Richmond lawyer decides the close ones \u2014 law clerks joke that the Constitution means whatever Lewis Powell thinks it means \u2014 balancing order against liberty with a counselor's caution.", "photo": "photos/powell.jpg"}, {"key": "rehnquist", "name": "William Rehnquist", "meta": "Nixon appointee (R)", "blurb": "The Court's anchor on the right, so fond of solo dissents that his clerks once gave him a Lone Ranger doll. Federalism, law enforcement, judicial restraint: his positions never wobble \u2014 and the Court, increasingly, comes to him.", "photo": "photos/rehnquist.jpg"}, {"key": "stevens", "name": "John Paul Stevens", "meta": "Ford appointee (R)", "blurb": "The bow-tied Chicagoan defies sorting \u2014 a Ford Republican drifting toward the Court's left flank, case by idiosyncratic case. He writes more separate opinions than anyone, trusting his own reading of the law over any bloc's.", "photo": "photos/stevens.jpg"}, {"key": "oconnor", "name": "Sandra Day O'Connor", "meta": "Reagan appointee (R)", "blurb": "The newest justice and the first woman to sit on the Court, a former Arizona legislative leader sworn in last fall. She judges like a lawmaker \u2014 narrow rulings, workable compromises, close attention to the facts \u2014 and no one yet knows where she lands.", "photo": "photos/oconnor.jpg"}], "votes": {"burger": "yes", "brennan": "no", "white": "no", "marshall": "no", "blackmun": "no", "powell": "yes", "rehnquist": "yes", "stevens": "yes", "oconnor": "yes"}}, {"id": "sherbert-v-verner", "era": "The Warren Court \u00b7 October Term 1962", "caseTitle": "Sherbert v. Verner", "question": "May a state deny unemployment benefits to a worker fired for refusing to work on her Sabbath?", "desc": "Fired for refusing Saturday shifts, Sherbert found every other mill in town on the same schedule and applied for unemployment compensation. The state commission ruled she had refused 'suitable work' without good cause; South Carolina's Sunday-closing laws, meanwhile, spare Sunday worshippers the same choice. Her lawyers call the denial a fine on her faith. The state answers that it forbids nothing \u2014 it simply declines to pay people who will not take the jobs on offer. The Free Exercise Clause has rarely been read to demand exemptions from neutral rules.", "intro": "Adell Sherbert ran a loom in a Spartanburg textile mill for 35 years. When the mill went to a six-day week, she would not work Saturdays \u2014 her Sabbath as a Seventh-day Adventist \u2014 and South Carolina says that makes her ineligible for benefits.", "decided": "June 17, 1963", "split": "7\u20132", "answer": "no", "justices": [{"key": "warren", "name": "Earl Warren", "meta": "Eisenhower appointee (R)", "blurb": "The former California governor, now the most consequential Chief Justice in a century. He asks lawyers one question \u2014 'But is it fair?' \u2014 and works the conference like the politician he never stopped being.", "photo": "photos/warren.jpg", "chief": true}, {"key": "black", "name": "Hugo Black", "meta": "Franklin Roosevelt appointee (D)", "blurb": "An Alabama New Dealer who carries the Constitution in his coat pocket and reads it literally. 'No law' means no law \u2014 but rights he cannot find in the text, he will not invent.", "photo": "photos/black.jpg"}, {"key": "douglas", "name": "William O. Douglas", "meta": "Franklin Roosevelt appointee (D)", "blurb": "A restless westerner and the Court's fastest pen \u2014 impatient with doctrine, indifferent to precedent, and instinctively on the side of the lone individual against the government in nearly any form it takes.", "photo": "photos/douglas.jpg"}, {"key": "clark", "name": "Tom C. Clark", "meta": "Truman appointee (D)", "blurb": "Truman's Attorney General in a trademark bow tie \u2014 the Court's law-and-order Texan. He backs the police and the prosecutor by instinct, but he ran federal law enforcement himself and knows its temptations from the inside.", "photo": "photos/clark.jpg"}, {"key": "harlan", "name": "John Marshall Harlan", "meta": "Eisenhower appointee (R)", "blurb": "The Wall Street patrician and grandson of a great dissenter \u2014 the Court's conservative conscience. He believes in ordered liberty and lawyerly process, and objects, elegantly, when the majority moves too far, too fast.", "photo": "photos/harlan.jpg"}, {"key": "brennan", "name": "William Brennan", "meta": "Eisenhower appointee (R)", "blurb": "The Court's Irish charmer and master coalition-builder, an Eisenhower appointee who turned out to be its most effective liberal. His first rule of the shop: with five votes, you can do anything.", "photo": "photos/brennan.jpg"}, {"key": "stewart", "name": "Potter Stewart", "meta": "Eisenhower appointee (R)", "blurb": "A moderate Ohio Republican who resists both blocs' grand theories. He decides cases one at a time, asks what the Constitution actually commands, and lands \u2014 unpredictably \u2014 somewhere in the middle.", "photo": "photos/stewart.jpg"}, {"key": "white", "name": "Byron White", "meta": "Kennedy appointee (D)", "blurb": "'Whizzer' White, the All-American halfback turned Kennedy's deputy attorney general \u2014 tough-minded, unsentimental, and skeptical of newly minted rights, especially the kind that make police work harder.", "photo": "photos/white.jpg"}, {"key": "goldberg", "name": "Arthur Goldberg", "meta": "Kennedy appointee (D)", "blurb": "Kennedy's labor secretary, new to the bench in Frankfurter's old seat and his opposite in every way: an exuberant liberal who believes the Constitution grows, and that the Court should help it along.", "photo": "photos/goldberg.jpg"}], "votes": {"warren": "no", "black": "no", "douglas": "no", "clark": "no", "harlan": "yes", "brennan": "no", "stewart": "no", "white": "yes", "goldberg": "no"}}, {"id": "united-states-v-rahimi", "era": "The Roberts Court \u00b7 October Term 2023", "caseTitle": "United States v. Rahimi", "question": "May the government disarm a person who is under a domestic-violence restraining order?", "desc": "A 1994 federal statute disarms anyone subject to a domestic-violence protective order. Rahimi, who also threatened to shoot his girlfriend if she told anyone about the assault, pleaded guilty \u2014 then the Fifth Circuit threw out his conviction under Bruen's new test, finding no founding-era law quite like it. Two years after Bruen, the Court must say how closely a modern gun law has to match history. The government points to old 'surety' and 'going armed' laws; Rahimi's lawyers say the founders never disarmed anyone on a civil court's say-so.", "intro": "Zackey Rahimi, under a Texas restraining order for assaulting his girlfriend, fires guns in five separate incidents in two months, including into the air at a Whataburger. Federal law bars him from having a gun at all. He says the Second Amendment disagrees.", "decided": "June 21, 2024", "split": "8\u20131", "answer": "yes", "justices": [{"key": "roberts", "name": "John Roberts", "meta": "George W. Bush appointee (R)", "blurb": "No longer the Court's median vote \u2014 a six-justice conservative majority can now rule without him. He still preaches minimalism and frets over the institution's standing, hunting for narrower paths that his colleagues increasingly decline to take.", "photo": "photos/roberts.jpg", "chief": true}, {"key": "thomas_roberts", "name": "Clarence Thomas", "meta": "George H. W. Bush appointee (R)", "blurb": "The Court's most uncompromising originalist, fearless in print: he will discard decades of precedent without apology and stake out positions entirely alone, serenely confident the law will someday catch up to him.", "photo": "photos/thomas_roberts.jpg"}, {"key": "alito", "name": "Samuel Alito", "meta": "George W. Bush appointee (R)", "blurb": "A former federal prosecutor from New Jersey, methodical and unflashy, with the most reliably conservative instincts on the bench \u2014 above all where crime, religion, or the culture wars are concerned. In dissent, his pen turns acid.", "photo": "photos/alito.jpg"}, {"key": "sotomayor", "name": "Sonia Sotomayor", "meta": "Obama appointee (D)", "blurb": "From a Bronx housing project to Princeton to the federal trial bench: the first Latina justice never lets the Court forget how doctrine lands on actual people. A former prosecutor, relentless at argument, the liberal wing's most passionate voice.", "photo": "photos/sotomayor.jpg"}, {"key": "kagan", "name": "Elena Kagan", "meta": "Obama appointee (D)", "blurb": "The former Harvard Law dean and solicitor general, a coalition-builder who learned her politics in the Clinton White House. The liberal wing's tactician: she writes in plain, wry English and plays a patient long game of her own.", "photo": "photos/kagan.jpg"}, {"key": "gorsuch", "name": "Neil Gorsuch", "meta": "Trump appointee (R)", "blurb": "Scalia's successor and a true-believing textualist from Colorado: read the words, then follow them off a cliff if necessary. A westerner with a libertarian streak, he votes his method wherever it leads \u2014 to either camp's occasional dismay.", "photo": "photos/gorsuch.jpg"}, {"key": "kavanaugh", "name": "Brett Kavanaugh", "meta": "Trump appointee (R)", "blurb": "Confirmed after the most explosive hearings in memory, the former Bush White House aide works at looking reassuringly conventional: a conservative who prizes stability, writes separately to narrow things, and courts the middle whenever there is one.", "photo": "photos/kavanaugh.jpg"}, {"key": "barrett", "name": "Amy Coney Barrett", "meta": "Trump appointee (R)", "blurb": "Scalia's former clerk and a Notre Dame law professor, elevated to the bench days before a presidential election. An academic originalist \u2014 careful, methodical, unshowy \u2014 still drawing her own map of where method and caution part ways.", "photo": "photos/barrett.jpg"}, {"key": "jackson", "name": "Ketanji Brown Jackson", "meta": "Biden appointee (D)", "blurb": "The first Black woman on the Court and its first former public defender. She brings a trial judge's practicality, a performer's timing at oral argument, and no apparent interest in waiting her turn to be heard.", "photo": "photos/jackson.jpg"}], "votes": {"roberts": "yes", "thomas_roberts": "no", "alito": "yes", "sotomayor": "yes", "kagan": "yes", "gorsuch": "yes", "kavanaugh": "yes", "barrett": "yes", "jackson": "yes"}}, {"id": "roper-v-simmons", "era": "The Rehnquist Court \u00b7 October Term 2004", "caseTitle": "Roper v. Simmons", "question": "May a state execute a murderer who was under eighteen at the time of the crime?", "desc": "Simmons planned the 1993 burglary and murder for weeks and assured accomplices they could 'get away with it' as minors; he confessed on videotape. In 1989 the Court upheld the death penalty for sixteen- and seventeen-year-olds. Since then \u2014 and after Atkins v. Virginia barred executing the mentally retarded \u2014 the Missouri Supreme Court declared a new national consensus and resentenced him to life. Thirty states now forbid juvenile executions; the United States is the last country still carrying them out. Psychologists argue the adolescent brain is unfinished.", "intro": "At seventeen, Christopher Simmons broke into a Missouri home with a friend, bound Shirley Crook with electrical wire and duct tape, and threw her from a railroad trestle. A jury sentenced him to death. Missouri's own supreme court has now set it aside.", "decided": "March 1, 2005", "split": "5\u20134", "answer": "no", "justices": [{"key": "rehnquist", "name": "William Rehnquist", "meta": "Nixon appointee (R)", "blurb": "Chief Justice for nearly two decades, a genial and ruthlessly efficient administrator with a lifelong project: reviving states' rights and reining in Washington. He has spent his whole career waiting for the votes he now has.", "photo": "photos/rehnquist.jpg", "chief": true}, {"key": "stevens", "name": "John Paul Stevens", "meta": "Ford appointee (R)", "blurb": "The senior associate justice, a bow-tied Ford appointee from Chicago who now marshals the Court's liberal wing. Fiercely independent in method, he assigns the dissents whenever the Chief is on the other side.", "photo": "photos/stevens.jpg"}, {"key": "oconnor", "name": "Sandra Day O'Connor", "meta": "Reagan appointee (R)", "blurb": "A former Arizona legislator and the Court's pivotal vote \u2014 by common consent the most powerful woman in America. She distrusts absolutes and decides case by case; where she lands is usually where the law lands.", "photo": "photos/oconnor.jpg"}, {"key": "scalia", "name": "Antonin Scalia", "meta": "Reagan appointee (R)", "blurb": "The Court's combative originalist, its funniest questioner and its fiercest dissenter. He wants clear rules drawn from text and history, and treats his colleagues' balancing tests as legislation in robes.", "photo": "photos/scalia.jpg"}, {"key": "kennedy", "name": "Anthony Kennedy", "meta": "Reagan appointee (R)", "blurb": "A courtly Sacramento Republican with a taste for sweeping language about liberty and dignity. Conservative by default but persuadable at the margins \u2014 one of the two votes every advocate in the courtroom is chasing.", "photo": "photos/kennedy.jpg"}, {"key": "souter", "name": "David Souter", "meta": "George H. W. Bush appointee (R)", "blurb": "The first President Bush's 'stealth nominee,' a frugal New Hampshire bachelor who confounded his sponsors by settling into the moderate-liberal wing. A common-law traditionalist, devoted to precedent and wary of bold constitutional lurches.", "photo": "photos/souter.jpg"}, {"key": "thomas", "name": "Clarence Thomas", "meta": "George H. W. Bush appointee (R)", "blurb": "The Court's most uncompromising originalist, silent at argument and fearless in print. He would rather overrule a wrong precedent than trim it, and he stakes out positions no other justice will yet join.", "photo": "photos/thomas.jpg"}, {"key": "ginsburg", "name": "Ruth Bader Ginsburg", "meta": "Clinton appointee (D)", "blurb": "The ACLU litigator who dismantled sex-discrimination law brick by brick, now a precise, soft-spoken justice. A minimalist by temperament and a reliable liberal vote on questions of equal citizenship.", "photo": "photos/ginsburg.jpg"}, {"key": "breyer", "name": "Stephen Breyer", "meta": "Clinton appointee (D)", "blurb": "The junior justice, a Harvard administrative-law professor who thinks in workable purposes rather than absolutes. Pragmatic, optimistic about government, and forever spinning elaborate hypotheticals from the bench.", "photo": "photos/breyer.jpg"}], "votes": {"rehnquist": "yes", "stevens": "no", "oconnor": "yes", "scalia": "yes", "kennedy": "no", "souter": "no", "thomas": "yes", "ginsburg": "no", "breyer": "no"}}, {"id": "rucho-v-common-cause", "era": "The Roberts Court \u00b7 October Term 2018", "caseTitle": "Rucho v. Common Cause", "question": "May federal courts strike down an election map as an unconstitutional partisan gerrymander?", "desc": "Representative David Lewis told the redistricting committee he proposed a 10\u20133 map 'because I do not believe it's possible to draw a map with 11 Republicans and 2 Democrats.' In Maryland, Governor O'Malley's team reshaped the Sixth District to flip it. Lower courts struck down both maps. Gerrymandering is as old as Elbridge Gerry, and the Court has never found a standard for judging it; computers now draw maps with surgical precision. Common Cause asks the justices to draw a line. The states ask them to admit there isn't one.", "intro": "North Carolina Republicans drew their congressional map to elect ten Republicans and three Democrats, and said so out loud. In Maryland, Democrats erased a Republican seat. Both maps arrive together, asking whether a gerrymander can go too far.", "decided": "June 27, 2019", "split": "5\u20134", "answer": "no", "justices": [{"key": "roberts", "name": "John Roberts", "meta": "George W. Bush appointee (R)", "blurb": "A dozen years in, the chief has become the Court's institutional conscience, insisting \u2014 especially in a polarized age \u2014 that it must not look like a political body. An incrementalist by temperament: he would rather decide little than decide loudly.", "photo": "photos/roberts.jpg", "chief": true}, {"key": "thomas_roberts", "name": "Clarence Thomas", "meta": "George H. W. Bush appointee (R)", "blurb": "The Court's most uncompromising originalist, fearless in print: he will discard decades of precedent without apology and stake out positions entirely alone, serenely confident the law will someday catch up to him.", "photo": "photos/thomas_roberts.jpg"}, {"key": "ginsburg_roberts", "name": "Ruth Bader Ginsburg", "meta": "Clinton appointee (D)", "blurb": "The pioneering women's-rights litigator of the 1970s, now the liberal wing's most exacting technician. Small, quiet, and precise, she picks her battles carefully \u2014 and reads her fiercest dissents aloud from the bench when she loses one.", "photo": "photos/ginsburg_roberts.jpg"}, {"key": "breyer_roberts", "name": "Stephen Breyer", "meta": "Clinton appointee (D)", "blurb": "The Court's pragmatist professor: a former Senate staffer and administrative-law scholar who judges by consequences, not grand theory. Endlessly optimistic about government, allergic to absolutes, and famous for winding hypotheticals that leave lawyers blinking.", "photo": "photos/breyer_roberts.jpg"}, {"key": "alito", "name": "Samuel Alito", "meta": "George W. Bush appointee (R)", "blurb": "A former federal prosecutor from New Jersey, methodical and unflashy, with the most reliably conservative instincts on the bench \u2014 above all where crime, religion, or the culture wars are concerned. In dissent, his pen turns acid.", "photo": "photos/alito.jpg"}, {"key": "sotomayor", "name": "Sonia Sotomayor", "meta": "Obama appointee (D)", "blurb": "From a Bronx housing project to Princeton to the federal trial bench: the first Latina justice never lets the Court forget how doctrine lands on actual people. A former prosecutor, relentless at argument, the liberal wing's most passionate voice.", "photo": "photos/sotomayor.jpg"}, {"key": "kagan", "name": "Elena Kagan", "meta": "Obama appointee (D)", "blurb": "The former Harvard Law dean and solicitor general, a coalition-builder who learned her politics in the Clinton White House. The liberal wing's tactician: she writes in plain, wry English and plays a patient long game of her own.", "photo": "photos/kagan.jpg"}, {"key": "gorsuch", "name": "Neil Gorsuch", "meta": "Trump appointee (R)", "blurb": "Scalia's successor and a true-believing textualist from Colorado: read the words, then follow them off a cliff if necessary. A westerner with a libertarian streak, he votes his method wherever it leads \u2014 to either camp's occasional dismay.", "photo": "photos/gorsuch.jpg"}, {"key": "kavanaugh", "name": "Brett Kavanaugh", "meta": "Trump appointee (R)", "blurb": "Confirmed after the most explosive hearings in memory, the former Bush White House aide works at looking reassuringly conventional: a conservative who prizes stability, writes separately to narrow things, and courts the middle whenever there is one.", "photo": "photos/kavanaugh.jpg"}], "votes": {"roberts": "no", "thomas_roberts": "no", "ginsburg_roberts": "yes", "breyer_roberts": "yes", "alito": "no", "sotomayor": "yes", "kagan": "yes", "gorsuch": "no", "kavanaugh": "no"}}, {"id": "heart-of-atlanta-motel", "era": "The Warren Court \u00b7 October Term 1964", "caseTitle": "Heart of Atlanta Motel v. United States", "question": "May Congress use its power over interstate commerce to forbid a motel from turning away Black guests?", "desc": "Moreton Rolleston Jr., the lawyer who owns the motel, argues his own case: Congress may regulate commerce, not morality, and forcing him to rent rooms is involuntary servitude. The Justice Department, wary of the Fourteenth Amendment since the Civil Rights Cases of 1883 gutted it, hangs Title II on the Commerce Clause instead \u2014 three-quarters of the motel's guests come from out of state, and segregation, it argues, chokes the national travel economy. A companion case asks the same about Ollie's Barbecue in Birmingham, which serves almost no travelers.", "intro": "Hours after President Johnson signed the Civil Rights Act of 1964, the owner of a 216-room motel beside the interstate in downtown Atlanta filed suit to keep refusing Black travelers. By December the Act's fate is before the Court.", "decided": "December 14, 1964", "split": "9\u20130", "answer": "yes", "justices": [{"key": "warren", "name": "Earl Warren", "meta": "Eisenhower appointee (R)", "blurb": "The former California governor, now the most consequential Chief Justice in a century. He asks lawyers one question \u2014 'But is it fair?' \u2014 and works the conference like the politician he never stopped being.", "photo": "photos/warren.jpg", "chief": true}, {"key": "black", "name": "Hugo Black", "meta": "Franklin Roosevelt appointee (D)", "blurb": "An Alabama New Dealer who carries the Constitution in his coat pocket and reads it literally. 'No law' means no law \u2014 but rights he cannot find in the text, he will not invent.", "photo": "photos/black.jpg"}, {"key": "douglas", "name": "William O. Douglas", "meta": "Franklin Roosevelt appointee (D)", "blurb": "A restless westerner and the Court's fastest pen \u2014 impatient with doctrine, indifferent to precedent, and instinctively on the side of the lone individual against the government in nearly any form it takes.", "photo": "photos/douglas.jpg"}, {"key": "clark", "name": "Tom C. Clark", "meta": "Truman appointee (D)", "blurb": "Truman's Attorney General in a trademark bow tie \u2014 the Court's law-and-order Texan. He backs the police and the prosecutor by instinct, but he ran federal law enforcement himself and knows its temptations from the inside.", "photo": "photos/clark.jpg"}, {"key": "harlan", "name": "John Marshall Harlan", "meta": "Eisenhower appointee (R)", "blurb": "The Wall Street patrician and grandson of a great dissenter \u2014 the Court's conservative conscience. He believes in ordered liberty and lawyerly process, and objects, elegantly, when the majority moves too far, too fast.", "photo": "photos/harlan.jpg"}, {"key": "brennan", "name": "William Brennan", "meta": "Eisenhower appointee (R)", "blurb": "The Court's Irish charmer and master coalition-builder, an Eisenhower appointee who turned out to be its most effective liberal. His first rule of the shop: with five votes, you can do anything.", "photo": "photos/brennan.jpg"}, {"key": "stewart", "name": "Potter Stewart", "meta": "Eisenhower appointee (R)", "blurb": "A moderate Ohio Republican who resists both blocs' grand theories. He decides cases one at a time, asks what the Constitution actually commands, and lands \u2014 unpredictably \u2014 somewhere in the middle.", "photo": "photos/stewart.jpg"}, {"key": "white", "name": "Byron White", "meta": "Kennedy appointee (D)", "blurb": "'Whizzer' White, the All-American halfback turned Kennedy's deputy attorney general \u2014 tough-minded, unsentimental, and skeptical of newly minted rights, especially the kind that make police work harder.", "photo": "photos/white.jpg"}, {"key": "goldberg", "name": "Arthur Goldberg", "meta": "Kennedy appointee (D)", "blurb": "Kennedy's labor secretary, new to the bench in Frankfurter's old seat and his opposite in every way: an exuberant liberal who believes the Constitution grows, and that the Court should help it along.", "photo": "photos/goldberg.jpg"}], "votes": {"warren": "yes", "black": "yes", "douglas": "yes", "clark": "yes", "harlan": "yes", "brennan": "yes", "stewart": "yes", "white": "yes", "goldberg": "yes"}}, {"id": "hustler-v-falwell", "era": "The Rehnquist Court \u00b7 October Term 1987", "caseTitle": "Hustler Magazine v. Falwell", "question": "May a public figure collect damages for emotional distress caused by an offensive parody that no reader would take as fact?", "desc": "The November 1983 issue of Hustler ran a mock advertisement, labeled in small print 'ad parody \u2014 not to be taken seriously,' in which Falwell describes a drunken encounter with his mother in an outhouse. The jury rejected his libel claim \u2014 no one could believe it was true \u2014 but awarded $200,000 for intentional infliction of emotional distress. Flynt, the pornographer, and Falwell, the televangelist, loathe each other in public. Political cartoonists from Thomas Nast forward are invoked on one side; common decency on the other.", "intro": "A Campari-ad parody in Hustler magazine depicts the Rev. Jerry Falwell, founder of the Moral Majority, recalling a drunken first time with his mother in an outhouse. Falwell sues Larry Flynt. A Virginia jury has already awarded him $200,000.", "decided": "February 24, 1988", "split": "8\u20130", "answer": "no", "justices": [{"key": "rehnquist88", "name": "William Rehnquist", "meta": "Nixon appointee (R)", "blurb": "Two terms into the chief justiceship after fifteen years as the Court's lone-wolf conservative dissenter \u2014 a genial, poker-playing states'-rights man who now assigns the opinions and is learning to hold majorities rather than write dissents.", "photo": "photos/rehnquist88.jpg", "chief": true}, {"key": "brennan", "name": "William Brennan", "meta": "Eisenhower appointee (R)", "blurb": "The architect of the Warren Court's rights revolution, now 81 and the senior associate justice. Still the Court's great coalition-builder \u2014 'five votes can do anything around here' \u2014 and with Powell gone, counting harder than ever.", "photo": "photos/brennan.jpg"}, {"key": "white", "name": "Byron White", "meta": "Kennedy appointee (D)", "blurb": "A Kennedy appointee and former NFL halfback, gruff and unsentimental. Hard on criminal defendants, skeptical of newly minted rights, steady on civil rights \u2014 he defies every label, writes short opinions, and asks no one's permission.", "photo": "photos/white.jpg"}, {"key": "marshall", "name": "Thurgood Marshall", "meta": "Lyndon Johnson appointee (D)", "blurb": "The lawyer who won Brown v. Board of Education, now the Court's most unwavering liberal. He votes against every death sentence and speaks for the poor and powerless \u2014 increasingly in dissent, shoulder to shoulder with Brennan.", "photo": "photos/marshall.jpg"}, {"key": "blackmun", "name": "Harry Blackmun", "meta": "Nixon appointee (R)", "blurb": "The Nixon appointee who wrote Roe v. Wade and has drifted left ever since, marked by the backlash. A meticulous former counsel to the Mayo Clinic, sensitive and deliberate, usually found alongside Brennan and Marshall.", "photo": "photos/blackmun.jpg"}, {"key": "stevens88", "name": "John Paul Stevens", "meta": "Ford appointee (R)", "blurb": "A Ford appointee and Chicago antitrust lawyer with a bow tie and a ferociously independent streak. He follows his own analysis wherever it leads and scatters solo opinions along the way \u2014 beholden to no bloc.", "photo": "photos/stevens88.jpg"}, {"key": "oconnor88", "name": "Sandra Day O'Connor", "meta": "Reagan appointee (R)", "blurb": "The first woman on the Court, a former Arizona legislative leader who judges the way she once governed: case by case, fact by fact, wary of sweeping rules. With Powell retired, she is the Court's center of gravity.", "photo": "photos/oconnor88.jpg"}, {"key": "scalia88", "name": "Antonin Scalia", "meta": "Reagan appointee (R)", "blurb": "Reagan's combative textualist, in only his second term and already the Court's sharpest pen. He reads constitutional text at face value wherever it points \u2014 and delights in skewering colleagues who balance interests instead.", "photo": "photos/scalia88.jpg"}], "votes": {"rehnquist88": "no", "brennan": "no", "white": "no", "marshall": "no", "blackmun": "no", "stevens88": "no", "oconnor88": "no", "scalia88": "no"}}, {"id": "biden-v-nebraska", "era": "The Roberts Court \u00b7 October Term 2022", "caseTitle": "Biden v. Nebraska", "question": "May the Education Secretary cancel hundreds of billions of dollars in student debt under the HEROES Act's power to 'waive or modify' aid rules?", "desc": "The HEROES Act of 2003 lets the Education Secretary 'waive or modify' student-aid rules in a national emergency; the administration says the pandemic is one and that cancellation keeps borrowers from default. Missouri's loan-servicing agency, MOHELA, would lose fees, giving the states a path into court. They argue that no Congress wrote a $430 billion giveaway into a wartime waiver, and that a decision this big belongs to legislators. Borrowers have applied in the millions; the forgiveness is frozen pending the Court's answer.", "intro": "President Biden announces up to $20,000 in student-loan forgiveness for 43 million borrowers, invoking a post-9/11 law written for soldiers at war. Six Republican-led states sue. The price tag is about $430 billion.", "decided": "June 30, 2023", "split": "6\u20133", "answer": "no", "justices": [{"key": "roberts", "name": "John Roberts", "meta": "George W. Bush appointee (R)", "blurb": "No longer the Court's median vote \u2014 a six-justice conservative majority can now rule without him. He still preaches minimalism and frets over the institution's standing, hunting for narrower paths that his colleagues increasingly decline to take.", "photo": "photos/roberts.jpg", "chief": true}, {"key": "thomas_roberts", "name": "Clarence Thomas", "meta": "George H. W. Bush appointee (R)", "blurb": "The Court's most uncompromising originalist, fearless in print: he will discard decades of precedent without apology and stake out positions entirely alone, serenely confident the law will someday catch up to him.", "photo": "photos/thomas_roberts.jpg"}, {"key": "alito", "name": "Samuel Alito", "meta": "George W. Bush appointee (R)", "blurb": "A former federal prosecutor from New Jersey, methodical and unflashy, with the most reliably conservative instincts on the bench \u2014 above all where crime, religion, or the culture wars are concerned. In dissent, his pen turns acid.", "photo": "photos/alito.jpg"}, {"key": "sotomayor", "name": "Sonia Sotomayor", "meta": "Obama appointee (D)", "blurb": "From a Bronx housing project to Princeton to the federal trial bench: the first Latina justice never lets the Court forget how doctrine lands on actual people. A former prosecutor, relentless at argument, the liberal wing's most passionate voice.", "photo": "photos/sotomayor.jpg"}, {"key": "kagan", "name": "Elena Kagan", "meta": "Obama appointee (D)", "blurb": "The former Harvard Law dean and solicitor general, a coalition-builder who learned her politics in the Clinton White House. The liberal wing's tactician: she writes in plain, wry English and plays a patient long game of her own.", "photo": "photos/kagan.jpg"}, {"key": "gorsuch", "name": "Neil Gorsuch", "meta": "Trump appointee (R)", "blurb": "Scalia's successor and a true-believing textualist from Colorado: read the words, then follow them off a cliff if necessary. A westerner with a libertarian streak, he votes his method wherever it leads \u2014 to either camp's occasional dismay.", "photo": "photos/gorsuch.jpg"}, {"key": "kavanaugh", "name": "Brett Kavanaugh", "meta": "Trump appointee (R)", "blurb": "Confirmed after the most explosive hearings in memory, the former Bush White House aide works at looking reassuringly conventional: a conservative who prizes stability, writes separately to narrow things, and courts the middle whenever there is one.", "photo": "photos/kavanaugh.jpg"}, {"key": "barrett", "name": "Amy Coney Barrett", "meta": "Trump appointee (R)", "blurb": "Scalia's former clerk and a Notre Dame law professor, elevated to the bench days before a presidential election. An academic originalist \u2014 careful, methodical, unshowy \u2014 still drawing her own map of where method and caution part ways.", "photo": "photos/barrett.jpg"}, {"key": "jackson", "name": "Ketanji Brown Jackson", "meta": "Biden appointee (D)", "blurb": "The first Black woman on the Court and its first former public defender. She brings a trial judge's practicality, a performer's timing at oral argument, and no apparent interest in waiting her turn to be heard.", "photo": "photos/jackson.jpg"}], "votes": {"roberts": "no", "thomas_roberts": "no", "alito": "no", "sotomayor": "yes", "kagan": "yes", "gorsuch": "no", "kavanaugh": "no", "barrett": "no", "jackson": "yes"}}, {"id": "united-states-v-leon", "era": "The Burger Court \u00b7 October Term 1983", "caseTitle": "United States v. Leon", "question": "May evidence seized under a search warrant later found defective still be used at trial if the police relied on the warrant in good faith?", "desc": "Alberto Leon and his partners ran a trafficking operation that officers tracked through surveillance and an informant of unproven reliability. A magistrate signed the warrant; a district judge found the affidavit fell short of probable cause and threw out the drugs. Since Mapp v. Ohio, evidence taken in violation of the Fourth Amendment has been barred from every trial. The Justice Department argues that suppression punishes nobody when the police did everything right; defense lawyers answer that a 'good faith' exception would make the warrant requirement a formality.", "intro": "Burbank police watch a house for months, write up a warrant, and seize a drug dealer's cocaine. A judge later decides the warrant should never have issued \u2014 and the exclusionary rule faces its sharpest test in twenty years.", "decided": "July 5, 1984", "split": "6\u20133", "answer": "yes", "justices": [{"key": "burger", "name": "Warren Burger", "meta": "Nixon appointee (R)", "blurb": "Seventeen years into the center chair, as much administrator as judge \u2014 obsessed with judicial efficiency and courtroom decorum. Reliably conservative on crime and social questions, though colleagues grumble that his opinion assignments follow strategy more than principle.", "photo": "photos/burger.jpg", "chief": true}, {"key": "brennan", "name": "William Brennan", "meta": "Eisenhower appointee (R)", "blurb": "The aging captain of the Court's shrinking liberal wing, three decades in. He can still conjure a majority from thin air on a good day \u2014 but these days he is more often assigning dissents than opinions.", "photo": "photos/brennan.jpg"}, {"key": "white", "name": "Byron White", "meta": "Kennedy appointee (D)", "blurb": "JFK's last appointee has hardened into the Court's flintiest pragmatist \u2014 tough on crime, dismissive of rights he cannot find in the Constitution's text, still steady on race and equal protection.", "photo": "photos/white.jpg"}, {"key": "marshall", "name": "Thurgood Marshall", "meta": "Lyndon Johnson appointee (D)", "blurb": "The civil-rights giant in winter, increasingly isolated as the Court moves right. He and Brennan vote as a pair on the death penalty and much else, filing dissent after dissent for a future Court to find.", "photo": "photos/marshall.jpg"}, {"key": "blackmun", "name": "Harry Blackmun", "meta": "Nixon appointee (R)", "blurb": "The onetime 'Minnesota Twin' has completed a long migration: the shy Nixon appointee now votes more often with Brennan and Marshall than with the Chief he grew up beside \u2014 above all on privacy and equality.", "photo": "photos/blackmun.jpg"}, {"key": "powell", "name": "Lewis Powell", "meta": "Nixon appointee (R)", "blurb": "The Court's gentle fulcrum. The courtly Richmond lawyer decides the close ones \u2014 law clerks joke that the Constitution means whatever Lewis Powell thinks it means \u2014 balancing order against liberty with a counselor's caution.", "photo": "photos/powell.jpg"}, {"key": "rehnquist", "name": "William Rehnquist", "meta": "Nixon appointee (R)", "blurb": "The Court's anchor on the right, so fond of solo dissents that his clerks once gave him a Lone Ranger doll. Federalism, law enforcement, judicial restraint: his positions never wobble \u2014 and the Court, increasingly, comes to him.", "photo": "photos/rehnquist.jpg"}, {"key": "stevens", "name": "John Paul Stevens", "meta": "Ford appointee (R)", "blurb": "The bow-tied Chicagoan defies sorting \u2014 a Ford Republican drifting toward the Court's left flank, case by idiosyncratic case. He writes more separate opinions than anyone, trusting his own reading of the law over any bloc's.", "photo": "photos/stevens.jpg"}, {"key": "oconnor", "name": "Sandra Day O'Connor", "meta": "Reagan appointee (R)", "blurb": "The first woman on the Court, a former Arizona legislative leader who judges like a lawmaker \u2014 narrow rulings, workable compromises, close attention to the facts. Reliably conservative on crime; harder to predict everywhere else.", "photo": "photos/oconnor.jpg"}], "votes": {"burger": "yes", "brennan": "no", "white": "yes", "marshall": "no", "blackmun": "yes", "powell": "yes", "rehnquist": "yes", "stevens": "no", "oconnor": "yes"}}, {"id": "katz-v-united-states", "era": "The Warren Court \u00b7 October Term 1967", "caseTitle": "Katz v. United States", "question": "Does the Fourth Amendment require a warrant before federal agents bug a public telephone booth?", "desc": "The recordings convicted Katz of transmitting wagering information across state lines. Since Olmstead in 1928 the rule has been physical: no trespass, no search, so a tap that touches no property is outside the Fourth Amendment entirely. The government argues that a booth is public and its glass walls let anyone see in. Katz's lawyers answer that what he paid for when he shut the door was not invisibility but privacy \u2014 and that the Amendment protects people, not places. Electronic surveillance has arrived; has the Constitution?", "intro": "Charles Katz, a Los Angeles bookmaker, placed his bets from a glass phone booth on Sunset Boulevard. The FBI never entered it: agents taped a microphone to its roof and recorded him from outside.", "decided": "December 18, 1967", "split": "7\u20131", "answer": "yes", "justices": [{"key": "warren", "name": "Earl Warren", "meta": "Eisenhower appointee (R)", "blurb": "The former California governor, now the most consequential Chief Justice in a century. He asks lawyers one question \u2014 'But is it fair?' \u2014 and works the conference like the politician he never stopped being.", "photo": "photos/warren.jpg", "chief": true}, {"key": "black", "name": "Hugo Black", "meta": "Franklin Roosevelt appointee (D)", "blurb": "An Alabama New Dealer who carries the Constitution in his coat pocket and reads it literally. 'No law' means no law \u2014 but rights he cannot find in the text, he will not invent.", "photo": "photos/black.jpg"}, {"key": "douglas", "name": "William O. Douglas", "meta": "Franklin Roosevelt appointee (D)", "blurb": "A restless westerner and the Court's fastest pen \u2014 impatient with doctrine, indifferent to precedent, and instinctively on the side of the lone individual against the government in nearly any form it takes.", "photo": "photos/douglas.jpg"}, {"key": "harlan", "name": "John Marshall Harlan", "meta": "Eisenhower appointee (R)", "blurb": "The Wall Street patrician and grandson of a great dissenter \u2014 the Court's conservative conscience. He believes in ordered liberty and lawyerly process, and objects, elegantly, when the majority moves too far, too fast.", "photo": "photos/harlan.jpg"}, {"key": "brennan", "name": "William Brennan", "meta": "Eisenhower appointee (R)", "blurb": "The Court's Irish charmer and master coalition-builder, an Eisenhower appointee who turned out to be its most effective liberal. His first rule of the shop: with five votes, you can do anything.", "photo": "photos/brennan.jpg"}, {"key": "stewart", "name": "Potter Stewart", "meta": "Eisenhower appointee (R)", "blurb": "A moderate Ohio Republican who resists both blocs' grand theories. He decides cases one at a time, asks what the Constitution actually commands, and lands \u2014 unpredictably \u2014 somewhere in the middle.", "photo": "photos/stewart.jpg"}, {"key": "white", "name": "Byron White", "meta": "Kennedy appointee (D)", "blurb": "'Whizzer' White, the All-American halfback turned Kennedy's deputy attorney general \u2014 tough-minded, unsentimental, and skeptical of newly minted rights, especially the kind that make police work harder.", "photo": "photos/white.jpg"}, {"key": "fortas", "name": "Abe Fortas", "meta": "Lyndon Johnson appointee (D)", "blurb": "LBJ's confidant and Washington's premier lawyer, still quietly advising the President from the bench. As an advocate he won poor defendants their counsel; as a justice he champions the underdog \u2014 children included.", "photo": "photos/fortas.jpg"}], "votes": {"warren": "yes", "black": "no", "douglas": "yes", "harlan": "yes", "brennan": "yes", "stewart": "yes", "white": "yes", "fortas": "yes"}}, {"id": "tennessee-v-garner", "era": "The Burger Court \u00b7 October Term 1984", "caseTitle": "Tennessee v. Garner", "question": "May police shoot a fleeing, unarmed burglary suspect simply to prevent his escape?", "desc": "Edward Garner was slight, unarmed and, the officer later admitted, almost certainly not dangerous; Tennessee law allowed 'all the necessary means' to stop a fleeing felon, a rule inherited from the common law, when every felony was a hanging offense. Garner's father sued the city and the officer. Half the states still permit deadly force against any fleeing felon; police departments say officers cannot be asked to let suspects run. The question is whether the Fourth Amendment's bar on unreasonable seizures governs the most final seizure of all.", "intro": "Memphis, an October night in 1974. A fifteen-year-old with ten dollars and a stolen purse scrambles over a backyard fence, and a police officer shoots him in the back of the head.", "decided": "March 27, 1985", "split": "6\u20133", "answer": "no", "justices": [{"key": "burger", "name": "Warren Burger", "meta": "Nixon appointee (R)", "blurb": "Seventeen years into the center chair, as much administrator as judge \u2014 obsessed with judicial efficiency and courtroom decorum. Reliably conservative on crime and social questions, though colleagues grumble that his opinion assignments follow strategy more than principle.", "photo": "photos/burger.jpg", "chief": true}, {"key": "brennan", "name": "William Brennan", "meta": "Eisenhower appointee (R)", "blurb": "The aging captain of the Court's shrinking liberal wing, three decades in. He can still conjure a majority from thin air on a good day \u2014 but these days he is more often assigning dissents than opinions.", "photo": "photos/brennan.jpg"}, {"key": "white", "name": "Byron White", "meta": "Kennedy appointee (D)", "blurb": "JFK's last appointee has hardened into the Court's flintiest pragmatist \u2014 tough on crime, dismissive of rights he cannot find in the Constitution's text, still steady on race and equal protection.", "photo": "photos/white.jpg"}, {"key": "marshall", "name": "Thurgood Marshall", "meta": "Lyndon Johnson appointee (D)", "blurb": "The civil-rights giant in winter, increasingly isolated as the Court moves right. He and Brennan vote as a pair on the death penalty and much else, filing dissent after dissent for a future Court to find.", "photo": "photos/marshall.jpg"}, {"key": "blackmun", "name": "Harry Blackmun", "meta": "Nixon appointee (R)", "blurb": "The onetime 'Minnesota Twin' has completed a long migration: the shy Nixon appointee now votes more often with Brennan and Marshall than with the Chief he grew up beside \u2014 above all on privacy and equality.", "photo": "photos/blackmun.jpg"}, {"key": "powell", "name": "Lewis Powell", "meta": "Nixon appointee (R)", "blurb": "The Court's gentle fulcrum. The courtly Richmond lawyer decides the close ones \u2014 law clerks joke that the Constitution means whatever Lewis Powell thinks it means \u2014 balancing order against liberty with a counselor's caution.", "photo": "photos/powell.jpg"}, {"key": "rehnquist", "name": "William Rehnquist", "meta": "Nixon appointee (R)", "blurb": "The Court's anchor on the right, so fond of solo dissents that his clerks once gave him a Lone Ranger doll. Federalism, law enforcement, judicial restraint: his positions never wobble \u2014 and the Court, increasingly, comes to him.", "photo": "photos/rehnquist.jpg"}, {"key": "stevens", "name": "John Paul Stevens", "meta": "Ford appointee (R)", "blurb": "The bow-tied Chicagoan defies sorting \u2014 a Ford Republican drifting toward the Court's left flank, case by idiosyncratic case. He writes more separate opinions than anyone, trusting his own reading of the law over any bloc's.", "photo": "photos/stevens.jpg"}, {"key": "oconnor", "name": "Sandra Day O'Connor", "meta": "Reagan appointee (R)", "blurb": "The first woman on the Court, a former Arizona legislative leader who judges like a lawmaker \u2014 narrow rulings, workable compromises, close attention to the facts. Reliably conservative on crime; harder to predict everywhere else.", "photo": "photos/oconnor.jpg"}], "votes": {"burger": "yes", "brennan": "no", "white": "no", "marshall": "no", "blackmun": "no", "powell": "no", "rehnquist": "yes", "stevens": "no", "oconnor": "yes"}}, {"id": "reynolds-v-sims", "era": "The Warren Court \u00b7 October Term 1963", "caseTitle": "Reynolds v. Sims", "question": "Must both houses of a state legislature be apportioned on the basis of population?", "desc": "Alabama's constitution requires reapportionment every ten years; the legislature has ignored it for sixty. Voters in Birmingham and Mobile sued, and a federal court found the map flagrant. The states reply with the federal analogy: the U.S. Senate gives Wyoming and New York two seats apiece, so why may a state not apportion one house by county? Cases from New York, Maryland, Virginia, Delaware and Colorado \u2014 where voters approved their unequal senate by referendum \u2014 are argued alongside. Whatever rule emerges will redraw most statehouses in America.", "intro": "Two years after Baker v. Carr opened the courthouse door, six states' legislatures arrive at once. Alabama's map dates from 1900: Jefferson County, with 600,000 people, has one senator \u2014 the same as a county of 15,000.", "decided": "June 15, 1964", "split": "8\u20131", "answer": "yes", "justices": [{"key": "warren", "name": "Earl Warren", "meta": "Eisenhower appointee (R)", "blurb": "The former California governor, now the most consequential Chief Justice in a century. He asks lawyers one question \u2014 'But is it fair?' \u2014 and works the conference like the politician he never stopped being.", "photo": "photos/warren.jpg", "chief": true}, {"key": "black", "name": "Hugo Black", "meta": "Franklin Roosevelt appointee (D)", "blurb": "An Alabama New Dealer who carries the Constitution in his coat pocket and reads it literally. 'No law' means no law \u2014 but rights he cannot find in the text, he will not invent.", "photo": "photos/black.jpg"}, {"key": "douglas", "name": "William O. Douglas", "meta": "Franklin Roosevelt appointee (D)", "blurb": "A restless westerner and the Court's fastest pen \u2014 impatient with doctrine, indifferent to precedent, and instinctively on the side of the lone individual against the government in nearly any form it takes.", "photo": "photos/douglas.jpg"}, {"key": "clark", "name": "Tom C. Clark", "meta": "Truman appointee (D)", "blurb": "Truman's Attorney General in a trademark bow tie \u2014 the Court's law-and-order Texan. He backs the police and the prosecutor by instinct, but he ran federal law enforcement himself and knows its temptations from the inside.", "photo": "photos/clark.jpg"}, {"key": "harlan", "name": "John Marshall Harlan", "meta": "Eisenhower appointee (R)", "blurb": "The Wall Street patrician and grandson of a great dissenter \u2014 the Court's conservative conscience. He believes in ordered liberty and lawyerly process, and objects, elegantly, when the majority moves too far, too fast.", "photo": "photos/harlan.jpg"}, {"key": "brennan", "name": "William Brennan", "meta": "Eisenhower appointee (R)", "blurb": "The Court's Irish charmer and master coalition-builder, an Eisenhower appointee who turned out to be its most effective liberal. His first rule of the shop: with five votes, you can do anything.", "photo": "photos/brennan.jpg"}, {"key": "stewart", "name": "Potter Stewart", "meta": "Eisenhower appointee (R)", "blurb": "A moderate Ohio Republican who resists both blocs' grand theories. He decides cases one at a time, asks what the Constitution actually commands, and lands \u2014 unpredictably \u2014 somewhere in the middle.", "photo": "photos/stewart.jpg"}, {"key": "white", "name": "Byron White", "meta": "Kennedy appointee (D)", "blurb": "'Whizzer' White, the All-American halfback turned Kennedy's deputy attorney general \u2014 tough-minded, unsentimental, and skeptical of newly minted rights, especially the kind that make police work harder.", "photo": "photos/white.jpg"}, {"key": "goldberg", "name": "Arthur Goldberg", "meta": "Kennedy appointee (D)", "blurb": "Kennedy's labor secretary, new to the bench in Frankfurter's old seat and his opposite in every way: an exuberant liberal who believes the Constitution grows, and that the Court should help it along.", "photo": "photos/goldberg.jpg"}], "votes": {"warren": "yes", "black": "yes", "douglas": "yes", "clark": "yes", "harlan": "no", "brennan": "yes", "stewart": "yes", "white": "yes", "goldberg": "yes"}}, {"id": "swann-v-charlotte-mecklenburg", "era": "The Burger Court \u00b7 October Term 1970", "caseTitle": "Swann v. Charlotte-Mecklenburg Board of Education", "question": "May a federal judge order a city to bus schoolchildren across town to desegregate its schools?", "desc": "Charlotte-Mecklenburg runs 84,000 pupils through a single countywide system, and most of its Black children still attend schools that are all but entirely Black. Judge James McMillan, a local Presbyterian elder, has ordered pairing of inner-city and suburban schools and daily busing to make every school's enrollment resemble the county's \u2014 then received death threats and seen his effigy burned. The school board says Brown required only an end to assignment by race, not racial balance. The Nixon administration, campaigning against 'forced busing,' sides with the board.", "intro": "Charlotte, North Carolina. Seventeen years after Brown, a federal judge has ordered the South's model school system to bus thousands of children out of their neighborhoods \u2014 and the city is in an uproar.", "decided": "April 20, 1971", "split": "9\u20130", "answer": "yes", "justices": [{"key": "burger", "name": "Warren Burger", "meta": "Nixon appointee (R)", "blurb": "Nixon's chief justice, installed to steady a Court he believes ran wild under Earl Warren. A stickler for order and the dignity of institutions, he is more cautious conservative than crusader \u2014 and ever mindful of the Court's public standing.", "photo": "photos/burger.jpg", "chief": true}, {"key": "black", "name": "Hugo Black", "meta": "Franklin Roosevelt appointee (D)", "blurb": "At 85, the New Deal's last titan and the First Amendment's fiercest literalist \u2014 'no law abridging' means no law, period. Frail and near the end of 34 years on the bench, he still writes with the old fire.", "photo": "photos/black.jpg"}, {"key": "douglas", "name": "William O. Douglas", "meta": "Franklin Roosevelt appointee (D)", "blurb": "A New Deal wunderkind grown into the Court's absolutist loner \u2014 three decades on the bench, four wives, a shelf of his own books. He votes for the individual against the government almost reflexively, and writes opinions at breakneck speed.", "photo": "photos/douglas.jpg"}, {"key": "harlan", "name": "John Marshall Harlan", "meta": "Eisenhower appointee (R)", "blurb": "The Court's patrician conservative conscience, a lawyer's lawyer of precision and restraint. Nearly blind, he reads briefs held an inch from his eyes \u2014 and insists that judging is a matter of process and precedent, never passion.", "photo": "photos/harlan.jpg"}, {"key": "brennan", "name": "William Brennan", "meta": "Eisenhower appointee (R)", "blurb": "The Warren Court's master coalition-builder, an Eisenhower appointee turned architect of its liberal revolution. His first rule \u2014 with five votes you can do anything \u2014 still guides him as the bench tilts rightward around him.", "photo": "photos/brennan.jpg"}, {"key": "stewart", "name": "Potter Stewart", "meta": "Eisenhower appointee (R)", "blurb": "A pragmatic Ohio Republican wary of grand theory, he decides cases narrowly and one at a time. Neither wing can count on him: he distrusts government overreach and judicial adventure in roughly equal measure.", "photo": "photos/stewart.jpg"}, {"key": "white", "name": "Byron White", "meta": "Kennedy appointee (D)", "blurb": "The Kennedys' deputy attorney general, an All-America halfback turned no-nonsense pragmatist. Tough on crime and skeptical of newly minted rights, yet often found with the liberals on race and civil rights.", "photo": "photos/white.jpg"}, {"key": "marshall", "name": "Thurgood Marshall", "meta": "Lyndon Johnson appointee (D)", "blurb": "The architect of Brown v. Board and the Court's first Black justice. He judges from lived experience \u2014 Jim Crow courtrooms, clients facing the electric chair \u2014 and defends the poor and powerless with unembarrassed consistency.", "photo": "photos/marshall.jpg"}, {"key": "blackmun", "name": "Harry Blackmun", "meta": "Nixon appointee (R)", "blurb": "The junior justice, a shy Minnesota Republican and longtime counsel to the Mayo Clinic. Washington calls him and his boyhood friend the Chief the 'Minnesota Twins' \u2014 so far he votes Burger's way more often than not.", "photo": "photos/blackmun.jpg"}], "votes": {"burger": "yes", "black": "yes", "douglas": "yes", "harlan": "yes", "brennan": "yes", "stewart": "yes", "white": "yes", "marshall": "yes", "blackmun": "yes"}}, {"id": "ins-v-chadha", "era": "The Burger Court \u00b7 October Term 1982", "caseTitle": "INS v. Chadha", "question": "May one house of Congress, by resolution alone, overturn a decision the executive branch made under authority Congress delegated?", "desc": "Jagdish Chadha was a man without a country: neither Kenya nor Britain would take him back, and in 1974 an immigration judge suspended his deportation. Under a 1952 statute either house of Congress may veto such a suspension by simple resolution, and in December 1975 the House did, with no hearing and no recorded vote. The 'legislative veto' appears in nearly two hundred federal laws, from war powers to arms sales; Congress calls it an essential check on the agencies. Chadha's lawyers call it lawmaking without a law.", "intro": "A Kenyan-born student of Indian descent overstays his visa, wins permission to remain from an immigration judge \u2014 and loses it when the House of Representatives passes a resolution, without debate, naming him.", "decided": "June 23, 1983", "split": "7\u20132", "answer": "no", "justices": [{"key": "burger", "name": "Warren Burger", "meta": "Nixon appointee (R)", "blurb": "A dozen years into the center chair, the silver-maned Chief looks the part and guards the institution's dignity above all. Conservative on crime and schools, surprisingly pragmatic elsewhere, he assigns opinions with one eye on the headlines.", "photo": "photos/burger.jpg", "chief": true}, {"key": "brennan", "name": "William Brennan", "meta": "Eisenhower appointee (R)", "blurb": "A quarter-century in, the Warren Court's great playmaker now leads a liberal wing of two or three. He still hunts the center vote in every conference, and still lands a surprising number of them \u2014 his clerks call it the rule of five.", "photo": "photos/brennan.jpg"}, {"key": "white", "name": "Byron White", "meta": "Kennedy appointee (D)", "blurb": "JFK's last appointee has hardened into the Court's flintiest pragmatist \u2014 tough on crime, dismissive of rights he cannot find in the Constitution's text, still steady on race and equal protection.", "photo": "photos/white.jpg"}, {"key": "marshall", "name": "Thurgood Marshall", "meta": "Lyndon Johnson appointee (D)", "blurb": "The civil-rights giant in winter, increasingly isolated as the Court moves right. He and Brennan vote as a pair on the death penalty and much else, filing dissent after dissent for a future Court to find.", "photo": "photos/marshall.jpg"}, {"key": "blackmun", "name": "Harry Blackmun", "meta": "Nixon appointee (R)", "blurb": "The onetime 'Minnesota Twin' has completed a long migration: the shy Nixon appointee now votes more often with Brennan and Marshall than with the Chief he grew up beside \u2014 above all on privacy and equality.", "photo": "photos/blackmun.jpg"}, {"key": "powell", "name": "Lewis Powell", "meta": "Nixon appointee (R)", "blurb": "The Court's gentle fulcrum. The courtly Richmond lawyer decides the close ones \u2014 law clerks joke that the Constitution means whatever Lewis Powell thinks it means \u2014 balancing order against liberty with a counselor's caution.", "photo": "photos/powell.jpg"}, {"key": "rehnquist", "name": "William Rehnquist", "meta": "Nixon appointee (R)", "blurb": "The Court's anchor on the right, so fond of solo dissents that his clerks once gave him a Lone Ranger doll. Federalism, law enforcement, judicial restraint: his positions never wobble \u2014 and the Court, increasingly, comes to him.", "photo": "photos/rehnquist.jpg"}, {"key": "stevens", "name": "John Paul Stevens", "meta": "Ford appointee (R)", "blurb": "The bow-tied Chicagoan defies sorting \u2014 a Ford Republican drifting toward the Court's left flank, case by idiosyncratic case. He writes more separate opinions than anyone, trusting his own reading of the law over any bloc's.", "photo": "photos/stevens.jpg"}, {"key": "oconnor", "name": "Sandra Day O'Connor", "meta": "Reagan appointee (R)", "blurb": "The newest justice and the first woman to sit on the Court, a former Arizona legislative leader sworn in last fall. She judges like a lawmaker \u2014 narrow rulings, workable compromises, close attention to the facts \u2014 and no one yet knows where she lands.", "photo": "photos/oconnor.jpg"}], "votes": {"burger": "no", "brennan": "no", "white": "yes", "marshall": "no", "blackmun": "no", "powell": "no", "rehnquist": "yes", "stevens": "no", "oconnor": "no"}}, {"id": "employment-division-v-smith", "era": "The Rehnquist Court \u00b7 October Term 1989", "caseTitle": "Employment Division v. Smith", "question": "May a state deny unemployment benefits to workers fired for using peyote in a religious ceremony?", "desc": "Alfred Smith, a Klamath Indian, and Galen Black ingested peyote \u2014 a hallucinogenic cactus and a Schedule I drug in Oregon \u2014 as the central rite of a Native American Church service, and lost their jobs at a private drug-treatment agency for it. Oregon called the firing misconduct and refused benefits. For a generation the Court has required states to show a compelling interest before burdening religious practice; twenty-three states exempt peyote worship outright. Oregon does not, and asks whether a neutral criminal law must bend to anyone's faith.", "intro": "Two drug-rehabilitation counselors in Oregon are fired for swallowing peyote at a ceremony of the Native American Church. The state denies them unemployment benefits. Their sacrament, they say, is older than the state.", "decided": "April 17, 1990", "split": "6\u20133", "answer": "yes", "justices": [{"key": "rehnquist88", "name": "William Rehnquist", "meta": "Nixon appointee (R)", "blurb": "Elevated to Chief Justice in 1986 after fifteen years as the Court's lone-wolf conservative dissenter. A states'-rights man with a genial, poker-playing manner, he now assigns the opinions and works to move the Court rightward without splintering his majorities.", "photo": "photos/rehnquist88.jpg", "chief": true}, {"key": "brennan", "name": "William Brennan", "meta": "Eisenhower appointee (R)", "blurb": "The aging architect of the Warren Court's rights revolution, now 83 and often outnumbered. The Court's great coalition-builder \u2014 'five votes can do anything around here' \u2014 he still hunts for a fifth vote wherever one can be found.", "photo": "photos/brennan.jpg"}, {"key": "white", "name": "Byron White", "meta": "Kennedy appointee (D)", "blurb": "A Kennedy appointee and former NFL halfback, gruff and unsentimental. He defies every label: hard on criminal defendants, skeptical of newly minted rights, steady on civil rights. He writes short opinions and asks no one's permission.", "photo": "photos/white.jpg"}, {"key": "marshall", "name": "Thurgood Marshall", "meta": "Lyndon Johnson appointee (D)", "blurb": "The lawyer who argued Brown v. Board of Education, now the Court's most unwavering liberal. He votes against every death sentence and speaks for the poor and powerless \u2014 increasingly in dissent, side by side with his ally Brennan.", "photo": "photos/marshall.jpg"}, {"key": "blackmun", "name": "Harry Blackmun", "meta": "Nixon appointee (R)", "blurb": "The Nixon appointee who wrote Roe v. Wade and has drifted left ever since, marked by the backlash. A meticulous former counsel to the Mayo Clinic, sensitive and deliberate, now usually found alongside Brennan and Marshall.", "photo": "photos/blackmun.jpg"}, {"key": "stevens88", "name": "John Paul Stevens", "meta": "Ford appointee (R)", "blurb": "A Ford appointee and Chicago antitrust lawyer with a bow tie and a ferociously independent streak. He follows his own analysis wherever it leads, scattering solo opinions along the way \u2014 unpredictable by design and beholden to no bloc.", "photo": "photos/stevens88.jpg"}, {"key": "oconnor88", "name": "Sandra Day O'Connor", "meta": "Reagan appointee (R)", "blurb": "The first woman on the Court, a former Arizona legislative leader who judges the way she once governed: case by case, fact by fact, wary of sweeping rules. Increasingly she is the justice both sides must persuade.", "photo": "photos/oconnor88.jpg"}, {"key": "scalia88", "name": "Antonin Scalia", "meta": "Reagan appointee (R)", "blurb": "Reagan's combative textualist, three terms on the bench and already the Court's sharpest pen. He reads constitutional text at face value wherever it points \u2014 and delights in skewering colleagues who balance interests instead.", "photo": "photos/scalia88.jpg"}, {"key": "kennedy88", "name": "Anthony Kennedy", "meta": "Reagan appointee (R)", "blurb": "The newest justice, a courtly Sacramento conservative confirmed unanimously after the Bork nomination went down in flames. Expected to be a dependable Reagan vote, but given to grand talk about liberty and the dignity of the individual.", "photo": "photos/kennedy88.jpg"}], "votes": {"rehnquist88": "yes", "brennan": "no", "white": "yes", "marshall": "no", "blackmun": "no", "stevens88": "yes", "oconnor88": "yes", "scalia88": "yes", "kennedy88": "yes"}}, {"id": "walker-v-birmingham", "era": "The Warren Court \u00b7 October Term 1966", "caseTitle": "Walker v. City of Birmingham", "question": "May marchers be punished for defying a court order against demonstrating if they never asked a court to lift it?", "desc": "A state judge forbade the marches at the city's request, citing an ordinance that let Connor deny parade permits at will. King, Abernathy, Wyatt Tee Walker and five others marched anyway, served five days for contempt, and appealed. Everyone agrees the ordinance was probably unconstitutional. The question is procedure: the city says a court order must be obeyed until a court overturns it, however wrong it may be; the ministers say they could not wait on Alabama's courts to vindicate a right the Constitution already gave them.", "intro": "Good Friday, 1963. Martin Luther King Jr. and Ralph Abernathy lead a march through Birmingham in open defiance of an injunction obtained two days earlier by Bull Connor's city. King's cell produced a famous letter; the contempt conviction produced this case.", "decided": "June 12, 1967", "split": "5\u20134", "answer": "yes", "justices": [{"key": "warren", "name": "Earl Warren", "meta": "Eisenhower appointee (R)", "blurb": "The former California governor, now the most consequential Chief Justice in a century. He asks lawyers one question \u2014 'But is it fair?' \u2014 and works the conference like the politician he never stopped being.", "photo": "photos/warren.jpg", "chief": true}, {"key": "black", "name": "Hugo Black", "meta": "Franklin Roosevelt appointee (D)", "blurb": "An Alabama New Dealer who carries the Constitution in his coat pocket and reads it literally. 'No law' means no law \u2014 but rights he cannot find in the text, he will not invent.", "photo": "photos/black.jpg"}, {"key": "douglas", "name": "William O. Douglas", "meta": "Franklin Roosevelt appointee (D)", "blurb": "A restless westerner and the Court's fastest pen \u2014 impatient with doctrine, indifferent to precedent, and instinctively on the side of the lone individual against the government in nearly any form it takes.", "photo": "photos/douglas.jpg"}, {"key": "clark", "name": "Tom C. Clark", "meta": "Truman appointee (D)", "blurb": "Truman's Attorney General in a trademark bow tie \u2014 the Court's law-and-order Texan. He backs the police and the prosecutor by instinct, but he ran federal law enforcement himself and knows its temptations from the inside.", "photo": "photos/clark.jpg"}, {"key": "harlan", "name": "John Marshall Harlan", "meta": "Eisenhower appointee (R)", "blurb": "The Wall Street patrician and grandson of a great dissenter \u2014 the Court's conservative conscience. He believes in ordered liberty and lawyerly process, and objects, elegantly, when the majority moves too far, too fast.", "photo": "photos/harlan.jpg"}, {"key": "brennan", "name": "William Brennan", "meta": "Eisenhower appointee (R)", "blurb": "The Court's Irish charmer and master coalition-builder, an Eisenhower appointee who turned out to be its most effective liberal. His first rule of the shop: with five votes, you can do anything.", "photo": "photos/brennan.jpg"}, {"key": "stewart", "name": "Potter Stewart", "meta": "Eisenhower appointee (R)", "blurb": "A moderate Ohio Republican who resists both blocs' grand theories. He decides cases one at a time, asks what the Constitution actually commands, and lands \u2014 unpredictably \u2014 somewhere in the middle.", "photo": "photos/stewart.jpg"}, {"key": "white", "name": "Byron White", "meta": "Kennedy appointee (D)", "blurb": "'Whizzer' White, the All-American halfback turned Kennedy's deputy attorney general \u2014 tough-minded, unsentimental, and skeptical of newly minted rights, especially the kind that make police work harder.", "photo": "photos/white.jpg"}, {"key": "fortas", "name": "Abe Fortas", "meta": "Lyndon Johnson appointee (D)", "blurb": "LBJ's confidant and Washington's premier lawyer, still quietly advising the President from the bench. As an advocate he won poor defendants their counsel; as a justice he champions the underdog \u2014 children included.", "photo": "photos/fortas.jpg"}], "votes": {"warren": "no", "black": "yes", "douglas": "no", "clark": "yes", "harlan": "yes", "brennan": "no", "stewart": "yes", "white": "yes", "fortas": "no"}}, {"id": "craig-v-boren", "era": "The Burger Court \u00b7 October Term 1976", "caseTitle": "Craig v. Boren", "question": "May Oklahoma let women buy 3.2 percent beer at eighteen while making men wait until twenty-one?", "desc": "Curtis Craig, an Oklahoma State student, could not buy the weak beer his female classmates bought freely; Carolyn Whitener, who sold it, faced losing her license if she served him. Oklahoma points to arrest statistics: young men are far more often picked up for drunk driving. The challengers, with Ruth Bader Ginsburg of the ACLU at counsel table, say the numbers are thin and the stereotype thick. Five years after Reed v. Reed the Justices still have no agreed standard for sex-discrimination cases; this unlikely vehicle may force one.", "intro": "A college fraternity man and the owner of the Honk n' Holler drive-in in Stillwater, Oklahoma, go to the Supreme Court over near beer \u2014 and over how hard the Constitution looks at laws that sort people by sex.", "decided": "December 20, 1976", "split": "7\u20132", "answer": "no", "justices": [{"key": "burger", "name": "Warren Burger", "meta": "Nixon appointee (R)", "blurb": "Nixon's chief justice, installed to steady a Court he believes ran wild under Earl Warren. A stickler for order and the dignity of institutions, he is more cautious conservative than crusader \u2014 and ever mindful of the Court's public standing.", "photo": "photos/burger.jpg", "chief": true}, {"key": "brennan", "name": "William Brennan", "meta": "Eisenhower appointee (R)", "blurb": "Twenty years on, the great liberal playmaker works a Court that has drifted away from him. He still counts to five better than anyone alive, hunting the center for partners case by case.", "photo": "photos/brennan.jpg"}, {"key": "stewart", "name": "Potter Stewart", "meta": "Eisenhower appointee (R)", "blurb": "The Court's studied centrist, a judge of narrow rulings and practical lines. Eighteen years in, he remains the man both blocs court \u2014 skeptical of absolutes, attentive to how the law actually operates.", "photo": "photos/stewart.jpg"}, {"key": "white", "name": "Byron White", "meta": "Kennedy appointee (D)", "blurb": "The Kennedys' deputy attorney general, an All-America halfback turned no-nonsense pragmatist. Tough on crime and skeptical of newly minted rights, yet often found with the liberals on race and civil rights.", "photo": "photos/white.jpg"}, {"key": "marshall", "name": "Thurgood Marshall", "meta": "Lyndon Johnson appointee (D)", "blurb": "The architect of Brown v. Board and the Court's first Black justice. He judges from lived experience \u2014 Jim Crow courtrooms, clients facing the electric chair \u2014 and defends the poor and powerless with unembarrassed consistency.", "photo": "photos/marshall.jpg"}, {"key": "blackmun", "name": "Harry Blackmun", "meta": "Nixon appointee (R)", "blurb": "The Mayo Clinic's meticulous former counsel, an anxious drafter who agonizes over every case. Once dismissed as Burger's 'Minnesota Twin,' he is drifting from the Chief, case by case, toward a path of his own.", "photo": "photos/blackmun.jpg"}, {"key": "powell", "name": "Lewis Powell", "meta": "Nixon appointee (R)", "blurb": "The courtly Richmond lawyer has settled into the Court's center seat, a balancer who distrusts bright lines and sweeping theories alike. He weighs each case like a client matter, writes with a counselor's caution, and seldom finds himself in dissent.", "photo": "photos/powell.jpg"}, {"key": "rehnquist", "name": "William Rehnquist", "meta": "Nixon appointee (R)", "blurb": "The Court's most unapologetic conservative, a brilliant and cheerful writer who would rather dissent alone than join an opinion he doubts. States' rights, law enforcement, judicial restraint \u2014 his compass never wavers, whatever the company.", "photo": "photos/rehnquist.jpg"}, {"key": "stevens", "name": "John Paul Stevens", "meta": "Ford appointee (R)", "blurb": "The newest justice, a bow-tied Chicago antitrust lawyer chosen by Gerald Ford for sheer legal craftsmanship. He belongs to no bloc, writes separate opinions constantly, and steers by his own idiosyncratic compass.", "photo": "photos/stevens.jpg"}], "votes": {"burger": "yes", "brennan": "no", "stewart": "no", "white": "no", "marshall": "no", "blackmun": "no", "powell": "no", "rehnquist": "yes", "stevens": "no"}}, {"id": "brandenburg-v-ohio", "era": "The Warren Court \u00b7 October Term 1968", "caseTitle": "Brandenburg v. Ohio", "question": "May a state punish a speaker for advocating violence in general terms, without inciting imminent lawless action?", "desc": "Clarence Brandenburg, a Klan leader, invited the reporter himself; the footage shows guns, slurs against Black Americans and Jews, and talk of marching on Congress on the Fourth of July. He drew one to ten years and a $1,000 fine for advocating 'the duty, necessity, or propriety' of violence as a means of reform. The Court upheld an identical California statute in 1927, over Brandeis's famous protest. The ACLU argues his case; the question is what is left of the clear-and-present-danger test after two decades of Cold War prosecutions.", "intro": "A Cincinnati television crew films a Ku Klux Klan rally on a farm outside town: a dozen hooded figures, a burning cross, and a leader promising 'revengeance' if Washington keeps suppressing the white race. Ohio convicts him under a 1919 syndicalism law.", "decided": "June 9, 1969", "split": "8\u20130", "answer": "no", "justices": [{"key": "warren", "name": "Earl Warren", "meta": "Eisenhower appointee (R)", "blurb": "The former California governor, now the most consequential Chief Justice in a century. He asks lawyers one question \u2014 'But is it fair?' \u2014 and works the conference like the politician he never stopped being.", "photo": "photos/warren.jpg", "chief": true}, {"key": "black", "name": "Hugo Black", "meta": "Franklin Roosevelt appointee (D)", "blurb": "An Alabama New Dealer who carries the Constitution in his coat pocket and reads it literally. 'No law' means no law \u2014 but rights he cannot find in the text, he will not invent.", "photo": "photos/black.jpg"}, {"key": "douglas", "name": "William O. Douglas", "meta": "Franklin Roosevelt appointee (D)", "blurb": "A restless westerner and the Court's fastest pen \u2014 impatient with doctrine, indifferent to precedent, and instinctively on the side of the lone individual against the government in nearly any form it takes.", "photo": "photos/douglas.jpg"}, {"key": "harlan", "name": "John Marshall Harlan", "meta": "Eisenhower appointee (R)", "blurb": "The Wall Street patrician and grandson of a great dissenter \u2014 the Court's conservative conscience. He believes in ordered liberty and lawyerly process, and objects, elegantly, when the majority moves too far, too fast.", "photo": "photos/harlan.jpg"}, {"key": "brennan", "name": "William Brennan", "meta": "Eisenhower appointee (R)", "blurb": "The Court's Irish charmer and master coalition-builder, an Eisenhower appointee who turned out to be its most effective liberal. His first rule of the shop: with five votes, you can do anything.", "photo": "photos/brennan.jpg"}, {"key": "stewart", "name": "Potter Stewart", "meta": "Eisenhower appointee (R)", "blurb": "A moderate Ohio Republican who resists both blocs' grand theories. He decides cases one at a time, asks what the Constitution actually commands, and lands \u2014 unpredictably \u2014 somewhere in the middle.", "photo": "photos/stewart.jpg"}, {"key": "white", "name": "Byron White", "meta": "Kennedy appointee (D)", "blurb": "'Whizzer' White, the All-American halfback turned Kennedy's deputy attorney general \u2014 tough-minded, unsentimental, and skeptical of newly minted rights, especially the kind that make police work harder.", "photo": "photos/white.jpg"}, {"key": "marshall", "name": "Thurgood Marshall", "meta": "Lyndon Johnson appointee (D)", "blurb": "The architect of the NAACP's litigation war on Jim Crow and the first Black justice \u2014 a storyteller who has seen the criminal law from the defendant's side of the table and never forgets it.", "photo": "photos/marshall.jpg"}], "votes": {"warren": "no", "black": "no", "douglas": "no", "harlan": "no", "brennan": "no", "stewart": "no", "white": "no", "marshall": "no"}}, {"id": "baker-v-carr", "era": "The Warren Court \u00b7 October Term 1961", "caseTitle": "Baker v. Carr", "question": "May federal courts hear a claim that a state's legislative districts are so unequal they deny equal protection?", "desc": "Charles Baker, a Republican county judge from suburban Memphis, sues Tennessee's secretary of state over a legislature frozen in the farm era: cities have grown for sixty years while their seats have not. The lower court threw the case out under Colegrove v. Green, where Frankfurter warned judges to stay out of the 'political thicket' of districting. Solicitor General Archibald Cox argues for the voters. The case has been argued twice and the conference is split down the middle; whatever the Court says will reach every statehouse in America.", "intro": "Tennessee has not redrawn its legislative map since 1901. A vote in rural Moore County now counts nineteen times a vote in Memphis, and the legislature that benefits will never fix it. Memphis voters ask a federal court to step in.", "decided": "March 26, 1962", "split": "6\u20132", "answer": "yes", "justices": [{"key": "warren", "name": "Earl Warren", "meta": "Eisenhower appointee (R)", "blurb": "The former California governor, now the most consequential Chief Justice in a century. He asks lawyers one question \u2014 'But is it fair?' \u2014 and works the conference like the politician he never stopped being.", "photo": "photos/warren.jpg", "chief": true}, {"key": "black", "name": "Hugo Black", "meta": "Franklin Roosevelt appointee (D)", "blurb": "An Alabama New Dealer who carries the Constitution in his coat pocket and reads it literally. 'No law' means no law \u2014 but rights he cannot find in the text, he will not invent.", "photo": "photos/black.jpg"}, {"key": "frankfurter", "name": "Felix Frankfurter", "meta": "Franklin Roosevelt appointee (D)", "blurb": "The former Harvard professor and apostle of judicial restraint: courts, he preaches, must defer to legislatures even when the results offend. His seminars continue at conference, whether his colleagues want them or not.", "photo": "photos/frankfurter.jpg"}, {"key": "douglas", "name": "William O. Douglas", "meta": "Franklin Roosevelt appointee (D)", "blurb": "A restless westerner and the Court's fastest pen \u2014 impatient with doctrine, indifferent to precedent, and instinctively on the side of the lone individual against the government in nearly any form it takes.", "photo": "photos/douglas.jpg"}, {"key": "clark", "name": "Tom C. Clark", "meta": "Truman appointee (D)", "blurb": "Truman's Attorney General in a trademark bow tie \u2014 the Court's law-and-order Texan. He backs the police and the prosecutor by instinct, but he ran federal law enforcement himself and knows its temptations from the inside.", "photo": "photos/clark.jpg"}, {"key": "harlan", "name": "John Marshall Harlan", "meta": "Eisenhower appointee (R)", "blurb": "The Wall Street patrician and grandson of a great dissenter \u2014 the Court's conservative conscience. He believes in ordered liberty and lawyerly process, and objects, elegantly, when the majority moves too far, too fast.", "photo": "photos/harlan.jpg"}, {"key": "brennan", "name": "William Brennan", "meta": "Eisenhower appointee (R)", "blurb": "The Court's Irish charmer and master coalition-builder, an Eisenhower appointee who turned out to be its most effective liberal. His first rule of the shop: with five votes, you can do anything.", "photo": "photos/brennan.jpg"}, {"key": "stewart", "name": "Potter Stewart", "meta": "Eisenhower appointee (R)", "blurb": "A moderate Ohio Republican who resists both blocs' grand theories. He decides cases one at a time, asks what the Constitution actually commands, and lands \u2014 unpredictably \u2014 somewhere in the middle.", "photo": "photos/stewart.jpg"}], "votes": {"warren": "yes", "black": "yes", "frankfurter": "no", "douglas": "yes", "clark": "yes", "harlan": "no", "brennan": "yes", "stewart": "yes"}}, {"id": "san-antonio-v-rodriguez", "era": "The Burger Court \u00b7 October Term 1972", "caseTitle": "San Antonio Independent School District v. Rodriguez", "question": "Does funding public schools through local property taxes, which leaves poor districts with far less per pupil, violate the Equal Protection Clause?", "desc": "Demetrio Rodriguez's children attend Edgewood schools where the roof leaks, many teachers are uncertified and the district spends $356 per pupil; across town, Alamo Heights spends $594 at a lower tax rate, because its homes are worth so much more. Texas, like nearly every state, finances schools largely from local property wealth. A three-judge federal court found the system unconstitutional. If the Justices agree, school finance in forty-nine states must be rebuilt \u2014 and they must decide whether education is a fundamental right and the poor a specially protected class.", "intro": "Two San Antonio school districts a few miles apart: Edgewood taxes itself at the highest rate in the county and raises a fraction of what Alamo Heights spends on each child. A sheet-metal worker sues.", "decided": "March 21, 1973", "split": "5\u20134", "answer": "no", "justices": [{"key": "burger", "name": "Warren Burger", "meta": "Nixon appointee (R)", "blurb": "Nixon's chief justice, installed to steady a Court he believes ran wild under Earl Warren. A stickler for order and the dignity of institutions, he is more cautious conservative than crusader \u2014 and ever mindful of the Court's public standing.", "photo": "photos/burger.jpg", "chief": true}, {"key": "douglas", "name": "William O. Douglas", "meta": "Franklin Roosevelt appointee (D)", "blurb": "A New Deal wunderkind grown into the Court's absolutist loner \u2014 three decades on the bench, four wives, a shelf of his own books. He votes for the individual against the government almost reflexively, and writes opinions at breakneck speed.", "photo": "photos/douglas.jpg"}, {"key": "brennan", "name": "William Brennan", "meta": "Eisenhower appointee (R)", "blurb": "The Warren Court's master coalition-builder, an Eisenhower appointee turned architect of its liberal revolution. His first rule \u2014 with five votes you can do anything \u2014 still guides him as the bench tilts rightward around him.", "photo": "photos/brennan.jpg"}, {"key": "stewart", "name": "Potter Stewart", "meta": "Eisenhower appointee (R)", "blurb": "A pragmatic Ohio Republican wary of grand theory, he decides cases narrowly and one at a time. Neither wing can count on him: he distrusts government overreach and judicial adventure in roughly equal measure.", "photo": "photos/stewart.jpg"}, {"key": "white", "name": "Byron White", "meta": "Kennedy appointee (D)", "blurb": "The Kennedys' deputy attorney general, an All-America halfback turned no-nonsense pragmatist. Tough on crime and skeptical of newly minted rights, yet often found with the liberals on race and civil rights.", "photo": "photos/white.jpg"}, {"key": "marshall", "name": "Thurgood Marshall", "meta": "Lyndon Johnson appointee (D)", "blurb": "The architect of Brown v. Board and the Court's first Black justice. He judges from lived experience \u2014 Jim Crow courtrooms, clients facing the electric chair \u2014 and defends the poor and powerless with unembarrassed consistency.", "photo": "photos/marshall.jpg"}, {"key": "blackmun", "name": "Harry Blackmun", "meta": "Nixon appointee (R)", "blurb": "The junior justice, a shy Minnesota Republican and longtime counsel to the Mayo Clinic. Washington calls him and his boyhood friend the Chief the 'Minnesota Twins' \u2014 so far he votes Burger's way more often than not.", "photo": "photos/blackmun.jpg"}, {"key": "powell", "name": "Lewis Powell", "meta": "Nixon appointee (R)", "blurb": "A courtly Richmond corporate lawyer and former ABA president, newly arrived on the bench. The establishment's ideal judge: moderate, balancing, allergic to extremes \u2014 he weighs each case like a client matter and lands, usually, near the center.", "photo": "photos/powell.jpg"}, {"key": "rehnquist", "name": "William Rehnquist", "meta": "Nixon appointee (R)", "blurb": "The junior justice and its boldest conservative \u2014 a 47-year-old Nixon Justice Department lawyer with a brilliant pen and no fear of standing alone. He doubts much of what the Warren Court built.", "photo": "photos/rehnquist.jpg"}], "votes": {"burger": "no", "douglas": "yes", "brennan": "yes", "stewart": "no", "white": "yes", "marshall": "yes", "blackmun": "no", "powell": "no", "rehnquist": "no"}}]};